values ('iso45001@1', 'iso45001', 1, '{"de":"ISO 45001 Gap-Analyse","en":"ISO 45001 Gap Assessment"}'::jsonb, '[{"key":"c4","label":"4","title":{"de":"Kontext der Organisation","en":"Context of the organization"},"groups":[]},{"key":"c5","label":"5","title":{"de":"Führung","en":"Leadership"},"groups":[]},{"key":"c6","label":"6","title":{"de":"Planung","en":"Planning"},"groups":[]},{"key":"c7","label":"7","title":{"de":"Unterstützung","en":"Support"},"groups":[]},{"key":"c8","label":"8","title":{"de":"Betrieb","en":"Operation"},"groups":[]},{"key":"c9","label":"9","title":{"de":"Bewertung der Leistung","en":"Performance Evaluation"},"groups":[]},{"key":"c10","label":"10","title":{"de":"Verbesserung","en":"Improvement"},"groups":[]}]'::jsonb, 60, 'Built from iso45001_assessment.html ("ISO 45001 Gap Assessment"), export dated 2026-09-12.')
