insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/1', 'iso45001@1', 1, null, 'c4', null, '4.1', true, '{"de":"Verstehen der Organisation und ihres Kontextes","en":"Understanding the organization and its context"}'::jsonb, '{"de":"Bestimmen Sie die externen und internen Themen, die für den Zweck und die strategische Ausrichtung relevant sind und die die Fähigkeit beeinflussen, das (die) beabsichtigte(n) Ergebnis(se) des OH&S-Managementsystems zu erreichen.","en":"Determine the external and internal issues that are relevant to the purpose and strategic direction and that affect the ability to achieve the intended result(s) of the OH&S management system."}'::jsonb, '{"de":"Hat die Organisation externe und interne Themen bestimmt, die für ihren Zweck relevant sind und die ihre Fähigkeit beeinflussen, das (die) beabsichtigte(n) Ergebnis(se) ihres OH&S-Managementsystems zu erreichen?\n\nAchten Sie auf: Nachweise für eine laufende Überprüfung, Diskussionen, Massnahmen und die Klärung dieser Themen?","en":"Has the organization determined external and internal issues that are relevant to its purpose and that affect its ability to achieve the intended outcome(s) of its OH&S Management System?\n\nLook for: evidence of ongoing review, discussions, actions, and resolution of these issues?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/2', 'iso45001@1', 2, null, 'c4', null, '4.2', true, '{"de":"Verstehen der Erfordernisse und Erwartungen der Beschäftigten und anderer interessierter Parteien","en":"Understanding the needs and expectations of interested parties"}'::jsonb, '{"de":"Bestimmen Sie die interessierten Parteien, die zusätzlich zu den Beschäftigten für das OH&S-Managementsystem relevant sind; die relevanten Erfordernisse und Erwartungen der Beschäftigten und anderer interessierter Parteien; welche dieser Erfordernisse und Erwartungen rechtliche Verpflichtungen und andere Anforderungen sind oder werden könnten.","en":"Determine the interested parties, in addition to workers, that are relevant to the OH&S management system; the relevant needs and expectations of workers and other interested parties; which of these needs and expectations are, or could become, legal requirements and other requirements."}'::jsonb, '{"de":"Hat die Organisation die INTERESSIERTEN PARTEIEN und deren Anforderungen bestimmt?\n\nÜberprüfen Sie, ob die Organisation die interessierten Parteien und deren Anforderungen überwacht und überprüft, während sich diese im Laufe der Zeit ändern.\n\nAchten Sie auf: Nachweise in Plänen, Strategiedokumenten und Sitzungsprotokollen.","en":"Has the organization determined INTERESTED PARTIES and their requirements?\n\nVerify that the organization monitors and reviews the interested parties and their requirements as they change over time.\n\nLook for: evidence in plans, strategy documents, and meeting minutes."}'::jsonb, false)
