insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/3', 'iso45001@1', 3, null, 'c4', null, '4.3', true, '{"de":"Festlegen des Anwendungsbereichs des OH&S-Managementsystems","en":"Determining the scope of the OH&S management system"}'::jsonb, '{"de":"Bestimmen Sie die Grenzen und die Anwendbarkeit des OH&S-Managementsystems, um dessen Anwendungsbereich festzulegen, unter Berücksichtigung von:\nexternen und internen Themen;\nAnforderungen relevanter interessierter Parteien;\ngeplanten oder durchgeführten arbeitsbezogenen Tätigkeiten.\nDer Anwendungsbereich ist als dokumentierte Information verfügbar und wird aufrechterhalten, wobei Folgendes anzugeben ist:\ndie vom OH&S-Managementsystem abgedeckten Tätigkeiten, Produkte und Dienstleistungen;\ndie Begründung für jeden Fall, in dem eine Anforderung der ISO 45001:2018 nicht angewendet werden kann.","en":"Determine the boundaries and applicability of the OH&S management system to establish the scope, considering:\nexternal and internal issues;\nrequirements of relevant interested parties;\nplanned or performed work-related activities.\nThe scope is available and maintained as documented information stating the:\nactivities, products and services covered by the OH&S management system;\njustification for any instance where a requirement of ISO 45001:2018 cannot be applied."}'::jsonb, '{"de":"Falls bereits ein OH&S-Managementsystem vorhanden ist, überprüfen Sie, ob dessen Anwendungsbereich festgelegt und intern sowie extern kommuniziert ist.\n\nÜberprüfen Sie, ob die Erklärung zum Anwendungsbereich noch anwendbar und zutreffend ist.\n\nAchten Sie auf: Nachweise in Strategiepläne, Katalogen, Websites oder Zertifikaten der Zertifizierungsstelle.","en":"If a OH&S Management System is already in place, verify that its scope is defined, communicated internally and externally.\n\nVerify that the scope statement is still applicable and accurate.\n\nLook for: evidence in strategic plans, catalogs,  websites, or registrar certificates."}'::jsonb, false)
