insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/6', 'iso45001@1', 6, null, 'c5', null, '5.2', true, '{"de":"Politik","en":"Policy"}'::jsonb, '{"de":"Eine OH&S-Politik festlegen, umsetzen und aufrechterhalten, die:\n• eine Verpflichtung zur Bereitstellung sicherer und gesunder Arbeitsbedingungen zur Verhütung von arbeitsbedingten Verletzungen und Erkrankungen enthält und dem Zweck, der Grösse und dem Kontext der Organisation sowie der spezifischen Art ihrer OH&S-Risiken und OH&S-Chancen angemessen ist;\n• einen Rahmen für die Festlegung von OH&S-Zielen bietet;\n• eine Verpflichtung zur Erfüllung rechtlicher Verpflichtungen und anderer Anforderungen enthält;\n• eine Verpflichtung zur Beseitigung von Gefährdungen und zur Minderung von OH&S-Risiken enthält;\n• eine Verpflichtung zur fortlaufenden Verbesserung des OH&S-Managementsystems enthält;\n• eine Verpflichtung zur Konsultation und Beteiligung der Beschäftigten und, sofern vorhanden, der Beschäftigtenvertreter enthält.\n\n• Unsere OH&S-Politik ist:\no  als dokumentierte Information verfügbar;\no  innerhalb der Organisation kommuniziert;\no  interessierten Parteien, sofern angemessen, zugänglich;\no  relevant und angemessen.","en":"Establish, implement and maintain an OHSMS policy that:\n• Includes a commitment to provide safe and healthy working conditions for the prevention of work-related injury and ill health and is appropriate to the purpose, size and context of the organization and to the specific nature of its OH&S risks and OH&S opportunities;\n• provides a framework for setting OH&S objectives;\n• includes a commitment to fulfil legal requirements and other requirements;\n• includes a commitment to eliminate hazards and reduce OH&S risks;\n• includes a commitment to continual improvement of the OH&S management system.\n• Includes a commitment to consultation and participation of workers, and, where they exist workers’ representatives.\n\n• Our OH&S policy is:\no  available as documented information;\no  communicated within the organization;\no  available to interested parties, as appropriate;\no  relevant and appropriate."}'::jsonb, '{"de":"Gibt es eine POLITIK zu Arbeitssicherheit und Gesundheitsschutz und erfüllt diese die Anforderungen der Norm? Unterstützt sie die Strategie des Unternehmens und beinhaltet sie die Verpflichtung, Anforderungen zu erfüllen und die OH&S-Leistung fortlaufend zu verbessern?\n\nWird die Politik den interessierten Parteien kommuniziert? Ist sie intern ausgehängt? Ist sie für interessierte Parteien verfügbar?\n\nAchten Sie auf: OH&S-Politik, Kommunikation zu OH&S in Form von E-Mails, Aushängen, Präsentationen, Sitzungsprotokollen.","en":"Is there an Occupational Health & Safety POLICY and does it meet the requirements of the standard?  Does it support the strategy for the company and commit to meeting requirements and continually improving OH&S performance?\n\nIs the Policy communicated to interested parties? Is it internally posted. Is it available to interested parties?\n\nLook for: OH&S policy, communications about OH&S in for the form of emails, postings, presentations, meeting minutes."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/7', 'iso45001@1', 7, null, 'c5', null, '5.3', true, '{"de":"Rollen, Verantwortlichkeiten und Befugnisse in der Organisation","en":"Organizational roles, responsibilities and authorities"}'::jsonb, '{"de":"Sicherstellen, dass die Verantwortlichkeiten und Befugnisse für massgebliche Rollen innerhalb des OH&S-Managementsystems auf allen Ebenen der Organisation zugewiesen und kommuniziert sowie als dokumentierte Information aufrechterhalten werden. Beschäftigte auf jeder Ebene der Organisation sollen die Verantwortung für diejenigen Aspekte des OH&S-Managementsystems übernehmen, über die sie Kontrolle haben.\nDie oberste Leitung soll die Verantwortung und Befugnis zuweisen für:\n• das Sicherstellen, dass das OH&S-Managementsystem den Anforderungen dieses Dokuments entspricht;\n• das Berichten über die Leistung des OH&S-Managementsystems an die oberste Leitung.","en":"Ensure that the responsibilities and authorities for relevant roles within the OH&S management system are assigned and communicated at all levels within the organization and maintained as documented information.  Workers at each level of the organization shall assume responsibility for those aspects of the OH&S management system over which they have control.\nTop management shall assign the responsibility and authority for:\n• ensuring that it the OH&S management system conforms to the requirements of this document;\n• reporting on its performance of the OH&S management system to top management."}'::jsonb, '{"de":"Wurden die organisatorischen ROLLEN, VERANTWORTLICHKEITEN UND BEFUGNISSE angemessen zugewiesen, mit Ressourcen ausgestattet und kommuniziert?\n\nAchten Sie auf: Organigramme, strategische oder operative Pläne, Sitzungsagenden und -protokolle, Kommunikationstafeln und -mitteilungen,","en":"Have the organizational ROLES, RESPONSIBILITIES & AUTHORITIES been appropriately assigned, resourced and communicated?\n\nLook for: Organization charts, strategic or operational plans, meeting agendas and minutes, communications boards and messaging,"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/8', 'iso45001@1', 8, null, 'c5', null, '5.4', true, '{"de":"Konsultation und Beteiligung der Beschäftigten","en":"Consultation and Participation of workers"}'::jsonb, '{"de":"Einen Prozess für die Konsultation und Beteiligung der Beschäftigten auf allen Ebenen und Funktionen sowie, sofern vorhanden, der Beschäftigtenvertreter bei der Entwicklung, Planung, Umsetzung, Leistungsbewertung und den Massnahmen zur Verbesserung des OH&S-Managementsystems festlegen, umsetzen und aufrechterhalten; die erforderlichen Mechanismen, Zeit, Schulung und Ressourcen bereitstellen; rechtzeitigen Zugang zu klaren und relevanten Informationen gewähren; Hindernisse für die Beteiligung beseitigen oder minimieren; die Konsultation nicht leitender Beschäftigter zu den in 5.4 d) aufgeführten Angelegenheiten und ihre Beteiligung an den in 5.4 e) aufgeführten Angelegenheiten besonders betonen.","en":"Establish, implement and maintain a process for consultation and participation of workers at all levels and functions, and of workers'' representatives where they exist, in the development, planning, implementation, performance evaluation and actions for improvement of the OH&S management system; provide the mechanisms, time, training and resources needed; give timely access to clear and relevant information; remove or minimise barriers to participation; emphasise the consultation of non managerial workers on the matters listed in 5.4 d) and their participation in those listed in 5.4 e)."}'::jsonb, '{"de":"Gibt es einen wirksamen Prozess für die Konsultation und Beteiligung der Beschäftigten auf allen Ebenen und Funktionen sowie, sofern vorhanden, der Beschäftigtenvertreter (5.4 a-c)?\n\nLegt die Organisation besonderen Wert auf die Konsultation nicht leitender Beschäftigter gemäss (5.4 d)?\n\nAchten Sie auf: Anwesenheitsaufzeichnungen von Sitzungen, Sitzungsagenden und -protokolle, Kommunikationstafeln und -mitteilungen,","en":"Is there an effective process for consultation & participation of workers at all levels and functions, and where they exist workers’ representatives (5.4 a-c)?\n\nDoes the organization have emphasis of consultation with non-managerial workers per (5.4.d)?\n\nLook for: Meeting attendance records, meeting agendas and minutes, communications boards and messaging,"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/9', 'iso45001@1', 9, null, 'c6', null, '6.1.1', true, '{"de":"Massnahmen zum Umgang mit Risiken und Chancen / Allgemeines","en":"Actions to address risks and opportunities / General"}'::jsonb, '{"de":"Bei der Planung für das OH&S-Managementsystem sind die Themen (4.1) und die Anforderungen (4.2) und (4.3) zu berücksichtigen, und es sind die Risiken und Chancen zu bestimmen, die behandelt werden müssen, um:\n• sicherzustellen, dass das OH&S-Managementsystem seine(n) beabsichtigte(n) Ergebnis(se) erreichen kann;\n• unerwünschte Auswirkungen zu verhindern oder zu verringern;\n• eine fortlaufende Verbesserung zu erreichen.\nBei der Bestimmung der Risiken und Chancen für das OH&S-Managementsystem und dessen beabsichtigte Ergebnisse, die behandelt werden müssen, muss die Organisation Folgendes berücksichtigen:\n• Gefährdungen;\n• OH&S-Risiken und andere Risiken;\n• OH&S-Chancen und andere Chancen;\n• rechtliche Verpflichtungen und andere Anforderungen.\n\nDie Organisation muss in ihrem(n) Planungsprozess(en) die Risiken und Chancen bestimmen und bewerten, die für die beabsichtigten Ergebnisse des OH&S-Managementsystems relevant sind und die mit Änderungen der Organisation, ihrer Prozesse oder des OH&S-Managementsystems zusammenhängen. Im Falle geplanter Änderungen, dauerhaft oder vorübergehend, muss diese Bewertung durchgeführt werden, bevor die Änderung umgesetzt wird.\n\nDie Organisation muss dokumentierte Information aufbewahren über:\n• die Risiken und Chancen;\n• den(die) Prozess(e) und die Massnahmen, die notwendig sind, um ihre Risiken und Chancen zu bestimmen und zu behandeln, in dem Umfang, der notwendig ist, um Vertrauen darauf zu haben, dass sie wie geplant durchgeführt werden.","en":"When planning for the OHSMS, consider the issues (4.1) and the requirements (4.2) and (4.3), and determine the risks and opportunities that need to be addressed to:\n• assure that the OHSMS can achieve its intended result(s);\n• prevent, or reduce, undesired effects;\n• achieve continual improvement.\nWhen determining the risks and opportunities for the OH&S management system and its intended outcomes that need to be addressed, the organization shall take into account:\n• hazards;\n• OH&S risks and other risks;\n• OH&S opportunities and other opportunities;\n• Legal requirements and other requirements.\n\nThe organization, in its planning process(es), shall determine and assess the risks and opportunities that are relevant to the intended outcomes of the OH&S management system associated with changes in the organization, its processes or the OH&S management system. In the case of planned changes, permanent or temporary, this assessment shall be undertaken before the change is implemented.\n\nThe organization shall maintain documented information on:\n• Risks and opportunities\n• The process(es) and actions needed to determine and address its risks and opportunities to the extent necessary to have confidence that they are carried out as planned."}'::jsonb, '{"de":"Nachweis, dass RISIKEN UND CHANCEN im Zusammenhang mit OH&S-Gefährdungen und -Risiken, Compliance-Verpflichtungen und anderen Themen ermittelt und behandelt wurden\n\nAchten Sie auf: Strategische Pläne, Betriebspläne, Risikobeurteilungen sowie zugehörige Entscheidungen und Massnahmen.","en":"Evidence that RISKS AND OPPPORTUNITIES related to OH&S hazards & risks, compliance obligations and other issues have been identified and addressed\n\nLook for: Strategic plans, operating plans, risk assessments,  and related decisions and actions."}'::jsonb, false)
