values ('iso45001@1/10', 'iso45001@1', 10, null, 'c6', null, '6.1.2.1', true, '{"de":"Ermittlung von Gefährdungen","en":"Hazard identification"}'::jsonb, '{"de":"Einen Prozess für die laufende, proaktive Ermittlung entstehender Gefährdungen festlegen, umsetzen und aufrechterhalten.","en":"Establish, implement, and maintain a process for the on-going proactive identification of hazards arising."}'::jsonb, '{"de":"Hat die Organisation einen Prozess für die Ermittlung von Gefährdungen festgelegt, umgesetzt und aufrechterhalten, der laufend und proaktiv ist? Falls ja, siehe Anhang A und tragen Sie hier die abschliessenden Ergebnisse ein","en":"Has the organization established, implemented & maintained a process for hazard identification that is on-going and proactive? If yes see Annex A and enter final results here"}'::jsonb, false)
