insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/29', 'iso45001@1', 29, null, 'c6', null, '6.1.3', true, '{"de":"Bestimmen von rechtlichen Verpflichtungen und anderen Anforderungen","en":"Determination of legal requirements and other requirements"}'::jsonb, '{"de":"Einen Prozess festlegen, umsetzen und aufrechterhalten, um:\n\n• die aktuellen rechtlichen Verpflichtungen und anderen Anforderungen, denen sich die Organisation unterstellt und die auf ihre Gefährdungen und OH&S-Risiken anwendbar sind, zu bestimmen und Zugang dazu zu haben;\n\n• zu bestimmen, wie diese rechtlichen Verpflichtungen und anderen Anforderungen für die Organisation gelten und was kommuniziert werden muss (siehe 7.4);\n\n• diese rechtlichen Verpflichtungen und anderen Anforderungen bei der Festlegung, Umsetzung, Aufrechterhaltung und fortlaufenden Verbesserung ihres OH&S-Managementsystems zu berücksichtigen.\n\nDie Organisation muss dokumentierte Information über ihre anwendbaren rechtlichen Verpflichtungen und anderen Anforderungen aufrechterhalten und aufbewahren und sicherstellen, dass diese aktualisiert wird, um Änderungen widerzuspiegeln.","en":"Establish, implement, and maintain a process to:\n\n• determine and have access to up-to-date legal requirements and other requirements to which the organization subscribes that are applicable to its hazards and OH&S risks;\n\n• determine how these legal requirements and other requirements apply to the organization and what needs to be communicated (see 7.4);\n\n• take these legal requirements and other requirements into account when establishing, implementing maintaining and continually improving its OH&S management system.\n\nThe organization shall maintain and retain documented information on its applicable legal requirements and other requirements and shall ensure that it is updated to reflect any changes."}'::jsonb, '{"de":"Gibt es einen Prozess zur Bestimmung von RECHTLICHEN VERPFLICHTUNGEN & anderen Anforderungen für OH&S?\n\nAchten Sie auf: Liste rechtlicher oder anderer Anforderungen, OHSHA- oder behördliche Dokumentation oder Compliance-Pläne.","en":"Is there a process for the Determination of LEGAL REQUIREMENTS & Other Requirements for OH&S?\n\nLook for: list of legal or other requirements, OHSHA or government documentation or compliance plans."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/30', 'iso45001@1', 30, null, 'c6', null, '6.1.4', true, '{"de":"Planen von Massnahmen","en":"Planning action"}'::jsonb, '{"de":"Planen von:\n\n• Massnahmen, um:\n\no  diese Risiken und Chancen zu behandeln (siehe 6.1.2.3 und 6.1.2.4);\n\no  anwendbare rechtliche Verpflichtungen und andere Anforderungen zu behandeln (siehe 6.1.3);\n\no  sich auf Notfallsituationen vorzubereiten und auf diese zu reagieren (siehe 8.6);\n\n• wie:\n\no  die Massnahmen in die Prozesse ihres OH&S-Managementsystems oder andere Geschäftsprozesse integriert und umgesetzt werden;\n\no  die Wirksamkeit dieser Massnahmen bewertet wird.\n\nDie Organisation muss die Massnahmenhierarchie (siehe 8.1.2) und Ergebnisse aus dem OH&S-Managementsystem (siehe 10.2.2) bei der Planung von Massnahmen berücksichtigen.\n\nBei der Planung ihrer Massnahmen muss die Organisation bewährte Praktiken, technologische Optionen sowie finanzielle, betriebliche und geschäftliche Anforderungen und Einschränkungen berücksichtigen.","en":"Plan:\n\n• actions to:\n\no  address these risks and opportunities (see 6.1.2.3 and 6.1.2.4);\n\no  address applicable legal requirements and other requirements (see 6.1.3);\n\no  prepare for, and respond to, emergency situations (see 8.6);\n\n• How to\n\no  integrate and implement the actions into its OH&S management system processes or          other business processes;\n\no  Evaluate the effectiveness of these actions.\n\nThe organization shall take into account the hierarchy of controls (see 8.1.2) and outputs from the OH&S management system (see 10.2.2) when planning to take action.\n\nWhen planning its actions, the organization shall consider best practices, technological options, financial, operational, and business requirements and constraints."}'::jsonb, '{"de":"Hat die Organisation Massnahmen geplant? (6.1.4.) Falls ja, siehe Anhang B und tragen Sie die endgültigen Ergebnisse hier ein.","en":"Has the organization planned actions? (6.1.4.) If yes, see Annex B and enter final esults here."}'::jsonb, false)
