values ('iso45001@1/39', 'iso45001@1', 39, 'iso45001@1/30', 'c6', null, 'B.9', true, '{"de":"Bei der Planung ihrer Massnahmen muss die Organisation bewährte Praktiken, technologische Optionen und finanzielle, betriebliche und geschäftliche Anforderungen berücksichtigen.","en":"When planning its actions, the organization shall consider best practices, technological options and financial, operational and business requirements."}'::jsonb, null, '{"de":"Bei der Planung ihrer Massnahmen muss die Organisation bewährte Praktiken, technologische Optionen und finanzielle, betriebliche und geschäftliche Anforderungen berücksichtigen.","en":"When planning its actions, the organization shall consider best practices, technological options and financial, operational and business requirements."}'::jsonb, false)
