insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/40', 'iso45001@1', 40, null, 'c6', null, '6.2.1', true, '{"de":"OH&S-Ziele und Planung zu deren Erreichung","en":"OH&S objectives and planning to achieve them"}'::jsonb, '{"de":"Legen Sie OH&S-Ziele für relevante Funktionen, Ebenen und Prozesse fest, unter Berücksichtigung bedeutender Umweltaspekte, Einhaltungsverpflichtungen sowie Risiken und Chancen, die:\n\n• mit der OHSMS-Politik übereinstimmen,\n\n• messbar und überwacht sind;\n\n• zutreffende Anforderungen berücksichtigen;\n\n• relevant für die OH&S-Politik und die Verbesserung der OH&S-Leistung sind;\n\n• überwacht werden;\n\n• kommuniziert werden;\n\n• bei Bedarf aktualisiert werden.\n\nBewahren Sie Dokumentation zu den Zielen auf.","en":"Establish OH&S objectives at relevant functions, levels, and processes, taking into account significant environmental aspects, compliance obligations, and risks and opportunities that:\n\n• are consistent with the OHSMS policy,\n\n• are measurable and monitored;\n\n• take into account applicable requirements;\n\n• are relevant to the OH&S policy and to the improvement of OH&S performance;\n\n• are monitored;\n\n• are communicated;\n\n• are updated as appropriate.\n\nRetain documentation on the objectives."}'::jsonb, '{"de":"Wurden OH&S-ZIELE festgelegt, die mit dem Kontext der OH&S-Politik und den interessierten Parteien übereinstimmen, und werden diese entsprechend ÜBERWACHT, KOMMUNIZIERT und AKTUALISIERT?\n\nAchten Sie auf: E-Mails, Datenprotokolle, Berichte, Sitzungsprotokolle oder andere dokumentierte Informationen wie Messpläne.","en":"Have OH&S OBJECTIVES that are consistent with the OH&S  policy context and interested parties, been established, MONITORED, COMMUNICATED & UPDATED as appropriate?\n\nLook for:  emails, data logs, reports, meeting minutes, or any other documented information such as measurment plans."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/41', 'iso45001@1', 41, null, 'c7', null, '7.2', true, '{"de":"Kompetenz","en":"Competence"}'::jsonb, '{"de":"Die Organisation muss:\n\n• die notwendige Kompetenz der Beschäftigten festlegen, die ihre OH&S-Leistung beeinflusst oder beeinflussen kann;\n\n• sicherstellen, dass die Beschäftigten auf der Grundlage von angemessener Ausbildung, Schulung oder Erfahrung kompetent sind (einschliesslich der Fähigkeit, Gefährdungen zu erkennen);\n\n• soweit anwendbar, Massnahmen ergreifen, um die notwendige Kompetenz zu erwerben und aufrechtzuerhalten, und die Wirksamkeit der ergriffenen Massnahmen bewerten;\n\n• geeignete dokumentierte Information als Nachweis der Kompetenz aufbewahren.","en":"The organization shall:\n\n• determine the necessary competence of workers that affects or can affect its OH&S performance\n\n• ensure that workers are competent (including the ability to identify hazards) on the basis of education, training, or experience;\n\n• where applicable, take actions to acquire and maintain the necessary competence, and evaluate the effectiveness of the actions taken;\n\n• retain appropriate documentation as evidence of competence."}'::jsonb, '{"de":"Gibt es einen Prozess, um die notwendige KOMPETENZ, die notwendige Schulung und dokumentierte Information zur Unterstützung der Kompetenz gemäss den Anforderungen von ISO 45001:2018 festzulegen?\nWird Kompetenz sowohl zum Zeitpunkt der Einstellung als auch während der Beschäftigungsdauer festgelegt?\nWird während der Beschäftigung eine fortlaufende Schulung geplant und durchgeführt?\nWird die Wirksamkeit der Schulung bewertet?\n\nAchten Sie auf: Stellenausschreibungen, Stellenbeschreibungen, Lebensläufe, Bewerbungsunterlagen, Schulungspläne, Schulungsnachweise, Nachweise über die Ausbildung am Arbeitsplatz einschliesslich Bestätigungsblätter.\nFormulare zur Schulungsbewertung, Sitzungsprotokolle oder andere Nachweise dafür, dass die Wirksamkeit der Schulung bewertet wird.","en":"Is there a process in place to determine necessary COMPETENCE, necessary training and documented information to support competence supporting requirements of ISO 45001:2018?\nIs competence defined both at time of hire, and during the period of employment?\nDuring employent is ongoing training planned and provided?\nIs effectiveness of training evaluated?\n\nLook for: job postings, job descriptions, resumes, job applications, training plans, training records, on-the-job training evidence inclluding sign-off sheets.\nTraining evaluation forms, meeting minutes, or any other evidence that training effectiveness is evaluated."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/42', 'iso45001@1', 42, null, 'c7', null, '7.3', true, '{"de":"Bewusstsein","en":"Awareness"}'::jsonb, '{"de":"Die Beschäftigten müssen sich bewusst sein über:\n\n• die OH&S-Politik;\n\n• die OH&S-Ziele;\n\n• ihren Beitrag zum OH&S-Managementsystem und den Nutzen einer verbesserten OH&S-Leistung;\n\n• die Auswirkungen und möglichen Folgen einer Nichteinhaltung der Anforderungen des OH&S-Managementsystems;\n\n• Vorfälle und die Ergebnisse von Untersuchungen, die für sie relevant sind;\n\n• Gefährdungen, OH&S-Risiken und festgelegte Massnahmen, die für sie relevant sind;\n\n• die Möglichkeit, sich aus Arbeitssituationen zu entfernen, die ihrer Ansicht nach eine unmittelbare und ernsthafte Gefahr für ihr Leben oder ihre Gesundheit darstellen, sowie die Vorkehrungen, um sie vor unangemessenen Folgen zu schützen, wenn sie dies tun.","en":"Workers shall be made aware of:\n\n• the OH&S policy;\n\n• the OH&S objectives;\n\n• their contribution to the OHSMS and the benefits of improved OH&S performance;\n\n• the implications and potential consequences of not conforming to the OH&S management system requirements;\n\n• incidents and the outcomes of investigations that are relevant to them;\n\n• hazards, OH&S risks, and actions determined that are relevant to them;\n\n• the ability to remove themselves from work situations that they consider present an imminent and danger to their life or health, as well as the arrangements for protecting them from undue consequences for doing so."}'::jsonb, '{"de":"Gibt es dokumentierte Information, die das BEWUSSTSEIN der unter der Kontrolle der Organisation tätigen Personen unterstützt? (7.3) Falls ja, siehe Anhang C und tragen Sie die Endergebnisse hier ein.\n\nAchten Sie auf: jegliche systematische oder periodische Kommunikation mit Beschäftigten über das OH&S-System, die Politik, die Unternehmensleistung, die fortlaufende Verbesserung. Diese können in Form von E-Mails, Anschlagtafeln, Präsentationen und Mitarbeiterversammlungen vorliegen.","en":"Is there documented information supporting AWARENESS of persons working under the organizations control? (7.3) If yes, see Annex C and enter final results here\n\nLook for: any systematic or periodic communicaitons with employees about the OH&S system , the policy, company performance, continuous improvement. these can be in the form of emails, communications boards, presentations and employee meetings."}'::jsonb, false)
