values ('iso45001@1/50', 'iso45001@1', 50, null, 'c7', null, '7.5', true, '{"de":"Dokumentierte Information / Allgemeines","en":"Documented information /General"}'::jsonb, '{"de":"Das OH&S-Managementsystem der Organisation umfasst:\n\n• von der ISO-Norm geforderte dokumentierte Information;\n\n• von der Organisation als notwendig erachtete dokumentierte Information für die Wirksamkeit des OH&S-Managementsystems.","en":"The organization’s OH&S management system will include:\n\n• documented information required by the ISO standard\n\n• documented information deemed necessary by the organization for the effectiveness of the OH&S management system."}'::jsonb, '{"de":"Ist die DOKUMENTIERTE INFORMATION im Einklang mit ISO 45001:2018?\n\nAchten Sie auf: Dokumente oder Aufzeichnungen zu:\nOH&S-Politik, -Zielen, KPI\nProzess, Verfahren, Arbeitsanweisungen\nProduktions- oder Dienstleistungsplänen\nAufzeichnungen zu Produktions- oder Dienstleistungsarbeiten\nInspektionsaufzeichnungen, Nichtkonformitäten,\nKorrekturmassnahmen","en":"Is DOCUMENTED INFORMATION consistent with ISO 45001:2018?\n\nLook for: documents or records of:\nOH&S policy, objectives, KPI\nProcess, procedure, work instructions\nProduction or service plans\nRecords of production or service work\ninspection records nonfonformities,\ncorrective actions"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
