values ('iso45001@1/51', 'iso45001@1', 51, null, 'c8', null, '8.1.2', true, '{"de":"Beseitigung von Gefährdungen und Minderung von OH&S-Risiken","en":"Eliminating hazards and reducing OH&S risks"}'::jsonb, '{"de":"Einen Prozess zur Beseitigung von Gefährdungen und Minderung von OH&S-Risiken festlegen, verwirklichen und aufrechterhalten, unter Anwendung der folgenden Massnahmenhierarchie:\n\n• die Gefährdung beseitigen\n\n• durch weniger gefährliche Prozesse, Vorgänge, Materialien oder Ausrüstung ersetzen,\n\n• technische Massnahmen und Reorganisation der Arbeit anwenden;\n\n• administrative Massnahmen anwenden, einschliesslich Schulung\n\n• geeignete persönliche Schutzausrüstung verwenden.","en":"Establish, implement and maintain a process for the elimination of hazards and reduction of OH&S risks using the following hierarchy of controls:\n\n• eliminate the hazard\n\n• substitute with less hazardous processes, operations, materials or equipment,\n\n• use engineering controls and reorganization of work;\n\n• use administrative controls, including training\n\n• use adequate personal protective equipment."}'::jsonb, '{"de":"Hat die Organisation die notwendigen Prozesse festgelegt, um die Kriterien des OH&S-Managementsystems für Betriebsprozesse zu erfüllen und die Betriebsprozesse gemäss der Massnahmenhierarchie zu steuern?\n\nAchten Sie auf: Nachweise, dass Pläne und Beurteilungen vorhanden sind.","en":"Has the organization established processes needed to meet OH&SMS in operating process criteria and control of operating processes following hierarchy of controls ?\n\nLook for: evidence that plans and assesments are in place."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
