values ('iso45001@1/53', 'iso45001@1', 53, null, 'c8', null, '8.1.4', true, '{"de":"Beschaffung, Allgemeines und Auftragnehmer 8.1.4.2 und Ausgliederung 8.1.4.3","en":"Procurement General and contractors 8.1.4.2 and out sourcing 8.1.4.3"}'::jsonb, '{"de":"Einen Prozess zur Steuerung der Beschaffung von Produkten und Dienstleistungen festlegen, verwirklichen und aufrechterhalten, um deren Konformität mit dem OH&S-Managementsystem sicherzustellen.\n\nDen Beschaffungsprozess mit Auftragnehmern koordinieren, um Gefährdungen zu ermitteln sowie OH&S-Risiken zu beurteilen und zu steuern.\nSicherstellen, dass die Anforderungen des OH&S-Managementsystems von Auftragnehmern und deren Beschäftigten erfüllt werden. Der Beschaffungsprozess muss Kriterien für Arbeitssicherheit und Gesundheitsschutz für die Auswahl von Auftragnehmern festlegen und anwenden.\n\nSicherstellen, dass ausgegliederte Funktionen und Prozesse gesteuert werden. Sicherstellen, dass Ausgliederungsvereinbarungen mit den rechtlichen Verpflichtungen und anderen Anforderungen sowie mit dem Erreichen der beabsichtigten Ergebnisse des OH&S-Managementsystems im Einklang stehen. Die Art und der Umfang der auf diese Funktionen und Prozesse anzuwendenden Steuerung müssen im OH&S-Managementsystem festgelegt werden.","en":"Establish, implement, and maintain a process to control the procurement of products and services to ensure their conformity to its OH&S management system.\n\nCoordinate the procurement process with contractors, in order to identify hazards and to assess and control the OH&S risks.\nEnsure that the requirements of the OH&S management system are met by contractors and their workers. The procurement process shall define and apply occupational health and safety criteria for the selection of contractors.\n\nEnsure that the outsource functions and processes are controlled.  Ensure that outsourcing arrangement are consistent with legal requirements and other requirements and with achieving the intended outcomes of the OH&S management system.  The type and degree of control to be applied to these functions and processes shall be defined within the OH&S management system."}'::jsonb, '{"de":"Hat die Organisation einen Beschaffungsprozess für Ausgliederung festgelegt?\n\nAchten Sie auf: Pläne, Kommunikation mit Lieferanten oder Auftragnehmern, Verträge und Sitzungsprotokolle.","en":"Has the organization established a procurement process for, outsourcing?\n\nLook for:  Look for plans, communications with suppliers or contractors, contracts and meeting minutes."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/54', 'iso45001@1', 54, null, 'c9', null, '9.1.1', true, '{"de":"Überwachung, Messung, Analyse und Leistungsbewertung/Allgemeines","en":"Monitoring, measurement, analysis and evaluation/General"}'::jsonb, '{"de":"Festlegen:\n\n• was überwacht und gemessen werden muss;\n\no  das Ausmass, in dem rechtliche Verpflichtungen und andere Anforderungen erfüllt sind;\n\no  die Tätigkeiten und Vorgänge im Zusammenhang mit ermittelten Gefährdungen, Risiken und Chancen;\n\no  der Fortschritt bei der Erreichung der OH&S-Ziele;\n\no  die Wirksamkeit von betrieblichen und anderen Massnahmen;\n\n• die Methoden für Überwachung, Messung, Analyse und Leistungsbewertung, um gültige Ergebnisse sicherzustellen;\n\n• die Kriterien, anhand derer die Organisation ihre OH&S-Leistung bewertet;\n\n• wann die Überwachung und Messung durchgeführt wird;\n\n• wann die Ergebnisse aus Überwachung und Messung analysiert, bewertet und kommuniziert werden.\n\nDie OH&S-Leistung bewerten und die Wirksamkeit des OH&S-Managementsystems bestimmen.\n\nSicherstellen, dass Überwachungs- und Messmittel, soweit zutreffend, kalibriert oder verifiziert sowie angemessen verwendet und gewartet werden.\n\nGeeignete dokumentierte Information aufbewahren:\n\n• als Nachweis der Ergebnisse von Überwachung, Messung, Analyse und Leistungsbewertung;\n\n• zur Wartung, Kalibrierung oder Verifizierung von Messmitteln.","en":"Determine:\n\n• what needs to be monitored and measured;\n\no  the extent to which legal requirements and other requirements are fulfilled;\n\no  the activities and operations related to identified hazards, risks and opportunities;\n\no  progress towards achievement of the OH&S objectives;\n\no  effectiveness of operational and other controls;\n\n• the methods for monitoring, measurement, analysis and performance evaluation to ensure valid results;\n\n• the criteria against which the organization will evaluate its OH&S performance;\n\n• when the monitoring and measuring will be performed;\n\n• when the results from monitoring and measurement will be analyzed, evaluated and communicated.\n\nEvaluate the OH&S performance and determine the effectiveness of the OH&S management system.\n\nEnsure that monitoring and measuring equipment is calibrated or verified as applicable and is used and maintained as appropriate.\n\nRetain appropriate documented information:\n\n• as evidence of the results of monitoring, measurement, analysis and performance evaluation;\n\n• on the maintenance, calibration or verification of measuring equipment."}'::jsonb, '{"de":"Sind OH&S-Ziele, wichtige Prozesskennzahlen oder andere Messgrössen der OH&S-Leistung definiert, gemessen, überwacht und berichtet?\n\nSind für diese Messgrössen erwartete Werte (Zielwerte) festgelegt, und wird die Leistung bewertet, um festzustellen, ob die Zielwerte erreicht werden?\n\nWerden Massnahmen ergriffen, wenn Zielwerte nicht erreicht werden?\n\nAchten Sie auf: Definitionen von Messgrössen, Datenprotokolle, Berichte, Besprechungsprotokolle oder andere dokumentierte Information, die zeigt, dass Messungen die OH&S-Leistung vorantreiben.","en":"Are OH&S objectives, key process indicators or other measures of OH&S performance defined, measured, monitored, reported?\n\nAre expected values (targets) set for these measures and is performance assessed to determine whether or not targets are being met?\n\nWhen targets are not met, is action taken?\n\nLook for definitions of measures, data logs, reports, meeting minutes, or any other documented information showing that measurements are driving OH&S performance."}'::jsonb, false)
