values ('iso45001@1/55', 'iso45001@1', 55, null, 'c9', null, '9.1.2', true, '{"de":"Bewertung der Einhaltung von Verpflichtungen","en":"Evaluation of compliance"}'::jsonb, '{"de":"Einen Prozess zur Bewertung der Einhaltung rechtlicher Verpflichtungen und anderer Anforderungen festlegen, umsetzen und aufrechterhalten. Die Organisation muss:\n\n• die Häufigkeit und Methode(n) zur Bewertung der Einhaltung festlegen;\n\n• die Einhaltung bewerten und bei Bedarf Massnahmen ergreifen;\n\n• Kenntnis und Verständnis ihres Einhaltungsstatus in Bezug auf rechtliche Verpflichtungen und andere Anforderungen aufrechterhalten;\n\n• dokumentierte Information über die Ergebnisse der Bewertung der Einhaltung aufbewahren","en":"Establish, implement, and maintain a process for evaluating compliance with legal requirements and other requirements.  The organization shall:\n\n• determine the frequency and method(s) for evaluation of compliance;\n\n• evaluate compliance and take action if needed\n\n• maintain knowledge and understanding of tis compliance status with legal requirements and other requirements;\n\n• retain documented information of the compliance evaluation result(s)"}'::jsonb, '{"de":"Beschreiben Sie, wie Sie die Einhaltung ermitteln und überwachen?\n\nAchten Sie auf: Compliance-Pläne, andere Pläne, Bewertungsformulare usw.","en":"Describe how you obtain and monitor compliance?\n\nLook for: compliance plans, other plans, evaluation forms etc."}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('iso45001@1/56', 'iso45001@1', 56, null, 'c9', null, '9.2', true, '{"de":"Internes Audit","en":"Internal Audit"}'::jsonb, '{"de":"In geplanten Abständen interne Audits durchführen, um Informationen darüber zu liefern, ob das OH&S-Managementsystem den Anforderungen entspricht, umgesetzt und aufrechterhalten wird.\nDie Organisation muss:\n• ein Auditprogramm planen, festlegen, umsetzen und aufrechterhalten, einschliesslich der Häufigkeit, Methoden, Verantwortlichkeiten, Konsultation, Planungsanforderungen und Berichterstattung, wobei die Bedeutung der betroffenen Prozesse und die Ergebnisse früherer Audits berücksichtigt werden;\n• die Auditkriterien und den Auditumfang für jedes Audit festlegen;\n• Auditoren auswählen und Audits durchführen, um die Objektivität und Unparteilichkeit des Auditprozesses sicherzustellen;\n• sicherstellen, dass die Ergebnisse der Audits der relevanten Leitung berichtet werden; sicherstellen, dass relevante Auditergebnisse den Beschäftigten und, soweit vorhanden, den Beschäftigtenvertretern sowie anderen relevanten interessierten Parteien berichtet werden;\n• Massnahmen ergreifen, um Nichtkonformitäten zu behandeln und die OH&S-Leistung fortlaufend zu verbessern;\n• dokumentierte Information als Nachweis für die Umsetzung des Auditprogramms und der Auditergebnisse aufbewahren.","en":"Conduct internal audits at planned intervals to provide information on whether the OHSMS conforms to requirements, is implemented, and maintained.\nThe organization shall:\n• plan, establish, implement, and maintain an audit program including the frequency, methods, responsibilities, consultation, planning requirements and reporting, which takes into consideration, the importance of the processes concerned, and the results of previous audits;\n• define the audit criteria and scope for each audit;\n• select auditors and conduct audits to ensure objectivity and impartiality of the audit process;\n• ensure that the results of the audits are reported to relevant management; ensure that relevant audit results are reported to workers, and where they exist, workers’ representatives, and other relevant interested parties;\n• take action to address nonconformities and continually improve the OH&S performance;\n• retain documented information as evidence of the implementation of the audit program and audit results."}'::jsonb, '{"de":"Gibt es ein internes Auditprogramm? Werden Audits geplant? Sind die Auditoren geschult oder zertifiziert?\n\nWerden die Auditergebnisse der Leitung berichtet? Werden Auditmassnahmen zugewiesen, nachverfolgt, abgeschlossen und verifiziert?\n\nAchten Sie auf: Auditaufzeichnungen, Korrekturmassnahmen aus den Auditfeststellungen.","en":"Is there an internal audit program? Are audits planned. Are auditors trained or certified.\n\nAre audit results reported to management. Are audit actions assigned, tracked, closed, and verified.\n\nLook for: audit records, corrective actions from the audit findings."}'::jsonb, false)
