values ('compliance@1', 'compliance', 1, '{"de":"EHS-Standards-Audit","en":"EHS Standards Audit"}'::jsonb, '[{"key":"electrical_safety","label":"1","title":{"de":"Elektrische Sicherheit","en":"Electrical Safety"},"groups":[{"key":"electrical_safety.1","label":"1","title":{"de":"Kontext der Organisation","en":"Context of the Organisation"}},{"key":"electrical_safety.2","label":"2","title":{"de":"Eigentümer/Betreiber von Hochspannungsanlagen","en":"Owner/ Operator High Voltage Installations"}},{"key":"electrical_safety.3","label":"3","title":{"de":"Allgemeine Anforderungen","en":"General Requirements"}}]},{"key":"fire_protection_storage","label":"2","title":{"de":"Brandschutz & Lagerung","en":"Fire Protection & Storage"},"groups":[{"key":"fire_protection_storage.1","label":"1","title":{"de":"Lagerung von entzündbaren und brennbaren Materialien","en":"Storage of Flammable and Combustible Material"}},{"key":"fire_protection_storage.2","label":"2","title":{"de":"Brandschutz","en":"Fire Safety"}},{"key":"fire_protection_storage.3","label":"3","title":{"de":"Hebezeuge","en":"Lifiting devices"}},{"key":"fire_protection_storage.4","label":"4","title":{"de":"Gasflaschen","en":"Compressed gas cylinders"}},{"key":"fire_protection_storage.5","label":"5","title":{"de":"Sichere Lagerung","en":"Safe storage"}},{"key":"fire_protection_storage.6","label":"6","title":{"de":"Be- und Entladevorgänge","en":"Loading/ unloading operations"}},{"key":"fire_protection_storage.7","label":"7","title":{"de":"Gabelstaplersicherheit","en":"Forklift safety"}}]},{"key":"ppe","label":"3","title":{"de":"PSA","en":"PPE"},"groups":[{"key":"ppe.1","label":"1","title":{"de":"Persönliche Schutzausrüstung (PSA)","en":"Personal Protective Equipment (PPE)"}},{"key":"ppe.2","label":"2","title":{"de":"Augenspülung, Sicherheitsdusche und Erste Hilfe","en":"Eye wash, safety shower and first aid"}}]},{"key":"industrial_hygiene_sampling","label":"4","title":{"de":"Arbeitshygiene & Probenahme","en":"Industrial Hygiene & Sampling"},"groups":[{"key":"industrial_hygiene_sampling.1","label":"1","title":{"de":"Toxikologie","en":"Toxicology"}},{"key":"industrial_hygiene_sampling.2","label":"2","title":{"de":"Arbeitshygiene und arbeitsplatzbezogene Grenzwerte","en":"Industrial hygiene and occupational limits"}},{"key":"industrial_hygiene_sampling.3","label":"3","title":{"de":"Medizinische Untersuchungen","en":"Medical check ups"}},{"key":"industrial_hygiene_sampling.4","label":"4","title":{"de":"Umgang mit Chemikalien","en":"Handling of chemicals"}},{"key":"industrial_hygiene_sampling.5","label":"5","title":{"de":"Containment-Strategie","en":"Containment Strategy"}}]},{"key":"projects","label":"5","title":{"de":"Projekte","en":"Projects"},"groups":[{"key":"projects.1","label":"1","title":{"de":"Beschaffung","en":"Procurement"}},{"key":"projects.2","label":"2","title":{"de":"Ausgliederung und Management von Auftragnehmern","en":"Outsourcing and contractor management"}},{"key":"projects.3","label":"3","title":{"de":"EHS-Risiken und -Chancen im Projekt","en":"Project EHS risks & opportunities"}}]},{"key":"security","label":"6","title":{"de":"Sicherheit","en":"Security"},"groups":[{"key":"security.1","label":"1","title":{"de":"Physische Sicherheit des Standorts","en":"Site physical security"}},{"key":"security.2","label":"2","title":{"de":"Business-Continuity-Plan","en":"Business continuity plan"}}]},{"key":"line_breaking","label":"7","title":{"de":"Öffnen von Leitungen (Line Breaking)","en":"Line Breaking"},"groups":[{"key":"line_breaking.1","label":"1","title":{"de":"Öffnen von Leitungen (Line Breaking)","en":"Line Breaking"}}]},{"key":"hot_work","label":"8","title":{"de":"Heissarbeiten","en":"Hot Work"},"groups":[{"key":"hot_work.1","label":"1","title":{"de":"Heissarbeiten","en":"Hot Work"}}]},{"key":"confined_space","label":"9","title":{"de":"Enger Raum (Confined Space)","en":"Confined Space"},"groups":[{"key":"confined_space.1","label":"1","title":{"de":"Enger Raum (CS)","en":"Confined Space (CS)"}}]},{"key":"high_work","label":"10","title":{"de":"Arbeiten in der Höhe","en":"High Work"},"groups":[{"key":"high_work.1","label":"1","title":{"de":"Arbeiten in der Höhe und Absturzsicherung","en":"Work at Heights and Fall Protection"}}]},{"key":"excavation","label":"11","title":{"de":"Erdarbeiten","en":"Excavation"},"groups":[{"key":"excavation.1","label":"1","title":{"de":"Erdarbeiten, Grabenarbeiten und Verbau","en":"Excavation, Trenching, and Shoring"}}]},{"key":"loto","label":"12","title":{"de":"LOTO","en":"LOTO"},"groups":[{"key":"loto.1","label":"1","title":{"de":"Lockout Tagout (LOTO)","en":"Lock Out Tag Out (LOTO)"}}]},{"key":"explosion_protection","label":"13","title":{"de":"Explosionsschutz","en":"Explosion Protection"},"groups":[{"key":"explosion_protection.1","label":"1","title":{"de":"Explosionsschutz","en":"Explosion Protection"}}]},{"key":"mechanical_integrity","label":"14","title":{"de":"Mechanische Integrität","en":"Mechanical Integrity"},"groups":[{"key":"mechanical_integrity.1","label":"1","title":{"de":"Mechanische Integrität","en":"Mechanical Integrity"}},{"key":"mechanical_integrity.2","label":"2","title":{"de":"Inspektionen & Prüfungen","en":"Inspections & Tests"}},{"key":"mechanical_integrity.3","label":"3","title":{"de":"QS","en":"QA"}}]},{"key":"moc_pssr","label":"15","title":{"de":"MOC & PSSR","en":"MOC & PSSR"},"groups":[{"key":"moc_pssr.1","label":"1","title":{"de":"Änderungsmanagement (MOC)","en":"Management of Change (MOC)"}},{"key":"moc_pssr.2","label":"2","title":{"de":"Sicherheitsprüfung vor Inbetriebnahme (PSSR)","en":"Pre-Start-up Safety Review (PSSR)"}}]},{"key":"incident_investigation","label":"16","title":{"de":"Vorfalluntersuchung","en":"Incident Investigation"},"groups":[{"key":"incident_investigation.1","label":"1","title":{"de":"Vorfalluntersuchung","en":"Incident Investigation"}}]},{"key":"contractor_management","label":"17","title":{"de":"Auftragnehmermanagement","en":"Contractor Management"},"groups":[{"key":"contractor_management.1","label":"1","title":{"de":"Bieterauswahl","en":"Bidder Selection"}},{"key":"contractor_management.2","label":"2","title":{"de":"Vertragsvorbereitung","en":"Contract Preparation"}},{"key":"contractor_management.3","label":"3","title":{"de":"Vertragsvergabe","en":"Contract Award"}},{"key":"contractor_management.4","label":"4","title":{"de":"Einführung & Schulung","en":"Orientation & Training"}},{"key":"contractor_management.5","label":"5","title":{"de":"Führungskräfteentwicklung & Mitarbeiterengagement","en":"Leadership Development & Employee Engagement"}},{"key":"contractor_management.6","label":"6","title":{"de":"Auditierung & Bewertung","en":"Auditing & Evaluation"}}]},{"key":"effective_communication","label":"18","title":{"de":"Wirksame Kommunikation","en":"Effective Communication"},"groups":[{"key":"effective_communication.1","label":"1","title":{"de":"Wirksame Kommunikation","en":"Effective Communication"}}]}]'::jsonb, 327, 'Built from standards_assessment.html ("EHS Standards Audit"), export dated 2026-09-12.')
