insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/2', 'compliance@1', 2, null, 'electrical_safety', 'electrical_safety.1', '1.2', true, '{"de":"Die technische Dokumentation für die elektrischen Systeme und Installationen muss stets…","en":"The technical documentation for the electrical systems and installations must be kept up…"}'::jsonb, '{"de":"Die technische Dokumentation für die elektrischen Systeme und Installationen muss stets auf dem neuesten Stand gehalten werden. Personen, die Arbeiten an elektrischen Systemen ausführen, müssen über den Zustand der technischen Systeme sowie über allfällige Schutzmassnahmen oder Gefährdungen informiert sein. Alle Änderungen an den Systemen und Installationen müssen zeitnah dokumentiert werden.","en":"The technical documentation for the electrical systems and installations must be kept up to date at all times. Persons who carry out work on electrical systems must be informed about the state of the technical systems and any protective measures or hazards. All changes to the systems and installations must be documented promptly."}'::jsonb, '{"de":"Sind Schränke und Räume mit elektrischen Installationen vollständig dokumentiert, sind sie auf dem neuesten Stand und mit den korrekten Warnzeichen gekennzeichnet?","en":"Are cabinets and rooms with electrical installations all properly documented, are they up to date and are they marked with correct warning symbols?"}'::jsonb, false)
