insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/3', 'compliance@1', 3, null, 'electrical_safety', 'electrical_safety.1', '1.3', true, '{"de":"Elektrische Betriebsräume dürfen nur von befugten Personen betreten werden.","en":"Electrical operating rooms may only be entered by authorized persons."}'::jsonb, '{"de":"Elektrische Betriebsräume dürfen nur von befugten Personen betreten werden.","en":"Electrical operating rooms may only be entered by authorized persons."}'::jsonb, '{"de":"Ist der Zugang zu Betriebsräumen und Schaltschränken für unbefugte Personen (z. B. Kinder, betriebsfremde Personen, geistig beeinträchtigte Personen usw.) versperrt?","en":"Is access to operating rooms and control cabinets blocked for unauthorized persons (e.g. children, non-company persons, mentally disturbed persons etc.)?"}'::jsonb, false)
