insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/4', 'compliance@1', 4, null, 'electrical_safety', 'electrical_safety.1', '1.4', true, '{"de":"Basierend auf den auszuführenden Tätigkeiten wird der Schulungsbedarf der eingesetzten…","en":"Based on the activities to be carried out, the training needs for the deployed persons…"}'::jsonb, '{"de":"Basierend auf den auszuführenden Tätigkeiten wird der Schulungsbedarf der eingesetzten\nPersonen ermittelt. Der Bedarf richtet sich nach dem Ausbildungsstand der jeweiligen Person. Schulungen und Instruktionen werden in einem Schulungsnachweis dokumentiert.","en":"Based on the activities to be carried out, the training needs for the deployed\npersons are determined. The need depends on the level of training of the individual person.Training and instructions are documented in a training certificate."}'::jsonb, '{"de":"Wurde das Personal in den betrieblichen Abläufen und Arbeiten an den elektrischen Systemen geschult (Tätigkeiten für Laien)?\n- Z. B. Bedienen von Zeitschaltuhren, Einschalten von Leitungsschutzschaltern,\nAuswechseln von Sicherungen usw.\n- Ist die Schulung dokumentiert?","en":"Have personnel been trained in the operational procedures and work on the electrical systems (layperson activities)?\n- E.g. operating timers, switching on circuit breakers,\nreplacing fuses, etc.\n- Is the training documented?"}'::jsonb, false)
