insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/5', 'compliance@1', 5, null, 'electrical_safety', 'electrical_safety.2', '2.1', true, '{"de":"Der Eigentümer muss die Sicherheit der elektrischen Systeme und…","en":"The owner must be able to provide evidence of the safety of the electrical systems and…"}'::jsonb, '{"de":"Der Eigentümer muss die Sicherheit der elektrischen Systeme und Installationen nachweisen können.\nDies erfolgt mittels Sicherheitsnachweisen, die vom Inhaber der Installationsbewilligung nach Abschluss der Arbeiten oder vom Inhaber der Kontrollbewilligung nach periodischen Kontrollen ausgestellt werden.","en":"The owner must be able to provide evidence of the safety of the electrical systems and installations.\nThis is done with safety certificates, which are issued by the holder of the installation permit after completion of the work or by the holder of the control permit after periodic inspections."}'::jsonb, '{"de":"Besteht ein Sicherheitskonzept für elektrische Installationen und Systeme?","en":"Is there a safety concept for electrical installations and systems?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/6', 'compliance@1', 6, null, 'electrical_safety', 'electrical_safety.2', '2.2', true, '{"de":"Die technische Dokumentation für die elektrischen Systeme und Installationen muss stets…","en":"The technical documentation for the electrical systems and installations must be kept up…"}'::jsonb, '{"de":"Die technische Dokumentation für die elektrischen Systeme und Installationen muss stets auf dem neuesten Stand gehalten werden. Personen, die Arbeiten an elektrischen Systemen ausführen, müssen über den Zustand der technischen Systeme sowie über allfällige Schutzmassnahmen oder Gefährdungen informiert sein. Alle Änderungen an den Systemen und Installationen müssen zeitnah dokumentiert werden.","en":"The technical documentation for the electrical systems and installations must be kept up to date at all times. Persons who carry out work on electrical systems must be informed about the state of the technical systems and any protective measures or hazards. All changes to the systems and installations must be documented promptly."}'::jsonb, '{"de":"Besteht eine Übersicht über alle elektrischen Installationen, die als Hochspannungsanlagen gelten?\nBeispiele für Hochspannungsanlagen sind:\nTransformatorenstationen, MS-Anlagen (Mittelspannungsverteilanlagen, 18 kV), NS-Anlagen (Niederspannungsverteilanlagen, 400 / 230 V), Unterverteilungen,\nBetriebsräume, Schaltschränke für die Produktion, Hausinstallationen","en":"Is there an overview of all electrical installations that are considered high-voltage installations?\nExamples of high-voltage systems are:\ntransformer stations, MVV systems (medium-voltage distribution systems, 18 kV), LV systems (low-voltage distribution systems, 400 / 230 V), sub-distribution boards,\noperating rooms, control cabinets for production, domestic installations"}'::jsonb, false)
