values ('compliance@1/8', 'compliance@1', 8, null, 'electrical_safety', 'electrical_safety.2', '2.4', true, '{"de":"Die technische Dokumentation für die elektrischen Systeme und Installationen muss stets…","en":"The technical documentation for the electrical systems and installations must be kept up…"}'::jsonb, '{"de":"Die technische Dokumentation für die elektrischen Systeme und Installationen muss stets auf dem neuesten Stand gehalten werden. Personen, die Arbeiten an elektrischen Systemen ausführen, müssen über den Zustand der technischen Systeme sowie über allfällige Schutzmassnahmen oder Gefährdungen informiert sein. Alle Änderungen an den Systemen und Installationen müssen zeitnah dokumentiert werden.","en":"The technical documentation for the electrical systems and installations must be kept up to date at all times. Persons who carry out work on electrical systems must be informed about the state of the technical systems and any protective measures or hazards. All changes to the systems and installations must be documented promptly."}'::jsonb, '{"de":"Sind Hochspannungsanlagen mit Warnzeichen gekennzeichnet?","en":"Are high-voltage systems marked with warning symbols?"}'::jsonb, false)
