insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/9', 'compliance@1', 9, null, 'electrical_safety', 'electrical_safety.2', '2.5', true, '{"de":"Mitarbeitende von Drittfirmen sind dafür verantwortlich, dass die beauftragten Arbeiten…","en":"Employees of third-party companies are responsible for ensuring that the contracted work…"}'::jsonb, '{"de":"Mitarbeitende von Drittfirmen sind dafür verantwortlich, dass die beauftragten Arbeiten ordnungsgemäss ausgeführt werden. Sie stimmen sich mit dem Auftraggeber über besondere Gefährdungen und die Notfallorganisation im betroffenen Arbeitsbereich ab.","en":"Employees of third-party companies are responsible for ensuring that the contracted work is carried out properly. They consult with the client about special hazards and the emergency organization in the affected work area."}'::jsonb, '{"de":"Ist sichergestellt, dass sich betriebsfremde Personen (Mitarbeitende von Fremdfirmen) vor der Ausführung von Arbeiten an Hochspannungsanlagen zunächst bei der intern zuständigen Stelle melden?","en":"Is it ensured that external persons (employees of external companies) first report to the internally responsible office before carrying out work on high-voltage power installations?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/10', 'compliance@1', 10, null, 'electrical_safety', 'electrical_safety.2', '2.6', true, '{"de":"Beschäftigte sind verpflichtet, den Betriebsinhaber bei der Durchsetzung der Arbeitssicherheit und…","en":"Employees are obliged to support the company owner in enforcing occupational safety and…"}'::jsonb, '{"de":"Beschäftigte sind verpflichtet, den Betriebsinhaber bei der Durchsetzung der Arbeitssicherheit und der elektrischen Sicherheit zu unterstützen. Sie sind verpflichtet, ihre Arbeiten sicher auszuführen,\nd. h. Arbeitsanweisungen und Sicherheitsregeln zu befolgen.","en":"Employees are obliged to support the company owner in enforcing occupational safety and electrical safety. They are obliged to carry out their work in a safe manner,\ni.e. to follow work instructions and safety rules."}'::jsonb, '{"de":"Falls der Betrieb über einen eigenen Elektriker verfügt:\n- Ist der betriebseigene Elektriker berechtigt, Installationsarbeiten vor Ort auszuführen?\n- Ist die Weiterbildung des betriebseigenen Elektrikers dokumentiert?\n- Ist die erforderliche Schutzausrüstung für die vom Betrieb instand gehaltenen Systeme vorhanden?","en":"If the company has its own electrician:\n- Is the company electrician authorized to carry out installation work on site?\n- Is the company electrician''s further training documented?\n- Is the necessary protective equipment available for the systems maintained by the company?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/11', 'compliance@1', 11, null, 'electrical_safety', 'electrical_safety.2', '2.7', true, '{"de":"Basierend auf den durchzuführenden Tätigkeiten wird der Schulungsbedarf für die eingesetzten Personen ermittelt…","en":"Based on the activities to be carried out, the training needs for the deployed persons…"}'::jsonb, '{"de":"Basierend auf den durchzuführenden Tätigkeiten wird der Schulungsbedarf für die eingesetzten Personen ermittelt. Der Bedarf richtet sich nach dem Ausbildungsstand der einzelnen Person. Schulungen und Unterweisungen werden in einem Ausbildungsnachweis dokumentiert.","en":"Based on the activities to be carried out, the training needs for the deployed persons are determined. The need depends on the level of training of the individual person.Training and instructions are documented in a training certificate."}'::jsonb, '{"de":"Ist die erforderliche Ausbildung für Personen festgelegt, die Zugang zu Hochspannungsanlagen haben\nund bestimmte Tätigkeiten daran ausführen?\n- Ausbildung als Elektriker oder Elektromonteur\n- Berufsbezogene Elektrokenntnisse (Mechaniker, Ingenieur usw.)\n- Interne Schulung durch Elektrofachkräfte","en":"Is the necessary training specified for people who have access to high-voltage installations\nand carry out certain activities on them?\n- Training as an electrician or industrial electrician\n- Job-related electrical knowledge (mechanic, engineer, etc.)\n- Internal training by electricians"}'::jsonb, false)
