insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/12', 'compliance@1', 12, null, 'electrical_safety', 'electrical_safety.2', '2.8', true, '{"de":"Der Eigentümer der Anlagen und Einrichtungen trägt die Verantwortung.","en":"The owner of the installations and facilities bears the responsibility."}'::jsonb, '{"de":"Der Eigentümer der Anlagen und Einrichtungen trägt die Verantwortung. Er delegiert die Überwachung und Kontrolle der Einrichtungen an befugte Personen, die die betrieblichen Tätigkeiten funktionsabhängig ausführen.","en":"The owner of the installations and facilities bears the responsibility. He delegates the monitoring and control of the facilities to authorized persons who carry out the operational activities on a function-dependent basis."}'::jsonb, '{"de":"Ist die Telefonnummer des Elektrikers auf einer allgemeinen Telefonliste oder einer Notfallliste aufgeführt?","en":"Is the electrician''s phone number listed on a general telephone list or an emergency list?"}'::jsonb, false)
