insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/13', 'compliance@1', 13, null, 'electrical_safety', 'electrical_safety.2', '2.9', true, '{"de":"Im Notfall übernimmt die Notfallorganisation.","en":"In the event of an emergency, the emergency response organization will take over."}'::jsonb, '{"de":"Im Notfall übernimmt die Notfallorganisation. Die aktuellen Hinweisschilder «Erste Hilfe bei Elektrounfällen» sind zudem angebracht, um über das Verhalten bei einem Vorfall in elektrischen Betriebsräumen zu informieren.","en":"In the event of an emergency, the emergency response organization will take over. The current information signs “First Aid for Electrical Accidents” are also displayed for information on how to behave in the event of an incident in electrical operating rooms."}'::jsonb, '{"de":"Ist das Vorgehen im Umgang mit einem Unfall einer Person mit Elektrizität im Notfallplan geregelt?","en":"Is the procedure for dealing with an accident involving an individual and electricity regulated in the emergency plan?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
