values ('compliance@1/14', 'compliance@1', 14, null, 'electrical_safety', 'electrical_safety.2', '2.10', true, '{"de":"Bei Elektrounfällen (Personenschäden oder erheblichen Sachschäden)…","en":"In the event of electrical accidents (personal injury or significant property damage),…"}'::jsonb, '{"de":"Bei Elektrounfällen (Personenschäden oder erheblichen Sachschäden) müssen die lokalen Behörden benachrichtigt werden.","en":"In the event of electrical accidents (personal injury or significant property damage), the local authorities must be notified."}'::jsonb, '{"de":"Ist sicherstellt, dass sämtliche durch Elektrizität verursachten Personenschäden oder erheblichen Sachschäden unverzüglich den Behörden gemeldet werden?","en":"Is it ensured that all personal injuries or significant property damage caused by electricity are reported to the authorities without delay?"}'::jsonb, false)
