insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/15', 'compliance@1', 15, null, 'electrical_safety', 'electrical_safety.3', '3.1', true, '{"de":"Der Eigentümer/Betreiber ist verpflichtet sicherzustellen, dass Wartung und Handhabung von…","en":"The owner/ operator is obliged to ensure that maintenance and handling are carried out by…"}'::jsonb, '{"de":"Der Eigentümer/Betreiber ist verpflichtet sicherzustellen, dass Wartung und Handhabung von qualifiziertem Personal durchgeführt werden, das über die entsprechende PSA verfügt. Ist für einzelne Anlagen Schutzausrüstung vorgeschrieben, muss diese ständig verfügbar sein. Sie muss jederzeit in einwandfreiem, gebrauchsfähigem Zustand gehalten werden.","en":"The owner/ operator is obliged to ensure that maintenance and handling are carried out by qualified personnel, which have the appropriate PPE.  If protective equipment is prescribed for individual systems, it must be permanently available. It must be kept in perfect, usable condition at all times."}'::jsonb, '{"de":"Verfügt das befugte Personal über die entsprechende PSA: Gummihandschuhe mit Lederüberhandschuh, Gummihandschuhe mit Prüfdatum und Spannungsangabe gestempelt (Prüfung alle 6 Monate). Stiefel mit EH-Kennzeichnung (weisses Quadrat mit Ohm-Symbol). Kleidung aus Baumwolle/Nomex – keine synthetischen Materialien, kein Metallschmuck","en":"Authorized personnel have appropriate PPE: Rubber Gloves with Leather Over-Glove, Rubber Gloves stamped with test date and voltage rating (testing every 6 months). Boots have EH rating (white square with ohm symbol). Cotton/Nomex clothing – no synthetic materials, metal jewelry"}'::jsonb, false)
