values ('compliance@1/17', 'compliance@1', 17, null, 'electrical_safety', 'electrical_safety.3', '3.3', true, '{"de":"Programm zur Prüfung von GFCIs (USA), DR (Brasilien), FI (Schweiz) oder länderspezifischen…","en":"Program to check GFCIs (USA), DR (Brazil), FE (Switzerland) or country specific ground…"}'::jsonb, '{"de":"Es besteht ein Programm zur Prüfung von Fehlerstromschutzschaltern (GFCI in den USA, DR in Brasilien, FI in der Schweiz) oder dem länderspezifischen Äquivalent in festgelegten Intervallen.","en":"A program is in place to check ground fault circuit interrupters (GFCI in the USA, DR in Brazil, FI in Switzerland) or the country specific equivalent at the defined interval."}'::jsonb, '{"de":"Besteht ein Programm zur Prüfung von Fehlerstromschutzschaltern (oder dem länderspezifischen Äquivalent) in festgelegten Intervallen, mit Aufzeichnungen?","en":"Is there a program to check ground fault circuit interrupters (or the country specific equivalent) at a defined interval, with records?"}'::jsonb, false)
