values ('compliance@1/23', 'compliance@1', 23, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.2', true, '{"de":"Entzündbare Flüssigkeiten müssen in Tanks, für entzündbare Stoffe zugelassenen IBC oder Metallfässern gelagert werden.","en":"Flammable liquids shall be stored in tanks, IBCs approved for flammables or metal drums."}'::jsonb, '{"de":"Entzündbare Flüssigkeiten müssen in Tanks, für entzündbare Stoffe zugelassenen IBC oder Metallfässern gelagert werden. Kleinere Mengen, die in Laboren und der Instandhaltungswerkstatt verwendet werden, müssen in Metallschränken gelagert werden, die für die Lagerung von entzündbaren Stoffen ausgelegt sind.","en":"Flammable liquids shall be stored in tanks, IBCs approved for flammables or metal drums. Smaller volumes used in laboratories and maintenance workshop shall be stored in metal cabinets designed for storage of flammables."}'::jsonb, '{"de":"Werden die Chemikalien in Übereinstimmung mit dem ursprünglich genehmigten Lagerkonzept gelagert?","en":"Are the chemicals stored in compliance with the originally approved storage concept?"}'::jsonb, false)
