values ('compliance@1/35', 'compliance@1', 35, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.14', true, '{"de":"Basierend auf den auszuführenden Tätigkeiten wird der Schulungsbedarf für die eingesetzten Personen ermittelt…","en":"Based on the activities to be carried out, the training needs for the deployed persons…"}'::jsonb, '{"de":"Basierend auf den auszuführenden Tätigkeiten wird der Schulungsbedarf für die eingesetzten Personen ermittelt. Der Bedarf richtet sich nach dem Ausbildungsstand der einzelnen Person. Schulungen und Unterweisungen werden in einem Ausbildungsnachweis dokumentiert.","en":"Based on the activities to be carried out, the training needs for the deployed persons are determined. The need depends on the level of training of the individual person.Training and instructions are documented in a training certificate."}'::jsonb, '{"de":"Werden die Anlagen von fachkundigem Personal gewartet?","en":"Are the systems maintained by expert personnel?"}'::jsonb, false)
