values ('compliance@1/36', 'compliance@1', 36, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.15', true, '{"de":"Alle fest installierten Brandbekämpfungseinrichtungen, wie Sprinkleranlagen, Schaumlöschanlagen, Brandmelder…","en":"All fixed firefighting equipment, like sprinkler-systems, foam-systems, fire-detectors…"}'::jsonb, '{"de":"Alle fest installierten Brandbekämpfungseinrichtungen, wie Sprinkleranlagen, Schaumlöschanlagen, Brandmelder und Brandmeldeanlagen, müssen jährlich durch eine sachkundige Person kontrolliert werden.","en":"All fixed firefighting equipment, like sprinkler-systems, foam-systems, fire-detectors and fire alarm systems shall be controlled by a competent person on an annual basis."}'::jsonb, '{"de":"Stehen geeignete Lösch- und Kühlgeräte zur Verfügung (Feuerlöscher, Brandbekämpfungspersonal)?","en":"Are appropriate extinguishing and cooling devices available (fire extinguishers, fire extinguishing personnel)?"}'::jsonb, false)
