values ('compliance@1/40', 'compliance@1', 40, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.19', true, '{"de":"Behälter und Chemikalien müssen gemäss den örtlichen Vorschriften gekennzeichnet und…","en":"Containers and chemicals shall be labeld in accordance with local regulations and…"}'::jsonb, '{"de":"Behälter und Chemikalien müssen gemäss den örtlichen Vorschriften gekennzeichnet und angemessen gelagert werden.","en":"Containers and chemicals shall be labeld in accordance with local regulations and adequartly stored."}'::jsonb, '{"de":"Werden Säuren und Laugen sowie Stoffe, die bei gegenseitigem Kontakt gefährlich reagieren können, örtlich oder räumlich getrennt voneinander gelagert?","en":"Are acids and alkalis, as well as substances that may react dangerously if they come into contact with each other, stored separately from each other in terms of location or space?"}'::jsonb, false)
