insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/41', 'compliance@1', 41, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.20', true, '{"de":"Gefahrstoffe müssen stets so gelagert werden, dass sie im Falle eines…","en":"Hazardous substances shall always be stored in such a way that, in the event of an…"}'::jsonb, '{"de":"Gefahrstoffe müssen stets so gelagert werden, dass sie im Falle eines Unfalls oder einer Leckage nicht in die Kanalisation oder ins Erdreich gelangen können.","en":"Hazardous substances shall always be stored in such a way that, in the event of an accident or leakage, they cannot enter the sewer system or the soil."}'::jsonb, '{"de":"Wurden Auffangmassnahmen getroffen, z. B. mittels Auffangwannen und Barrieren, um zu verhindern, dass auslaufende Flüssigkeiten in angrenzende Räume, Kanalisationssysteme und dergleichen gelangen (getrennte Auffangwannen bei Stoffunverträglichkeit)?","en":"Have containment measures been taken, e.g. using trays and barriers, to prevent leaking fluids from flowing into neighboring rooms, sewer systems and the like (separate collection trays for substance incompatibility)?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/42', 'compliance@1', 42, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.21', true, '{"de":"Das Sicherheitsdatenblatt (SDB) gibt Auskunft über die Gefahren für Mensch und die…","en":"The safety data sheet (SDS) provides information on the hazards for humans and the…"}'::jsonb, '{"de":"Das Sicherheitsdatenblatt (SDB) gibt Auskunft über die Gefahren für Mensch und Umwelt und beschreibt die zu treffenden notwendigen Massnahmen. Daraus muss auch die Einstufung klar hervorgehen. Ein SDB ist für alle als gefährlich eingestuften Stoffe und Gemische obligatorisch und muss vom Hersteller oder, bei ausländischen Produkten, vom Importeur bei der ersten Lieferung zur Verfügung gestellt werden.","en":"The safety data sheet (SDS) provides information on the hazards for humans and the environment and describes the necessary measures to be taken. The classification must also be clear from this. An SDS is mandatory for all substances and mixtures classified as hazardous and must be provided by the manufacturer or, in the case of foreign products, by the importer upon first delivery."}'::jsonb, '{"de":"Sind die Sicherheitsdatenblätter für alle gelagerten Stoffe vorhanden und für die Mitarbeitenden vor Ort im Notfall schnell zugänglich?","en":"Are the safety data sheets for all stored substances available and quickly accessible for employees on site in an emergency?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
