values ('compliance@1/43', 'compliance@1', 43, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.22', true, '{"de":"In unmittelbarer Nähe von Lagerräumen müssen Notfalleinrichtungen für Chemikalienverätzungen vorhanden sein…","en":"Emergengy facilities shall be available for chemical burns in close vincity of storage…"}'::jsonb, '{"de":"In unmittelbarer Nähe von Lagerräumen müssen Notfalleinrichtungen für Chemikalienverätzungen vorhanden sein.","en":"Emergengy facilities shall be available for chemical burns in close vincity of storage rooms."}'::jsonb, '{"de":"Sind in oder unmittelbar ausserhalb von Lagerräumen mit Säuren und Laugen Notfalleinrichtungen für Chemikalienverätzungen vorhanden (Augenspülung, Erste-Hilfe-Set)?","en":"Are emergency facilities for chemical burns available in or immediately outside storage rooms containing acids and alkalis (eye shower, first-aid kit)?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/44', 'compliance@1', 44, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.23', true, '{"de":"Notfall-Absorptionssets und geeignete PSA müssen vorhanden sein, um verschüttete Chemikalien aufzunehmen und…","en":"Emergency spill kits and adequate PPE shall be available to manage the absorbing and…"}'::jsonb, '{"de":"Notfall-Absorptionssets und geeignete PSA müssen vorhanden sein, um das Aufnehmen und Entsorgen von verschütteten Chemikalien zu ermöglichen.","en":"Emergency spill kits and adequate PPE shall be available to manage the absorbing and disposing of any chemical that might have been spilled."}'::jsonb, '{"de":"Sind ausserhalb des Lagers geeignete Absorptionsmittel und Schutzausrüstung wie Schutzhandschuhe, Schutzbrillen, Atemschutzgeräte usw. vorhanden, um verschüttete Chemikalien aufzunehmen und zu entsorgen?","en":"Are suitable absorbents and protective equipment such as protective gloves, goggles, breathing apparatus, etc. available outside the warehouse for absorbing and disposing of any chemicals that may have been spilled?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
