values ('compliance@1/45', 'compliance@1', 45, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.24', true, '{"de":"Gasflaschen müssen an geeigneten Orten gelagert und gesichert werden.","en":"Gas cyclinders shall be stored and secured in suitable locations."}'::jsonb, '{"de":"Gasflaschen müssen an geeigneten Orten gelagert und gesichert werden.","en":"Gas cyclinders shall be stored and secured in suitable locations."}'::jsonb, '{"de":"Werden Gasflaschen an einem geeigneten Ort gelagert (Hinweis: geschützt vor mechanischen und thermischen Einwirkungen, z. B. Lagerung in Räumen, die als Brandabschnitte ausgelegt sind, keine Ansammlung von entweichenden Gasen möglich, ausreichende natürliche oder künstliche Belüftung, keine Zündquellen für brennbare Gase, geschützt vor unbefugtem Zugang, keine offene Verbindung zu angrenzenden Räumen oder zur Kanalisation, Kennzeichnung der Gefahren mit geeigneten Sicherheitszeichen)?","en":"Are gas cylinders stored in a suitable location (note: protected from mechanical and thermal effects, e.g. storage in rooms designed as fire compartments, no accumulation of escaping gases possible, adequate natural or artificial ventilation, no ignition sources for combustible gases = protected from unauthorized access, no open connection to adjacent rooms or to the sewer system, labeling of hazards with appropriate safety signs)?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
