values ('compliance@1/46', 'compliance@1', 46, null, 'fire_protection_storage', 'fire_protection_storage.1', '1.25', true, '{"de":"Gasflaschen müssen an geeigneten Orten gelagert und gesichert werden.","en":"Gas cyclinders shall be stored and secured in suitable locations."}'::jsonb, '{"de":"Gasflaschen müssen an geeigneten Orten gelagert und gesichert werden.","en":"Gas cyclinders shall be stored and secured in suitable locations."}'::jsonb, '{"de":"Sind die gelagerten Gasflaschen gegen Umfallen gesichert (z. B. mit Ketten oder Gurten) und sind die Ventile durch eine Kappe vor Beschädigung geschützt?","en":"Are the stored gas cylinders secured against falling over (e.g. with chains or belts) and are the valves protected from damage by a cap?"}'::jsonb, false)
