values ('compliance@1/47', 'compliance@1', 47, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.1', true, '{"de":"Der Standort muss über eine regelmässige Prüfung der Brandmeldeanlage verfügen, und die Brandmeldeanlagen müssen…","en":"The site shall have a regular test of the fire alarm and the fire alarm systems shall be…"}'::jsonb, '{"de":"Der Standort muss über eine regelmässige Prüfung der Brandmeldeanlage verfügen, und die Brandmeldeanlagen müssen im Falle eines Stromausfalls an eine USV angeschlossen sein.","en":"The site shall have a regular test of the fire alarm and the fire alarm systems shall be connected to an UPS in case of power failure."}'::jsonb, '{"de":"Wird die Brandmeldeanlage regelmässig geprüft? Ist sie an eine USV angeschlossen, um die Funktionsfähigkeit im Falle eines Stromausfalls sicherzustellen?","en":"Is the fire alarm system tested regularly? Is it connected to a UPS to ensure functionality in case of power failure?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/48', 'compliance@1', 48, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.2', true, '{"de":"Alle Gebäude müssen über technische Zeichnungen mit Brandklassifizierung und Brandabschnittsbildung verfügen…","en":"All buildings shall have technical drawings with fire classification and fire-segregation…"}'::jsonb, '{"de":"Alle Gebäude müssen über technische Zeichnungen verfügen, in denen die Brandklassifizierung und Brandabschnittsbildung eingezeichnet sind. Ebenso müssen Sprinkleranlagen, Schaumlöschanlagen und alle anderen fest installierten Feuerlöscheinrichtungen in der Zeichnung enthalten sein. Aussenanlagen wie Löschwassertank, Feuerlöschpumpen und Hydranten mit Schläuchen müssen auf einem Lageplan eingezeichnet sein.","en":"All buildings shall have technical drawings with fire classification and fire-segregation marked. Also, sprinkler-systems, foam-systems and any other fixed firefighting installations shall be included on the drawing. Outdoor equipment like fire water tank, fire-pumps and hydrants with hoses shall be indicated on a site map."}'::jsonb, '{"de":"Sind technische Zeichnungen mit Kennzeichnung der Brandklassifizierung und Brandabschnittsbildung vorhanden? Sind alle Feuerlöscheinrichtungen und Aussenanlagen auf einem Lageplan eingezeichnet?","en":"Are technical drawings available with fire classification and fire-segregation markings? Are all firefighting installations and outdoor equipment indicated on a site map?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/49', 'compliance@1', 49, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.3', true, '{"de":"Tragbare Feuerlöscher müssen: - mit Standort erfasst sein, damit sichergestellt ist, dass die externe…","en":"Portable fire extinguishers shall: - be listed with location to make sure the external…"}'::jsonb, '{"de":"Tragbare Feuerlöscher müssen:\n- mit Standort erfasst sein, damit sichergestellt ist, dass die externe Servicefirma alle Löscher erfasst\n- regelmässig inspiziert und geprüft werden (BP - jährlich)\n- deutliche Beschilderung mit Löschanweisungen aufweisen, frei von Hindernissen\n- keine sichtbaren Schäden aufweisen und den korrekten Fülldruck haben\n- ein Inspektionsdatum aufweisen","en":"Portable fire extinguishers shall:\n- be listed with location to make sure the external service company will cover all cylinders\n- have regular inspection and testing (BP - annual)\n- have clear signs with fire instruction on it, clear from obstruction\n- have no visible damage with correct charging pressure\n- have inspection date"}'::jsonb, '{"de":"Sind tragbare Feuerlöscher mit Standort erfasst? Wurden sie jährlich inspiziert und geprüft? Sind die Löschanweisungen deutlich lesbar und nicht verdeckt? Gibt es sichtbare Schäden? Ist das Inspektionsdatum gültig?","en":"Are portable fire extinguishers listed with locations? Have they been inspected and tested annually? Are fire instructions clear and unobstructed? Is there any visible damage? Is the inspection date valid?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/50', 'compliance@1', 50, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.4', true, '{"de":"Brandschutztüren und -tore müssen: - keine sichtbaren Schäden aufweisen - sich beim Auslösen ohne Spalt schliessen","en":"Fire door and gate shall: - have no visible damage - be closed with no gap when released"}'::jsonb, '{"de":"Brandschutztüren und -tore müssen:\n- keine sichtbaren Schäden aufweisen\n- sich beim Auslösen ohne Spalt schliessen","en":"Fire door and gate shall:\n- have no visible damage\n- be closed with no gap when released"}'::jsonb, '{"de":"Sind alle Brandschutztüren und -tore frei von sichtbaren Schäden? Schliessen sie beim Auslösen vollständig ohne Spalt?","en":"Are all fire doors and gates free of visible damage? Do they close completely with no gaps when released?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/51', 'compliance@1', 51, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.5', true, '{"de":"Alle fest installierten Feuerlöscheinrichtungen wie Sprinkleranlagen, Schaumlöschanlagen, Brandmelder…","en":"All fixed firefighting equipment, like sprinkler-systems, foam-systems, fire-detectors…"}'::jsonb, '{"de":"Alle fest installierten Feuerlöscheinrichtungen wie Sprinkleranlagen, Schaumlöschanlagen, Brandmelder und Brandmeldeanlagen müssen jährlich von einer kompetenten Person kontrolliert werden.","en":"All fixed firefighting equipment, like sprinkler-systems, foam-systems, fire-detectors and fire alarm systems shall be controlled by a competent person on an annual basis"}'::jsonb, '{"de":"Wurden alle fest installierten Feuerlöscheinrichtungen im letzten Jahr von einer kompetenten Person inspiziert und kontrolliert?","en":"Has all fixed firefighting equipment been inspected and controlled by a competent person within the last year?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/52', 'compliance@1', 52, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.6', true, '{"de":"Wenn die Hauptfeuerlöschpumpe elektrisch betrieben wird, muss der Standort über eine Reservepumpe verfügen, die auf…","en":"If the main fire pump is running on electricity, the site shall have a back-up pump based…"}'::jsonb, '{"de":"Wenn die Hauptfeuerlöschpumpe elektrisch betrieben wird, muss der Standort über eine Reservepumpe verfügen, die mit Diesel oder einem anderen natürlichen Brennstoff betrieben wird. Der Kraftstofftank muss eine funktionsfähige Füllstandsanzeige haben und der Mindestfüllstand muss festgelegt sein. Die Diesel-Feuerlöschpumpe muss wöchentlich starten und 30 Minuten lang laufen.","en":"If the main fire pump is running on electricity, the site shall have a back-up pump based on diesel or other natural fuel. The fuel tank shall have a functional level indicator and minimum level shall be defined. The diesel fire pump shall start and run for 30 minutes every week."}'::jsonb, '{"de":"Verfügt der Standort über eine Reservepumpe für die Hauptfeuerlöschpumpe? Hat der Kraftstofftank eine funktionsfähige Füllstandsanzeige mit festgelegtem Mindestfüllstand? Startet die Diesel-Feuerlöschpumpe wöchentlich und läuft sie 30 Minuten lang?","en":"Does the site have a back-up pump for the main fire pump? Does the fuel tank have a functional level indicator with a defined minimum level? Does the diesel fire pump start and run for 30 minutes weekly?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/53', 'compliance@1', 53, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.7', true, '{"de":"Der Wassertank muss eine funktionsfähige Füllstandsanzeige haben und der Mindestfüllstand muss festgelegt sein.","en":"The water tank shall have a functional level indicator and minimum level shall be defined."}'::jsonb, '{"de":"Der Wassertank muss eine funktionsfähige Füllstandsanzeige haben und der Mindestfüllstand muss festgelegt sein. Schaummittel muss mit Mindestfüllstand und Verfallsdatum gekennzeichnet sein","en":"The water tank shall have a functional level indicator and minimum level shall be defined. Foam must be marked with minimum level and expiry date"}'::jsonb, '{"de":"Hat der Wassertank eine funktionsfähige Füllstandsanzeige mit festgelegtem Mindestfüllstand? Ist der Schaummittelstand gekennzeichnet und weist er ein Verfallsdatum auf?","en":"Does the water tank have a functional level indicator with a defined minimum level? Is the foam level marked, and does it have an expiry date?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/54', 'compliance@1', 54, null, 'fire_protection_storage', 'fire_protection_storage.2', '2.8', true, '{"de":"Bei vorübergehender Abschaltung von Brandbekämpfungs- und/oder Branddetektionssystemen…","en":"In case of temporary disconnection of firefighting and/or fire detection system…"}'::jsonb, '{"de":"Bei vorübergehender Abschaltung von Brandbekämpfungs- und/oder Branddetektionssystemen (Beeinträchtigung) muss die Versicherungsgesellschaft mindestens 24 Stunden vor der geplanten Abschaltung benachrichtigt werden","en":"In case of temporary disconnection of firefighting and/or fire detection system (impairment), the insurance company shall be notified at least 24 hours prior to planned disconnection"}'::jsonb, '{"de":"Gibt es einen dokumentierten Prozess zur Benachrichtigung der Versicherungsgesellschaft mindestens 24 Stunden vor jeder geplanten Abschaltung von Brandbekämpfungs- oder Branddetektionssystemen?","en":"Is there a documented process to notify the insurance company at least 24 hours before any planned disconnection of firefighting or fire detection systems?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/55', 'compliance@1', 55, null, 'fire_protection_storage', 'fire_protection_storage.3', '3.1', true, '{"de":"Kräne, Hebezeuge, Sicherheitsgurte, Rettungsleinen und andere Hebevorrichtungen müssen bemessen sein…","en":"Cranes, hoists, safety harnesses, rescue lines and other lifting devices shall be rated…"}'::jsonb, '{"de":"Kräne, Hebezeuge, Sicherheitsgurte, Rettungsleinen und andere Hebevorrichtungen müssen mit der maximalen Last bemessen sein, und jede Vorrichtung muss deutlich gekennzeichnet und für den Bediener sichtbar sein. Alle Hebevorrichtungen müssen jährlich von einer sachkundigen Person geprüft werden, und die Aufzeichnungen müssen archiviert werden. Änderungen an Hebevorrichtungen dürfen nur vom Hersteller vorgenommen werden.","en":"Cranes, hoists, safety harnesses, rescue lines and other lifting devices shall be rated with maximum load and each device shall be clearly marked and visible for the operator. All lifting devices shall be inspected on an annual basis by a competent person and records shall be kept on file. Change on lifting devices can only be done by the manufacturer."}'::jsonb, '{"de":"Sind alle Hebevorrichtungen deutlich mit der maximalen Last gekennzeichnet und für den Bediener sichtbar? Werden jährliche Prüfungen durchgeführt und Aufzeichnungen geführt?","en":"Are all lifting devices clearly marked with the maximum load and visible for the operator? Are annual inspections conducted and records maintained?"}'::jsonb, false)
