insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/56', 'compliance@1', 56, null, 'fire_protection_storage', 'fire_protection_storage.3', '3.2', true, '{"de":"Aufzüge und Lifte müssen: - das Datum der letzten Prüfung/das Fälligkeitsdatum der nächsten Prüfung im Aufzug angebracht haben…","en":"Elevators and lifts shall: - have last inspection date/due date next inspection posted…"}'::jsonb, '{"de":"Aufzüge und Lifte müssen:\n- das Datum der letzten Prüfung/das Fälligkeitsdatum der nächsten Prüfung im Aufzug angebracht haben\ndie maximale Last (kg) im Aufzug angebracht haben\n- keinen Personentransport in einem Warenaufzug zulassen\n- kein gefährliches Rohmaterial im Personenaufzug oder -lift zulassen\n- das Warnschild „Bei Brand Aufzug nicht benutzen“ in der Nähe von Personenliften angebracht haben\nDer Personenaufzug muss den Maschinenraum in einem separaten Brandabschnitt haben, und der Maschinenraum muss über eingeschränkten Zugang verfügen","en":"Elevators and lifts shall:\n- have last inspection date/due date next inspection posted inside elevator\nhave maximum load (kg) posted inside elevator\n- have no personnel that can travel with a goods elevator\n- have no hazardous raw material allowed inside an elevator or lift for persons\n- have warning sign “In case of fire, do not use elevator” posted nearby lifts for persons\nElevator for persons shall have the engine room located in a separate fire section and the engine room shall have restricted access"}'::jsonb, '{"de":"Sind die Prüfdaten im Aufzug angebracht? Ist die maximale Last deutlich angezeigt? Ist es dem Personal untersagt, mit Warenaufzügen zu fahren? Ist gefährliches Rohmaterial von Personenaufzügen ausgeschlossen? Ist ein Brandwarnschild in der Nähe von Liften angebracht? Befindet sich der Maschinenraum für Personenaufzüge in einem separaten Brandabschnitt mit eingeschränktem Zugang?","en":"Are inspection dates posted inside the elevator? Is the maximum load clearly displayed? Are personnel prohibited from traveling with goods elevators? Are hazardous raw materials restricted from passenger lifts? Is a fire warning sign posted near lifts? Is the engine room for passenger elevators in a separate fire section with restricted access?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/57', 'compliance@1', 57, null, 'fire_protection_storage', 'fire_protection_storage.4', '4.1', true, '{"de":"Druckgasflaschen müssen: - mit Gasname und Gefahrenkennzeichnung versehen sein - über eine…","en":"Compressed gas cylinders shall: - be labelled with gas name and hazard label - have a…"}'::jsonb, '{"de":"Druckgasflaschen müssen:\n- mit Gasname und Gefahrenkennzeichnung versehen sein\n- über einen dedizierten Lagerbereich mit eingeschränktem Zugang verfügen\n- in aufrechter Position gelagert und gesichert sein\n- auf einem Flaschenwagen mit Sicherungskette transportiert werden","en":"Compressed gas cylinders shall:\n- be labelled with gas name and hazard label\n- have a dedicated storage area with restricted access\n- be stored and secured in upright position\n- be transported on cylinder trolley with a security chain"}'::jsonb, '{"de":"Sind alle Druckgasflaschen ordnungsgemäss mit Gasname und Gefahrenkennzeichnung versehen? Werden sie in einem dedizierten Bereich mit eingeschränktem Zugang gelagert? Sind sie in aufrechter Position gesichert? Werden sie mit einem Flaschenwagen mit Sicherungskette transportiert? Ist das obere Ventil abgedeckt, wenn die Flasche nicht in Gebrauch ist?","en":"Are all compressed gas cylinders properly labeled with the gas name and hazard label? Are they stored in a dedicated area with restricted access? Are they secured in an upright position? Are they transported using a cylinder trolley with a security chain? Is the top valve covered when not in use?"}'::jsonb, false)
