insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/58', 'compliance@1', 58, null, 'fire_protection_storage', 'fire_protection_storage.4', '4.2', true, '{"de":"Das obere Ventil muss während des Transports und wenn nicht in Gebrauch abgedeckt sein","en":"The top valve shall have a cover during transport and when not in use"}'::jsonb, '{"de":"Das obere Ventil muss während des Transports und wenn nicht in Gebrauch abgedeckt sein","en":"The top valve shall have a cover during transport and when not in use"}'::jsonb, '{"de":"Sind die oberen Ventile während des Transports und wenn nicht in Gebrauch geschützt?","en":"Are top valves protected during transport and when not in use?"}'::jsonb, false)
