insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/59', 'compliance@1', 59, null, 'fire_protection_storage', 'fire_protection_storage.5', '5.1', true, '{"de":"Regale müssen: - vor Gebrauch von einer sachkundigen Person geprüft und freigegeben werden - in gutem…","en":"Racks shall: - be inspected and approved by a competent person before usage - be in good…"}'::jsonb, '{"de":"Regale müssen:\n- vor Gebrauch von einer sachkundigen Person geprüft und freigegeben werden\n- in gutem Betriebszustand sein, und jede Beschädigung an Regalen/Trägern/Stützen muss umgehend von einem qualifizierten Unternehmen behoben werden\n- mit der maximalen Bemessungslast/zertifizierten Last gekennzeichnet sein\n- über einen Stützenschutz/Barriere zum Schutz vor Gabelstaplerkollisionen verfügen","en":"Racks shall:\n- be inspected and approved by a competent person before usage\n- be in good working condition and any damage on the racks / beams / columns must be fixed by a qualified company immediately\n- be labelled with maximum design load/certified load\n- have a column guard/barrier installed to protected against forklift collision"}'::jsonb, '{"de":"Wurden alle Regale vor Gebrauch von einer sachkundigen Person geprüft und freigegeben? Werden beschädigte Regale umgehend von einem qualifizierten Unternehmen instand gesetzt? Sind die Regale mit ihrer maximalen Bemessungs-/zertifizierten Last gekennzeichnet? Sind Stützenschutz/Barrieren zum Schutz vor Gabelstaplerkollisionen installiert?","en":"Have all racks been inspected and approved by a competent person before use? Are damaged racks repaired immediately by a qualified company? Are racks labeled with their maximum design/certified load? Are column guards/barriers installed to protect against forklift collisions?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/60', 'compliance@1', 60, null, 'fire_protection_storage', 'fire_protection_storage.5', '5.2', true, '{"de":"Einzelregale müssen: - ordnungsgemäss an einer festen Installation gesichert sein, um ihre Stabilität zu gewährleisten…","en":"Single racks shall: - be properly secured to fixed installation to ensure its stability…"}'::jsonb, '{"de":"Einzelregale müssen:\n- ordnungsgemäss an einer festen Installation gesichert sein, um Stabilität und Integrität zu gewährleisten\n- einen angemessenen Rückenschutz aufweisen, wenn die Rückseite des Einzelregals zu einem Gang oder Durchgang zeigt\n- Massnahmen zur Verhinderung des Zutritts zum Bereich aufweisen, wenn das Einzelregal einen Rückraum hat, den eine Person betreten kann","en":"Single racks shall:\n- be properly secured to fixed installation to ensure its stability and integrity\n-  have a proper back protection, if the backside of the single rack faces a gangway or a passageway\n-  be installed measures to prevent entering the area, if the single rack has back space that a person can enter"}'::jsonb, '{"de":"Sind Einzelregale ordnungsgemäss an festen Installationen gesichert? Ist ein angemessener Rückenschutz vorhanden, wenn Regale zu einem Gang oder Durchgang zeigen? Sind Massnahmen vorhanden, um den unbefugten Zutritt zu Rückräumen von Einzelregalen zu verhindern?","en":"Are single racks properly secured to fixed installations? Is proper back protection provided when racks face a gangway or passageway? Are measures in place to prevent unauthorized access to back spaces of single racks?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/61', 'compliance@1', 61, null, 'fire_protection_storage', 'fire_protection_storage.5', '5.3', true, '{"de":"Paletten müssen: - in gutem Zustand sein, ohne sichtbare Schäden und für die tatsächliche Last ausgelegt…","en":"Pallets shall: - be in good conditions, no visible damages and designed for the actual…"}'::jsonb, '{"de":"Paletten müssen:\n- in gutem Zustand sein, ohne sichtbare Schäden und für die tatsächliche Last ausgelegt\n- für feste Rohstoffe niemals höher als 2,5 Meter gelagert werden\n- ab Ebene 1 und darüber umreift oder umwickelt sein","en":"Pallets shall:\n- be in good conditions, no visible damages and designed for the actual load\n- never be stored higher than 2,5 meters for solid raw material\n- be strapped or wrapped at level 1 and above"}'::jsonb, '{"de":"Sind Paletten in gutem Zustand ohne sichtbare Schäden und für die tatsächliche Last ausgelegt? Werden feste Rohstoffe niemals höher als 2,5 Meter gelagert? Sind Paletten auf Ebene 1 und darüber umreift oder umwickelt?","en":"Are pallets in good condition without visible damage and designed for the actual load? Are solid raw materials never stored higher than 2.5 meters? Are pallets at level 1 and above strapped or wrapped?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/62', 'compliance@1', 62, null, 'fire_protection_storage', 'fire_protection_storage.5', '5.4', true, '{"de":"„Der sichere Betrieb im Lager muss Folgendes umfassen: - Manuelles Kommissionieren mehr als eine Ebene über dem Boden…“","en":"Safe operation in warehouse shall include: - Manual picking more than one level above…"}'::jsonb, '{"de":"Der sichere Betrieb im Lager muss Folgendes umfassen:\n- Manuelles Kommissionieren mehr als eine Ebene über dem Boden ist nicht zulässig. Wenn Zählen erforderlich ist, muss ein zugelassenes Hebemittel verwendet werden.\n- Zwischen der Oberkante der Waren und dem darüberliegenden Träger muss ein Mindestabstand von 15 cm eingehalten werden\n- Toxische Rohstoffe müssen in einem eigens dafür vorgesehenen Bereich gelagert werden, der nicht höher als eine Ebene über dem Boden liegt und ordnungsgemäss gekennzeichnet ist","en":"Safe operation in warehouse shall include:\n- Manual picking more than one level above ground is not allowed. When counting is required, approved lifting device shall be used.\n- There shall be a minimum of 15 cm between the top of the goods and the beam above\n- Toxic raw materials shall be stored in a dedicated area not higher than one level above ground and with proper marking"}'::jsonb, '{"de":"Ist manuelles Kommissionieren oberhalb einer Ebene über dem Boden untersagt, sofern kein zugelassenes Hebemittel verwendet wird? Beträgt der Mindestabstand zwischen der Oberkante der gelagerten Waren und dem darüberliegenden Träger 15 cm? Werden toxische Rohstoffe in einem eigens dafür vorgesehenen Bereich in einer Höhe von höchstens einer Ebene über dem Boden mit ordnungsgemässer Kennzeichnung gelagert?","en":"Is manual picking above one level from the ground prohibited unless using an approved lifting device? Is there a minimum of 15 cm between the top of stored goods and the beam above? Are toxic raw materials stored in a dedicated area at a height no more than one level above ground with proper marking?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/63', 'compliance@1', 63, null, 'fire_protection_storage', 'fire_protection_storage.6', '6.1', true, '{"de":"„Der Be-/Entladebereich muss sich auf ebenem Gelände befinden, getrennt vom Verkehr und anderen…“","en":"Loading / off-loading location shall be on level area, separated from traffic and other…"}'::jsonb, '{"de":"Der Be-/Entladebereich muss sich auf ebenem Gelände befinden, getrennt vom Verkehr und anderen Gefahren, mit ausreichender Beleuchtung. Erdungswerkzeuge gegen statische Elektrizität sind beim Entladen brennbarer Stoffe zu verwenden","en":"Loading / off-loading location shall be on level area, separated from traffic and other hazards with adequate lighting. Grounding tools for static electricity use for flammable off-loading"}'::jsonb, '{"de":"Befindet sich der Be-/Entladebereich auf ebenem Gelände, getrennt vom Verkehr und ausreichend beleuchtet? Werden beim Entladen brennbarer Stoffe Erdungswerkzeuge gegen statische Elektrizität verwendet?","en":"Is the loading/off-loading location level, separated from traffic, and adequately lit? Are grounding tools used for static electricity in flammable off-loading?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/64', 'compliance@1', 64, null, 'fire_protection_storage', 'fire_protection_storage.6', '6.2', true, '{"de":"„Rohrleitungssysteme müssen deutlich mit Inhalt und Richtung gekennzeichnet sein, und die Stellung ‚Auf-Zu‘…“","en":"Piping systems shall be clearly marked with contents and directions and \"Open-close\"…"}'::jsonb, '{"de":"Rohrleitungssysteme müssen deutlich mit Inhalt und Richtung gekennzeichnet sein, und die Stellung „Auf-Zu“ der Hauptventile muss markiert sein","en":"Piping systems shall be clearly marked with contents and directions and \"Open-close\" position of major valves shall be marked"}'::jsonb, '{"de":"Sind Rohrleitungssysteme deutlich mit Inhalt und Richtung gekennzeichnet? Ist die Stellung „Auf-Zu“ der Hauptventile ordnungsgemäss markiert?","en":"Are piping systems clearly marked with contents and directions? Is the ''Open-close'' position of major valves properly marked?"}'::jsonb, false)
