insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/65', 'compliance@1', 65, null, 'fire_protection_storage', 'fire_protection_storage.6', '6.3', true, '{"de":"„Bewegung von Lastwagen: Unterlegkeile vorhanden, visuelle Anzeige (Fahnen, Lichter, Alarme) zur…“","en":"Movement of trucks : Wheel chocks in place, Visual indication (flags, lights, alarms) to…"}'::jsonb, '{"de":"Bewegung von Lastwagen: Unterlegkeile vorhanden, visuelle Anzeige (Fahnen, Lichter, Alarme) zur Kennzeichnung laufender Arbeiten, und Tankwagen sind konstruktionsbedingt nur in eine Richtung zu bewegen","en":"Movement of trucks : Wheel chocks in place, Visual indication (flags, lights, alarms) to designate operations taking place and Tank trucks only required to move in one direction by design"}'::jsonb, '{"de":"Sind Unterlegkeile für Lastwagen vorhanden? Werden visuelle Anzeigen wie Fahnen, Lichter und Alarme zur Kennzeichnung laufender Arbeiten verwendet? Sind Tankwagen so konstruiert, dass sie sich nur in eine Richtung bewegen können?","en":"Are wheel chocks in place for trucks? Are visual indicators such as flags, lights, and alarms used to designate operations? Are tank trucks designed to move only in one direction?"}'::jsonb, false)
