insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/66', 'compliance@1', 66, null, 'fire_protection_storage', 'fire_protection_storage.6', '6.4', true, '{"de":"„Gleise und Weichen müssen frei von Eis, Schnee und Schmutz gehalten werden und über eine ordnungsgemässe…“","en":"Tracks and switches shall be maintained free of ice, snow, debris and shall have a proper…"}'::jsonb, '{"de":"Gleise und Weichen müssen frei von Eis, Schnee und Schmutz gehalten werden und über eine ordnungsgemässe Entwässerung verfügen","en":"Tracks and switches shall be maintained free of ice, snow, debris and shall have a proper drainage"}'::jsonb, '{"de":"Werden Gleise und Weichen frei von Eis, Schnee und Schmutz gehalten und verfügen sie über eine ordnungsgemässe Entwässerung?","en":"Are tracks and switches maintained free of ice, snow, debris, and provided with proper drainage?"}'::jsonb, false)
