insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/67', 'compliance@1', 67, null, 'fire_protection_storage', 'fire_protection_storage.7', '7.1', true, '{"de":"Gabelstapler müssen regelmässig anhand einer Checkliste geprüft werden","en":"Forklifts shall be inspected regularly by using a checklist"}'::jsonb, '{"de":"Gabelstapler müssen regelmässig anhand einer Checkliste geprüft werden","en":"Forklifts shall be inspected regularly by using a checklist"}'::jsonb, '{"de":"Ist eine Checkliste für die regelmässige Prüfung von Gabelstaplern vorhanden?","en":"Is there a checklist in place for regular forklift inspections?"}'::jsonb, false)
