insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/68', 'compliance@1', 68, null, 'fire_protection_storage', 'fire_protection_storage.7', '7.2', true, '{"de":"Batterien müssen kontrolliert und regelmässig ausgetauscht werden (nicht bis zum Ausfall betreiben).","en":"Batteries shall be controlled and replaced regularly (not run to breakdown)."}'::jsonb, '{"de":"Batterien müssen kontrolliert und regelmässig ausgetauscht werden (nicht bis zum Ausfall betreiben). Die Batteriekontrolle muss im Serviceabkommen enthalten sein","en":"Batteries shall be controlled and replaced regularly (not run to breakdown). Control of batteries shall be included in the service agreement"}'::jsonb, '{"de":"Werden die Batterien der Gabelstapler regelmässig kontrolliert und vor einem Ausfall ausgetauscht? Ist die Batteriewartung im Serviceabkommen enthalten?","en":"Are forklift batteries regularly controlled and replaced before breakdown? Is battery maintenance included in the service agreement?"}'::jsonb, false)
