insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/69', 'compliance@1', 69, null, 'fire_protection_storage', 'fire_protection_storage.7', '7.3', true, '{"de":"„Ladestationen müssen ausserhalb von EX-Zonen platziert werden, so nah wie möglich am Ausgang und…“","en":"Charging stations shall be placed outside EX-zones; as close as possible to the exit and…"}'::jsonb, '{"de":"Ladestationen müssen ausserhalb von EX-Zonen platziert werden, so nah wie möglich am Ausgang und mit guter Belüftung. Kein brennbares Material näher als 1,5 m zur Ladestation","en":"Charging stations shall be placed outside EX-zones; as close as possible to the exit and with good ventilation. No combustible closer than 1.5m from charging station"}'::jsonb, '{"de":"Befinden sich die Ladestationen ausserhalb von EX-Zonen, in der Nähe von Ausgängen und gut belüftet? Befindet sich kein brennbares Material innerhalb von 1,5 Metern der Ladestation?","en":"Are charging stations located outside EX-zones, near exits, and well-ventilated? Is there no combustible material within 1.5 meters of the charging station?"}'::jsonb, false)
