insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/70', 'compliance@1', 70, null, 'fire_protection_storage', 'fire_protection_storage.7', '7.4', true, '{"de":"„Die Ladeeinheit muss an der Wand montiert oder am Boden befestigt und vor…“","en":"The charging unit shall be mounted on the wall or fixed to the floor and be protected…"}'::jsonb, '{"de":"Die Ladeeinheit muss an der Wand montiert oder am Boden befestigt und vor einem Anstoss durch den Gabelstapler geschützt sein","en":"The charging unit shall be mounted on the wall or fixed to the floor and be protected from being hit by the forklift"}'::jsonb, '{"de":"Ist die Ladeeinheit sicher an der Wand oder am Boden befestigt und vor einem Anstoss durch den Gabelstapler geschützt?","en":"Is the charging unit securely mounted on the wall or floor and protected from forklift impact?"}'::jsonb, false)
