values ('compliance@1/82', 'compliance@1', 82, null, 'ppe', 'ppe.1', '1.8', true, '{"de":"Sicherheitsschuhe sind obligatorisch in Produktion, Lager, Instandhaltung und Pilotlabors, jedoch nicht …","en":"Safety shoes are mandatory in production, warehouse, maintenance and pilot labs, but not…"}'::jsonb, '{"de":"Sicherheitsschuhe sind obligatorisch in Produktion, Lager, Instandhaltung und Pilotlabors, jedoch nicht in F&E- und Qualitätskontrolllabors. Sicherheitsschuhe müssen eine harte Schutzkappe aufweisen und antistatische Eigenschaften mindestens der Kategorie S1 gemäss EN ISO 20345 besitzen","en":"Safety shoes are mandatory in production, warehouse, maintenance and pilot labs, but not in R&D and Quality Control labs. Safety shoes shall be with hard top and have anti-static properties at least category S1 in accordance with EN ISO 20345"}'::jsonb, '{"de":"Sind Sicherheitsschuhe in den vorgesehenen Bereichen obligatorisch? Erfüllen sie die erforderliche Sicherheitskategorie (S1 gemäss EN ISO 20345)?","en":"Are safety shoes mandatory in the designated areas? Do they meet the required safety category (S1 according to EN ISO 20345)?"}'::jsonb, false)
