values ('compliance@1/84', 'compliance@1', 84, null, 'ppe', 'ppe.1', '1.10', true, '{"de":"Stosskappen sind obligatorisch in der Produktion, Schutzhelme zwischen den Gängen im Lagerregalbereich …","en":"Bump caps are mandatory in production, hard hats between the aisles in the storage rack…"}'::jsonb, '{"de":"Stosskappen sind obligatorisch in der Produktion, Schutzhelme zwischen den Gängen im Lagerregalbereich. Stosskappen müssen vom harten Typ sein und sorgfältig gelagert werden, um Risse zu vermeiden. Stosskappen haben aufgrund von UV-Einwirkung eine begrenzte Lebensdauer, und das Ablaufdatum muss auf der Kappe vermerkt sein","en":"Bump caps are mandatory in production, hard hats between the aisles in the storage rack area. Bump caps shall be of hard type hats and shall be stored with care to avoid cracking. Bump caps will have a limited life time due to UV exposure and the expiration date shall be marked on the hat"}'::jsonb, '{"de":"Werden Stosskappen in der Produktion und Schutzhelme in den Lagerregalbereichen verwendet? Werden sie ordnungsgemäss gelagert, um Risse zu vermeiden, und wird das Ablaufdatum aufgrund der UV-Einwirkung kontrolliert?","en":"Are bump caps used in production and hard hats in storage rack areas? Are they stored properly to avoid cracking and checked for UV exposure expiration?"}'::jsonb, false)
