values ('compliance@1/86', 'compliance@1', 86, null, 'ppe', 'ppe.1', '1.12', true, '{"de":"Risikobeurteilungen müssen den Bedarf an persönlicher Schutzausrüstung (PSA) wie Schürze,…","en":"Risk assessments shall identify need for personal protective equipment (PPE) like apron,…"}'::jsonb, '{"de":"Risikobeurteilungen müssen den Bedarf an persönlicher Schutzausrüstung (PSA) wie Schürze, Gesichtsschutz, Schutzbrille, Handschuhe, Filtermasken, Auffanggurt oder Ähnlichem ermitteln","en":"Risk assessments shall identify need for personal protective equipment (PPE) like apron, face shield, goggles, gloves, filter masks, harness or similar"}'::jsonb, '{"de":"Haben Risikobeurteilungen die erforderliche PSA für unterschiedliche Tätigkeiten ermittelt, wie Schürzen, Gesichtsschutz, Schutzbrillen, Handschuhe, Filtermasken und Auffanggurte?","en":"Have risk assessments identified the necessary PPE for different tasks, such as aprons, face shields, goggles, gloves, filter masks, and harnesses?"}'::jsonb, false)
