insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/89', 'compliance@1', 89, null, 'ppe', 'ppe.2', '2.1', true, '{"de":"Notdusche und Augenspülstation müssen: - gekennzeichnet, funktionsfähig und leicht…","en":"Emergency shower and eye wash station shall: - be marked, functional and easily…"}'::jsonb, '{"de":"Notdusche und Augenspülstation müssen:\n- gekennzeichnet, funktionsfähig und leicht zugänglich sein\n- innerhalb von 10 Sekunden oder 25 Metern von der offenen Handhabung von Gefahrstoffen liegen. Tragbare Augenspülflaschen können in Betracht gezogen werden, um die nächstgelegene Augenspülstation zu erreichen\n- eine Wassertemperatur von 16-38 °C aufweisen","en":"Emergency shower and eye wash station shall:\n- be marked, functional and easily accessible\n- be located within 10 seconds or 25 meter from open handling of hazardous chemicals. Portable eye wash bottles can be considered to reach the nearest eye wash station\n- have water temperature within 16-38 °C"}'::jsonb, '{"de":"Sind Notduschen und Augenspülstationen gekennzeichnet, funktionsfähig und leicht zugänglich? Befinden sie sich innerhalb von 10 Sekunden oder 25 Metern von Bereichen mit Handhabung von Gefahrstoffen? Wird die Wassertemperatur innerhalb von 16-38 °C gehalten?","en":"Are emergency showers and eye wash stations marked, functional, and easily accessible? Are they located within 10 seconds or 25 meters from hazardous chemical handling areas? Is the water temperature maintained within 16-38 °C?"}'::jsonb, false)
