values ('compliance@1/90', 'compliance@1', 90, null, 'ppe', 'ppe.2', '2.2', true, '{"de":"Der Standort muss einen zentralen Bereich für die Lagerung wichtiger Erste-Hilfe-Ausrüstung und als Treffpunkt festlegen…","en":"Site shall define a central area for storage of major first aid equipment and meeting…"}'::jsonb, '{"de":"Der Standort muss einen zentralen Bereich für die Lagerung wichtiger Erste-Hilfe-Ausrüstung und als Treffpunkt für das Erste-Hilfe-Team festlegen","en":"Site shall define a central area for storage of major first aid equipment and meeting point for First Aid Team"}'::jsonb, '{"de":"Hat der Standort einen zentralen Bereich für die Lagerung wichtiger Erste-Hilfe-Ausrüstung und einen Treffpunkt für das Erste-Hilfe-Team festgelegt?","en":"Has the site defined a central area for major first aid equipment storage and a meeting point for the First Aid Team?"}'::jsonb, false)
