insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/91', 'compliance@1', 91, null, 'ppe', 'ppe.2', '2.3', true, '{"de":"Der Erste-Hilfe-Kasten muss: - Anzahl, Standort und Inhalt werden vom Erste-Hilfe-Team festgelegt -…","en":"First aid kit shall: - be decided by first aid team about number, location and content -…"}'::jsonb, '{"de":"Der Erste-Hilfe-Kasten muss:\n- Anzahl, Standort und Inhalt werden vom Erste-Hilfe-Team festgelegt\n- keine Schmerzmittel enthalten\n- gekennzeichnet, sauber gehalten und leicht verfügbar sein\n- eine Inhaltsliste aufweisen und regelmässig kontrolliert werden","en":"First aid kit shall:\n- be decided by first aid team about number, location and content\n- not contain painkiller\n- be marked, kept clean and easily available\n- have a content list and regular control"}'::jsonb, '{"de":"Sind Erste-Hilfe-Kästen ordnungsgemäss platziert, gekennzeichnet, sauber und werden sie regelmässig kontrolliert? Sind sie frei von Schmerzmitteln?","en":"Are first aid kits properly placed, marked, clean, and regularly checked? Are they free of painkillers?"}'::jsonb, false)
