values ('compliance@1/92', 'compliance@1', 92, null, 'ppe', 'ppe.2', '2.4', true, '{"de":"Die Anzahl der Ersthelfer am Standort muss ausreichend sein, abhängig von der Gesamtzahl der Mitarbeitenden am Standort…","en":"Number of first aider on site shall be sufficient depending of total number of employees…"}'::jsonb, '{"de":"Die Anzahl der Ersthelfer am Standort muss ausreichend sein, abhängig von der Gesamtzahl der Mitarbeitenden am Standort und der Anzahl Schichten","en":"Number of first aider on site shall be sufficient depending of total number of employees on site and number of shift"}'::jsonb, '{"de":"Ist die Anzahl der Ersthelfer am Standort ausreichend, im Verhältnis zur Gesamtzahl der Mitarbeitenden und der Anzahl Schichten?","en":"Is there a sufficient number of first aiders on-site, proportional to the total number of employees and shifts?"}'::jsonb, false)
