values ('compliance@1/93', 'compliance@1', 93, null, 'ppe', 'ppe.2', '2.5', true, '{"de":"Die Notausgangstür muss: - keine sichtbaren Schäden aufweisen - selbstreflektierende Schilder…","en":"Emergency exit door shall: - have no visible damage - have self-reflective signs…"}'::jsonb, '{"de":"Die Notausgangstür muss:\n- keine sichtbaren Schäden aufweisen\n- selbstreflektierende Schilder aufweisen und über Notbeleuchtung verfügen\n- leicht zugänglich sein, ohne Hindernisse\n- zu einem Fluchtweg führen, der zum nächstgelegenen Sammelpunkt führt","en":"Emergency exit door shall:\n- have no visible damage\n- have self-reflective signs displayed and have emergency lights\n- be easy to access with no obstacles\n- lead to escape route which lead to closest assembly point"}'::jsonb, '{"de":"Sind die Notausgangstüren in einwandfreiem Zustand und ohne sichtbare Schäden? Verfügen sie über selbstreflektierende Schilder, Notbeleuchtung und einen ungehinderten Zugang? Führen sie zu Fluchtwegen, die zum nächstgelegenen Sammelpunkt führen?","en":"Are emergency exit doors in good condition with no visible damage? Do they have self-reflective signs, emergency lighting, and unobstructed access? Do they lead to escape routes that guide people to the closest assembly point?"}'::jsonb, false)
