insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/94', 'compliance@1', 94, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.1', '1.1', true, '{"de":"Der Standort muss über ein Toxikologieverfahren verfügen, das Folgendes umfasst: - wie die Einhaltung von…","en":"The site shall have a toxycology procedure that include: - how to be in compliance with…"}'::jsonb, '{"de":"Der Standort muss über ein Toxikologieverfahren verfügen, das Folgendes umfasst:\n- wie die Einhaltung des gesundheitsbasierten Expositionsgrenzwerts (Health-Based Exposure Limit, HBEL) für jede Verbindung sichergestellt wird\n- wie der HBEL aktualisiert wird und in welcher Häufigkeit\n- die Meldung und Untersuchung von Abweichungen bei Leachables und Extractables","en":"The site shall have a toxycology procedure that include:\n- how to be in compliance with the Health-Based Exposure Limit (HBEL) for each compound\n- how to update the HBEL and at which frequency\n- to report and investigate deviations from leachable and extractables"}'::jsonb, '{"de":"Verfügt der Standort über ein Toxikologieverfahren, das die Einhaltung des HBEL, dessen Aktualisierung und die Meldung von Abweichungen umfasst?","en":"Does the site have a toxicology procedure that includes HBEL compliance, updates, and deviation reporting?"}'::jsonb, false)
