insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/95', 'compliance@1', 95, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.1', '1.2', true, '{"de":"Der Standort muss über HBEL (Occupational Exposure Limit OEL und Permitted Daily Exposure…","en":"The site shall have HBEL (Occupational Exposure Limit OEL and Permitted Daily Exposure…"}'::jsonb, '{"de":"Der Standort muss über HBEL (Occupational Exposure Limit OEL und Permitted Daily Exposure PDE-Werte) für alle hergestellten Substanzen verfügen. Die Werte müssen mit einer angemessenen Dokumentation verwaltet werden (z. B. Voreinschätzung, Monografie sowie in der Corporate-Toxikologie-Datenbank (CTx) gespeicherte Werte; Verweise auf andere interne Datenbanken sind ebenfalls zulässig). Hinweis: PDE-Werte sind erforderlich für Active Pharmaceutical Ingredient (API) und Impurity Management (IM), OEL für alle gehandhabten Substanzen (Arbeitssicherheit)","en":"The site shall have HBEL (Occupational Exposure Limit OEL and Permitted Daily Exposure PDE values) for all substances manufactured. The values shall be managed with proper documentation (e.g. preliminary assessment, monograp, and values stored in the corporate toxicology (CTx) database (also references to other internal databases accepted). Note: PDE values needed for Active Pharmaceutical Ingredient (API) and Impurity Management (IM), OEL for all substances handeled (worker safety)"}'::jsonb, '{"de":"Sind HBEL-Werte (OEL und PDE) für alle hergestellten Substanzen ordnungsgemäss dokumentiert und verwaltet?","en":"Are HBEL values (OEL and PDE) documented and managed properly for all substances manufactured?"}'::jsonb, false)
