values ('compliance@1/98', 'compliance@1', 98, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.2', '2.1', true, '{"de":"Der Standort muss Staub, chemische Dämpfe, Lärm und Beleuchtung messen und die nationalen Vorschriften einhalten…","en":"The site shall measure dust, fume from chemicals, noise and illumination and be in line…"}'::jsonb, '{"de":"Der Standort muss Staub, chemische Dämpfe, Lärm und Beleuchtung messen und die nationalen Vorschriften einhalten. Diese Messungen müssen jährlich durch einen Dritten durchgeführt werden","en":"The site shall measure dust, fume from chemicals, noise and illumination and be in line with national regulations. These measurements shall be done annually by a third party"}'::jsonb, '{"de":"Werden Staub, Dämpfe, Lärm und Beleuchtung jährlich durch einen Dritten gemessen?","en":"Are dust, fumes, noise, and illumination measured annually by a third party?"}'::jsonb, false)
