values ('compliance@1/99', 'compliance@1', 99, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.2', '2.2', true, '{"de":"Der Standort muss festlegen, welche Arten von Lösungsmitteln in den verschiedenen Bereichen voraussichtlich vorhanden sind…","en":"The site shall decide what types of solvents are expected to be present in the different…"}'::jsonb, '{"de":"Der Standort muss festlegen, welche Arten von Lösungsmitteln in den verschiedenen Bereichen voraussichtlich vorhanden sind. Die entsprechenden arbeitsplatzbezogenen Expositionsgrenzwerte (OEL) müssen ermittelt und Messungen durchgeführt werden","en":"The site shall decide what types of solvents are expected to be present in the different areas. The corresponding occupational exposure limits (OEL) shall be identified and measurements shall be done"}'::jsonb, '{"de":"Hat der Standort arbeitsplatzbezogene Expositionsgrenzwerte (OEL) für Lösungsmittel ermittelt und die erforderlichen Messungen durchgeführt?","en":"Has the site identified occupational exposure limits (OEL) for solvents and conducted necessary measurements?"}'::jsonb, false)
