values ('compliance@1/100', 'compliance@1', 100, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.2', '2.3', true, '{"de":"Am Standort muss eine Lärmkarte erstellt werden.","en":"A noise map shall be developed at site."}'::jsonb, '{"de":"Am Standort muss eine Lärmkarte erstellt werden. Für Besucher und Mitarbeitende, die diesen Bereich nicht häufig besuchen, müssen Ohrstöpsel zur Verfügung stehen. Kapselgehörschützer sind für Mitarbeitende, die häufig in einem lärmintensiven Bereich arbeiten, verpflichtende persönliche Schutzausrüstung","en":"A noise map shall be developed at site. For visitors and employees not frequently visiting this area ear plugs shall be available. Earmuffs are mandatory personal protective equipment for employees working frequent in a noisy area"}'::jsonb, '{"de":"Wurde eine Lärmkarte erstellt und sind geeignete Gehörschutzmassnahmen vorhanden?","en":"Has a noise map been developed, and are appropriate ear protection measures in place?"}'::jsonb, false)
