values ('compliance@1/102', 'compliance@1', 102, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.2', '2.5', true, '{"de":"Der Standort muss die Risikobeurteilung nutzen, um hohe Risiken aufgrund von Ergonomie zu ermitteln, und Risiko…","en":"The site shall use the risk assessment to identify high risk due to ergonomics and risk…"}'::jsonb, '{"de":"Der Standort muss die Risikobeurteilung nutzen, um hohe Risiken aufgrund von Ergonomie zu ermitteln, und es müssen Risikominderungsmassnahmen in Betracht gezogen werden","en":"The site shall use the risk assessment to identify high risk due to ergonomics and risk mitigation actions shall be considered"}'::jsonb, '{"de":"Wurde eine Risikobeurteilung durchgeführt, um ergonomische Risiken und Minderungsmassnahmen zu ermitteln?","en":"Has a risk assessment been conducted to identify ergonomic risks and mitigation actions?"}'::jsonb, false)
