insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/103', 'compliance@1', 103, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.3', '3.1', true, '{"de":"Der Standort muss über einen Vertrag verfügen, der eine qualifizierte und regelmässige Unterstützung durch einen…","en":"The site shall have a contract in place to assure qualified and regular support from a…"}'::jsonb, '{"de":"Der Standort muss über einen Vertrag verfügen, der eine qualifizierte und regelmässige Unterstützung durch einen Arzt/eine Klinik sicherstellt. Ärztliche Untersuchungen müssen gemäss den örtlichen Gesetzen, Vorschriften oder Vereinbarungen mit Gewerkschaften durchgeführt werden.","en":"The site shall have a contract in place to assure qualified and regular support from a medical doctor/clinic. Medical check-ups shall be done in accordance with local laws, regulations or agreement with unions."}'::jsonb, '{"de":"Besteht ein Vertrag für medizinische Unterstützung, und werden ärztliche Untersuchungen gemäss den Vorschriften durchgeführt?","en":"Is there a contract in place for medical support, and are medical check-ups conducted as per regulations?"}'::jsonb, false)
