insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/104', 'compliance@1', 104, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.3', '3.2', true, '{"de":"Vor der Anstellung ist für alle Mitarbeitenden eine ärztliche Untersuchung durchzuführen.","en":"A medical check-up shall be done before employment for all employees."}'::jsonb, '{"de":"Vor der Anstellung ist für alle Mitarbeitenden eine ärztliche Untersuchung durchzuführen. Ärztliche Untersuchungen für Bediener und anderes Personal, das gefährlichen Chemikalien oder Lärm ausgesetzt ist, sollten in Abständen von höchstens 3 Jahren durchgeführt werden (lokale Abweichungen sind möglich).","en":"A medical check-up shall be done before employment for all employees. Medical check-ups for operators and other personnel exposed to hazardous chemicals or noise should be carried out with intervals no longer than 3 years (local variations might occur)."}'::jsonb, '{"de":"Werden ärztliche Voruntersuchungen und periodische Untersuchungen für Personal durchgeführt, das Gefährdungen ausgesetzt ist?","en":"Are pre-employment and periodic medical check-ups conducted for personnel exposed to hazards?"}'::jsonb, false)
