insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/105', 'compliance@1', 105, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.3', '3.3', true, '{"de":"Inhalt und Häufigkeit der ärztlichen Untersuchung müssen den nationalen Vorschriften entsprechen und…","en":"The medical check-up content and frequency shall comply with national regulations and be…"}'::jsonb, '{"de":"Inhalt und Häufigkeit der ärztlichen Untersuchung müssen den nationalen Vorschriften entsprechen und risikobasiert sein. Für Mitarbeitende, die mit infektiösen oder gefährlichen Materialien arbeiten, sollte das Programm ein Impfprogramm umfassen und die Risiken sowie Kontrollmassnahmen für gefährdete Beschäftigtengruppen identifizieren, z. B. schwangere Mitarbeiterinnen, Mitarbeitende mit bestehenden gesundheitlichen Vorerkrankungen.","en":"The medical check-up content and frequency shall comply with national regulations and be risk based. For employees working with infectious or hazardous materials, the program should cover immunizations program and identify the risk and control measures for susceptible group of employees e.g. pregnant staff, employees with pre-existing medical conditions."}'::jsonb, '{"de":"Umfasst das Programm der ärztlichen Untersuchungen Impfungen und eine Risikobeurteilung für gefährdete Mitarbeitende?","en":"Does the medical check-up program include immunizations and risk assessment for susceptible employees?"}'::jsonb, false)
