insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/106', 'compliance@1', 106, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.4', '4.1', true, '{"de":"Der Standort muss eine chemische Risikobeurteilung durchführen, einschliesslich: - Liste der toxischen Substanzen und…","en":"Site shall do a chemical risk assessment including: - list of toxic substance and…"}'::jsonb, '{"de":"Der Standort muss eine chemische Risikobeurteilung durchführen, einschliesslich:\n- Liste der toxischen Substanzen und der am Standort gelagerten Menge\n- Liste der CMR-Substanzen und der am Standort gelagerten Menge\n- Liste der sensibilisierenden Substanzen und der am Standort gelagerten Menge\n- Liste der korrosiven Substanzen und der am Standort gelagerten Menge\n- Liste der organischen Lösungsmittel und der am Standort gelagerten Menge\n- Liste der bestehenden Kontrollmassnahmen bei der Handhabung dieser Substanzen\n- Informationen zu chemischen Gefährdungen, d. h. Sicherheitsdatenblatt (SDS) und einseitige Chemikalieninformation am Arbeitsplatz\n- Erste Hilfe bei chemischen Vorfällen","en":"Site shall do a chemical risk assessment including:\n- list of toxic substance and quantity stored at site\n- list of CMR substance and quantity stored at site\n- list of sensitizing substance and quantity stored at site\n- list of corrosive substance and quantity stored at site\n- list of organic solvent substance and quantity stored at site\n- list of control measures in place when handling these substances\n- chemical hazard information. i.e. Safety Data Sheet (SDS) and one pager chemical information at workplace\n- first aid for chemical incidents"}'::jsonb, '{"de":"Hat der Standort eine chemische Risikobeurteilung durchgeführt und gefährliche Substanzen dokumentiert?","en":"Has the site conducted a chemical risk assessment and documented hazardous substances?"}'::jsonb, false)
