insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/107', 'compliance@1', 107, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.4', '4.2', true, '{"de":"Anforderungen an die Handhabung toxischer Materialien: - eine separate Lüftung ist obligatorisch.","en":"Handling of toxic materials requirements: - separate ventilation is mandatory."}'::jsonb, '{"de":"Anforderungen an die Handhabung toxischer Materialien:\n- eine separate Lüftung ist obligatorisch. Der Lüftungsauslass muss sich an einem sicheren Ort befinden und der Filter muss jährlich ersetzt werden.\n- Der Arbeitsplatz muss mit einem für toxische Substanzen ausgelegten Auffangset (Spill Kit) ausgerüstet sein\n- Bei der Handhabung toxischer Substanzen müssen Einweg- und vorbeschriftete Abfallbehälter vorhanden sein\n- Besteht ein Restrisiko der Exposition, gelten folgende zusätzliche Anforderungen an die persönliche Schutzausrüstung:\n• chemikalienbeständiger Einweg-Schutzanzug\n• doppelte Handschuhe (ein langer und ein kurzer Ärmel)\n• Filtermaske (mindestens P3) oder Frischluft-Atemschutzgerät\n• Gesichtsschutz","en":"Handling of toxic materials requirements:\n- separate ventilation is mandatory. The ventilation outlet shall be in a safe location and the filter shall be replaced on annual basis.\n- The workplace shall be prepared with spill kit designed to cover toxic substances\n- Disposable and pre-labelled waste basket shall be in place when handling toxic\n- If the residual risk of exposure is present, these are the additional requirements for personal protective equipment:\n• Chemical resistant disposable coverall\n• Double set of gloves (one long and one short sleeved)\n• Filter mask (minimum P3) or fresh air respirator\n• Face shield"}'::jsonb, '{"de":"Sind angemessene Lüftung, Auffangsets und Entsorgungsverfahren für die Handhabung toxischer Materialien vorhanden?","en":"Are proper ventilation, spill kits, and disposal procedures in place for handling toxic materials?"}'::jsonb, false)
