insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/108', 'compliance@1', 108, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.4', '4.3', true, '{"de":"Anforderungen an die Handhabung korrosiver Materialien: - Notdusche und Augenspülstationen…","en":"Handling of corrosive materials requirements: - Emergency shower and eye wash stations…"}'::jsonb, '{"de":"Anforderungen an die Handhabung korrosiver Materialien:\n- Notdusche und Augenspülstationen müssen in der Nähe (maximal 10 Sekunden oder 25 Meter) von Arbeitsplätzen, an denen korrosive Stoffe gehandhabt werden, verfügbar sein\n- Besteht ein Restrisiko der Exposition, gelten folgende zusätzliche Anforderungen an die persönliche Schutzausrüstung:\n• chemikalienbeständige langärmelige Handschuhe\n• Schutzbrille\n• Gesichtsschutz, Schürze und Gummistiefel sind nicht obligatorisch, sollten aber je nach Tätigkeit berücksichtigt werden","en":"Handling of corrosive materials requirements:\n- Emergency shower and eye wash stations shall be available in vicinity (maximum 10 seconds or 25 meters) of work stations where corrosives are handled\n- If the residual risk of exposure is present, these are the additional requirements for personal protective equipment:\n• Chemical resistant long sleeved gloves\n• Goggles\n• Face-shield, apron and rubber boots are not mandatory, but shall be considered due to task operation"}'::jsonb, '{"de":"Sind Notduschen, Augenspülstationen und Schutzausrüstung für die Handhabung korrosiver Materialien vorhanden?","en":"Are emergency showers, eye wash stations, and protective equipment available for corrosive material handling?"}'::jsonb, false)
