values ('compliance@1/109', 'compliance@1', 109, null, 'industrial_hygiene_sampling', 'industrial_hygiene_sampling.4', '4.4', true, '{"de":"Anforderungen an die Handhabung von CMR-/toxischen/sensibilisierenden/korrosiven/organischen Lösungsmitteln: - Jede Leckage…","en":"Handling of CMR/toxic/sensitizing/corrosive/organic solvent requirements: - Any leakage…"}'::jsonb, '{"de":"Anforderungen an die Handhabung von CMR-/toxischen/sensibilisierenden/korrosiven/organischen Lösungsmitteln:\n- Jede Leckage oder jeder Austritt muss unverzüglich gemeldet und behoben werden\n- Ordnung und Sauberkeit sind wesentlich, der Arbeitsplatz muss stets sauber und aufgeräumt sein\n- Das Personal muss aufgrund der chemischen Gefährdung jährlich eine spezifische Schulung erhalten. Aufzeichnungen müssen 5 Jahre lang aufbewahrt werden (bei CMR-Substanzen 50 Jahre).","en":"Handling of CMR/toxic/sensitizing/corrosive/organic solvent requirements:\n- Any leakage or spill shall be reported and corrected immediately\n- Housekeeping is essential, and the workplace shall always be clean and tidy\n- Personnel shall have annual specific training due to the chemical hazard. Records shall be kept for 5 years. (records kept for 50 years in the case of CMR)"}'::jsonb, '{"de":"Sind Meldung von Leckagen, Ordnung/Sauberkeit und jährliche Schulungen zu chemischen Gefährdungen umgesetzt und dokumentiert?","en":"Are spill reporting, housekeeping, and annual chemical hazard training implemented and documented?"}'::jsonb, false)
