values ('compliance@1/115', 'compliance@1', 115, null, 'projects', 'projects.1', '1.1', true, '{"de":"Es muss ein Verfahren geben, das den Beschaffungsanforderungsprozess vor Ort erläutert…","en":"There shall be a procedure explaining the procurement requirements process at site…"}'::jsonb, '{"de":"Es muss ein Verfahren geben, das den Beschaffungsanforderungsprozess vor Ort in Bezug auf EHS erläutert. Das heisst, neue Produkte werden im Einklang mit den EHS-Anforderungen beschafft. Personen, die für den Einkauf dieser Produkte verantwortlich sind, müssen regelmässig zu Sicherheits- und Nachhaltigkeitsanforderungen geschult werden.","en":"There shall be a procedure explaining the procurement requirements process at site related to EHS. i.e. new product purchased in line with EHS requirements. People responsible to buy these product shall be regularly trained on safety & sustainability requirements."}'::jsonb, '{"de":"Verfügt der Standort über ein Beschaffungsverfahren, das die EHS-Konformität von eingekauften Produkten sicherstellt?","en":"Does the site have a procurement procedure ensuring EHS compliance for purchased products?"}'::jsonb, false)
