values ('compliance@1/117', 'compliance@1', 117, null, 'projects', 'projects.2', '2.2', true, '{"de":"Das formelle Auswahlprogramm für Auftragnehmer muss Folgendes umfassen: - Unfall- und Erkrankungsaufzeichnungen; -…","en":"Formal selection program for contractors shall includes: - Injury and illness records; -…"}'::jsonb, '{"de":"Das formelle Auswahlprogramm für Auftragnehmer muss Folgendes umfassen:\n- Unfall- und Erkrankungsaufzeichnungen;\n- Sicherheits- und nachhaltigkeitsbezogene behördliche Beanstandungen, Bussgelder oder Strafen;\n- Erfahrungsbasierter Modifikationsfaktor der Unfallversicherung (Experience Modification Rate) (soweit anwendbar);\n- Qualifikations-/Fachzertifizierungen;\n- Sicherheits- und Nachhaltigkeitsschulung und -kompetenz; und\n- Schriftliches Material zu Sicherheits- und Nachhaltigkeitsprogrammen sowie Schulungsprogramme","en":"Formal selection program for contractors shall includes:\n- Injury and illness records;\n- Safety and sustainability related regulatory citations, fines, or penalties;\n- Worker’s compensation experience modification rate (where applicable);\n- Job/skill certifications;\n- Safety and sustainability training and competency; and\n- Written safety and sustainability program materials and training programs"}'::jsonb, '{"de":"Umfasst der Auswahlprozess für Auftragnehmer Aufzeichnungen zu Sicherheit, Einhaltungsvergangenheit, Schulung und Qualifikationsnachweisen?","en":"Does the contractor selection process include records of safety, compliance history, training, and job certifications?"}'::jsonb, false)
