insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/118', 'compliance@1', 118, null, 'projects', 'projects.2', '2.3', true, '{"de":"Für ein Grossprojekt muss ein EHS-Auftragnehmerplan erstellt werden, der vom Auftragnehmer entwickelt und…","en":"For a major project there shall be a EHS contractor plan developed by the contractor and…"}'::jsonb, '{"de":"Für ein Grossprojekt muss ein EHS-Auftragnehmerplan erstellt werden, der vom Auftragnehmer entwickelt und vom Unternehmen überprüft wird. Das heisst, beim Bau neuer Anlagen oder der Modernisierung bestehender Anlagen. Der Plan muss Folgendes abdecken:\n- EHS-Ressourcen der Auftragnehmer auf der Baustelle\n- Eine Risikobeurteilung der Tätigkeiten des Auftragnehmers\n- EHS-Schulung für das Personal des Auftragnehmers\n- Verfahren für Arbeitsfreigaben (Permit)\n- PSA\n- Vorfallmeldung und -untersuchung\n- Inspektionsprogramm und Korrekturmassnahmen\n- EHS-Besprechung","en":"For a major project there shall be a EHS contractor plan developed by the contractor and reviewed by the company. i.e. construction of new facilities, upgrading existing facility. The plan shall cover:\n- EHS resources at construction site by contractors\n- A risk assessment of contractor''s activities\n- EHS training for contrator staffs\n- Work permit procedure\n- PPE\n- Incident reporting and Investigation\n- Inspection program and corrective actions\n- EHS meeting"}'::jsonb, '{"de":"Gibt es für Grossprojekte einen EHS-Auftragnehmerplan, der Risikobeurteilung, Schulung, PSA und Vorfallmeldung abdeckt?","en":"For major projects, is there an EHS contractor plan covering risk assessment, training, PPE, and incident reporting?"}'::jsonb, false)
