values ('compliance@1/119', 'compliance@1', 119, null, 'projects', 'projects.2', '2.4', true, '{"de":"Die jährliche EHS-Einführung für Auftragnehmer muss Folgendes abdecken: - Eine Überprüfung der Gefährdungen vor Ort - PSA…","en":"Annual EHS contractor induction shall cover: - A review of site hazards - PPE…"}'::jsonb, '{"de":"Die jährliche EHS-Einführung für Auftragnehmer muss Folgendes abdecken:\n- Eine Überprüfung der Gefährdungen vor Ort\n- PSA-Anforderungen\n- Kritische Arbeitsverfahren und -anforderungen des Unternehmens\n- Anforderungen zur Vorfallmeldung\n- Protokolle für medizinische Hilfe\n- Notfallverfahren vor Ort.\nEs muss ein schriftlicher/digitaler Test für jeden Auftragnehmer durchgeführt werden","en":"Annual EHS contractor induction shall cover:\n- A review of site hazards\n- PPE requirements\n- Company critical work procedures and requirements\n- Incident reporting requirements\n- Medical assistance protocols\n- Site emergency procedures.\nA written/ digital test shall be given to each contractor"}'::jsonb, '{"de":"Deckt die jährliche EHS-Einführung für Auftragnehmer Gefährdungen vor Ort, PSA, kritische Arbeitsverfahren und Notfallmassnahmen ab?","en":"Does the annual EHS contractor induction cover site hazards, PPE, critical work procedures, and emergency response?"}'::jsonb, false)
