insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/125', 'compliance@1', 125, null, 'projects', 'projects.3', '3.4', true, '{"de":"In der Konzeptphase ist Folgendes durchzuführen: - eine Risikobeurteilung auf hohem Niveau -…","en":"At conceptual design stage, the following shall be done: - a high level risk assessment -…"}'::jsonb, '{"de":"In der Konzeptphase ist Folgendes durchzuführen:\n- eine Risikobeurteilung auf hohem Niveau\n- Ermittlung der wichtigsten lokalen und nationalen EHS-Vorschriften und anwendbaren Rechtsvorschriften\n- EHS-Rollen und -Verantwortlichkeiten\n- alle Erkenntnisse aus früheren ähnlichen Projekten\n- eine EHS-Überprüfung durch die interessierten Parteien, abgezeichnet durch den Projektleiter","en":"At conceptual design stage, the following shall be done:\n- a high level risk assessment\n- identification of main local and national EHS codes and applicable legislations\n- EHS roles and responsibilities\n- any lessons learned from previous similar projects\n- an EHS review by stakeholder and signed off by project manager"}'::jsonb, '{"de":"Werden während der Konzeptphase Risikobeurteilungen, EHS-Vorschriften, Rollen und Erkenntnisse aus früheren Projekten überprüft?","en":"During conceptual design, are risk assessments, EHS regulations, roles, and previous project lessons reviewed?"}'::jsonb, false)
