insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/126', 'compliance@1', 126, null, 'projects', 'projects.3', '3.5', true, '{"de":"In der Basic-Design-Phase ist Folgendes durchzuführen: - eine vorläufige Risikobeurteilung mit…","en":"At basic design stage, the following shall be done: - a preliminary risk assessment with…"}'::jsonb, '{"de":"In der Basic-Design-Phase ist Folgendes durchzuführen:\n- eine vorläufige Risikobeurteilung mit ihren Kontrollmassnahmen\n- EHS-Schulung für das Projektteam\n- Arbeitsfreigabesystem (Permit to Work) für die Bauphase\n- Entwicklung / Überprüfung eines Vorfallmeldesystems\n- eine EHS-Überprüfung durch die interessierten Parteien, abgezeichnet durch den Projektleiter","en":"At basic design stage, the following shall be done:\n- a preliminary risk assessment with its control measures\n- EHS training for project team\n- permit to work system for construction phase\n- development / review of an incident reporting system\n- an EHS review by stakeholder and signed off by project manager"}'::jsonb, '{"de":"Werden während der Basic-Design-Phase Risikobeurteilungen, EHS-Schulungen, Vorfallmeldungen und Arbeitsfreigaben (Permits) berücksichtigt?","en":"During basic design, are risk assessments, EHS training, incident reporting, and work permits addressed?"}'::jsonb, false)
