insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/127', 'compliance@1', 127, null, 'projects', 'projects.3', '3.6', true, '{"de":"In der Detail-Engineering-Phase ist Folgendes durchzuführen: - detaillierte Risikobeurteilung mit…","en":"At detailed design stage, the following shall be done: - detailed risk assessment with…"}'::jsonb, '{"de":"In der Detail-Engineering-Phase ist Folgendes durchzuführen:\n- detaillierte Risikobeurteilung mit Kontrollmassnahmen\n- Risikobeurteilung für die Bauphase\n- Plan zur Umsetzung der unternehmensinternen EHS-Anforderungen für die Bauphase\n- Risikobeurteilung der Inbetriebnahmephase (bei Inbetriebnahme)\n- eine EHS-Überprüfung durch die interessierten Parteien, abgezeichnet durch den Projektleiter","en":"At detailed design stage, the following shall be done:\n- detailed risk assessment with control measures\n- construction risk assessment\n- plan to implement the company EHS requirement for construction phase\n- risk assessment of the commissioning phase (when going live)\n- an EHS review by stakeholder and signed off by project manager"}'::jsonb, '{"de":"Werden während der Detail-Engineering-Phase Risikobeurteilungen für Bau und Inbetriebnahme durchgeführt und überprüft?","en":"During detailed design, are construction and commissioning risk assessments performed and reviewed?"}'::jsonb, false)
