insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/128', 'compliance@1', 128, null, 'projects', 'projects.3', '3.7', true, '{"de":"In der Inbetriebnahme- und Anlaufphase ist Folgendes durchzuführen: - eine Risikobeurteilung der…","en":"At commissioning and start-up stage, the following shall be done: - a risk assessment of…"}'::jsonb, '{"de":"In der Inbetriebnahme- und Anlaufphase ist Folgendes durchzuführen:\n- eine Risikobeurteilung des Explosionsschutzes, eine Beurteilung der Chemikalienexposition und eine Job Safety Analysis\n- ein vorbeugendes Wartungsprogramm mit dem Inspektions- und Prüfregime für sicherheitskritische Ausrüstung\n- SOPs (Standardarbeitsanweisungen) sind zu entwickeln\n- Sicherheitsprüfung vor Inbetriebnahme (PSSR) vor Beginn des Betriebs. Diese umfasst die Anlageninspektion, die Überprüfung der SOPs und der Ausrüstung, die Inspektion durch Behörden (z. B. Brandschutzanlagen)\n- alle Verantwortlichen jeder Disziplin müssen bestätigen, dass die Anlagen sicher betrieben werden können\n- eine EHS-Überprüfung durch die interessierten Parteien, abgezeichnet durch den Projektleiter","en":"At commissioning  and start-up stage, the following shall be done:\n- a risk assessment of the explosion protection, assessment of exposure to chemicals and a job safety analysis\n- preventive maintenance program with the inspection and testing regime of safety critical equipment\n- SOP shall be developped\n- pre-start-up safety review before starting operations. This include plant inspection, review of SOP and equipment, inspection by authorities (i.e. fire fighting systems)\n- all responsible person for each discipline shall confirm that installation are safe to be operated\n- an EHS review by stakeholder and signed off by project manager"}'::jsonb, '{"de":"Werden bei Inbetriebnahme/Anlauf Explosionsschutz, Chemikalienexposition, Sicherheitsanalysen und Sicherheitsprüfungen vor Inbetriebnahme (PSSR) durchgeführt?","en":"At commissioning/start-up, are explosion protection, chemical exposure, safety analysis, and pre-start safety checks conducted?"}'::jsonb, false)
