values ('compliance@1/129', 'compliance@1', 129, null, 'projects', 'projects.3', '3.8', true, '{"de":"Einige Monate nach Betriebsaufnahme des Projekts ist eine EHS-Überprüfung durchzuführen, um…","en":"An EHS review shall be conducted few months after the project has been in operation to…"}'::jsonb, '{"de":"Einige Monate nach Betriebsaufnahme des Projekts ist eine EHS-Überprüfung durchzuführen, um bewährte Praktiken zu teilen und sicherzustellen, dass das Projekt planmässig und innerhalb des Budgets betrieben wird.","en":"An EHS review shall be conducted few months after the project has been in operation to share best practices and to make sure the project operate as plan and has been within budget."}'::jsonb, '{"de":"Wird nach der Projektumsetzung eine EHS-Überprüfung durchgeführt, um die Einhaltung und bewährte Praktiken zu verifizieren?","en":"Is an EHS review conducted after project implementation to verify compliance and best practices?"}'::jsonb, false)
