insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/130', 'compliance@1', 130, null, 'projects', 'projects.3', '3.9', true, '{"de":"In der Ausserbetriebnahme- und Abbruchphase sind zu berücksichtigen: - Asbest - Verunreinigung in…","en":"Decommissioning and demolition phase shall consider: - asbestos - contamination in…"}'::jsonb, '{"de":"In der Ausserbetriebnahme- und Abbruchphase sind zu berücksichtigen:\n- Asbest\n- Verunreinigung des Bodens, der Struktur oder des Wassers\n- strukturelle Stabilität - Untersuchung zum Verständnis der Integrität der zu entfernenden Struktur\n- spezielle Dienstleistungen - Ermittlung von Leistungen, die durch Spezialisten erbracht werden müssen (z. B. Lösungsmittel, Dampfleitungen usw.)\n- Versorgungseinrichtungen und Dienstleistungen - welche Leistungen beendet werden müssen und welche während der Auslaufphase weiterlaufen müssen (z. B. Wartung des Brandschutzsystems)","en":"Decommissioning and demolition phase shall consider:\n- asbestos\n- contamination in ground, structure or water\n- structural stability - survey to understand the integrity of the structure to be removed\n- special services - identify services that will need to be done by specialist (i.e. solvent, steam line, ...)\n- utilities and services - which services need to be terminated and which need to continue during the phase out (i.e. fire fighting system maintenance)"}'::jsonb, '{"de":"Werden bei der Ausserbetriebnahme Asbest, Verunreinigungen, Stabilität, spezielle Dienstleistungen und die Beendigung von Versorgungseinrichtungen beurteilt?","en":"During decommissioning, are asbestos, contamination, stability, special services, and utility terminations assessed?"}'::jsonb, false)
