insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/131', 'compliance@1', 131, null, 'security', 'security.1', '1.1', true, '{"de":"„Der Standort muss ein Verfahren für den Sicherheitsbetrieb entwickeln: - Zugangskontrolle für Mitarbeiter,…“","en":"Site shall develop a procedure for security operations: - access control for employees,…"}'::jsonb, '{"de":"Der Standort muss ein Verfahren für den Sicherheitsbetrieb entwickeln:\n- Zugangskontrolle für Mitarbeiter, Besucher und Auftragnehmer\n- Notfallkontakte\n- Umgang mit Einbrüchen/Eindringen\n- Verfahren zur Schlüsselkontrolle\n- fotografische Geräte\n- Verfahren bei Bombendrohung\n- Verfahren bei Terrordrohung\n- Sicherheit für besondere Vermögenswerte und Standorte\nEinschliesslich der Registrierung aller nicht firmeneigenen Fahrzeuge, die Zugang innerhalb des gesicherten Perimeters des Standorts benötigen","en":"Site shall develop a procedure for security operations:\n- access control for employees, visitors and contractors\n- emergency contacts\n- intrusion handling\n- key control procedure\n- photographic device\n- bomb threat procedure\n- terroris threat procedure\n- security for special assets and locations\nIncluding registration of any non-company owned vehicles requiring access inside the secured peremeter of the site"}'::jsonb, '{"de":"Verfügt der Standort über ein dokumentiertes Verfahren für den Sicherheitsbetrieb, einschliesslich Zugangskontrolle, Notfallkontakten und Umgang mit Einbrüchen/Eindringen?","en":"Does the site have a documented procedure for security operations, including access control, emergency contacts, and intrusion handling?"}'::jsonb, false)
