insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/133', 'compliance@1', 133, null, 'security', 'security.1', '1.3', true, '{"de":"„Der Standort muss eine Sicherheits-Bedrohungs- und Schwachstellenanalyse durchführen: - überprüft…“","en":"The site shall conduct a security Threat and Vulnerability assessment: - reviewed…"}'::jsonb, '{"de":"Der Standort muss eine Sicherheits-Bedrohungs- und Schwachstellenanalyse durchführen:\n- jährlich überprüft\n- der Standort hat Hochrisiko-Vermögenswerte klar identifiziert und grundlegende Sicherheitskonzepte zur Risikokontrolle etabliert\n- der Standort hat Ereignisse identifiziert, die Bedrohungen für den Vermögenswert erzeugen\n- Kontrollen wurden für definierte kritische Ausrüstung und Standorte des Standorts etabliert (z. B. Be-/Entladebereiche für Gefahrgut und geschäftskritische Materialien, Lagerbereiche für diese Materialien, Luftversandlagerung, Biogefahrenbereiche, Labore, Kontrollräume für kritische Prozesse mit Gefahrstoffen oder biogefährlichen Materialien, Lagerbereiche für Finanzunterlagen und Personalunterlagen, Kassenräume oder Bereiche, in denen Bargeld des Unternehmens aufbewahrt wird).","en":"The site shall conduct a security Threat and Vulnerability assessment:\n- reviewed annually\n- site has clearly identified high risk assets and has established basic security concepts to control risks\n- site has identified event that generates threats to the asset\n- Controls have been established for defined Critical Equipment and Locations of the site (i.e. loading/ unloading areas for hazardous material and business critical materials, storage areas for these materials, air shipment storage, bio-hazard areas, laboratories, Control rooms for critical processes using hazardous or biohazardous materials, storage areas for financial files and HR files, cashier rooms or areas where company cash is stored)."}'::jsonb, '{"de":"Hat der Standort eine Sicherheits-Bedrohungs- und Schwachstellenanalyse durchgeführt, einschliesslich Identifikation von Hochrisiko-Vermögenswerten und Kontrollmassnahmen?","en":"Has the site conducted a security Threat and Vulnerability assessment, including high-risk asset identification and control measures?"}'::jsonb, false)
