insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/135', 'compliance@1', 135, null, 'security', 'security.1', '1.5', true, '{"de":"„Die Anlage muss gegen unbefugten Zugang ausgestattet sein: kontrollierte Zugangspunkte,…“","en":"Facility shall be equipped against unauthorized access: controlled access points,…"}'::jsonb, '{"de":"Die Anlage muss gegen unbefugten Zugang ausgestattet sein: kontrollierte Zugangspunkte, Perimeterkontrolle wie Zäune, Wachpersonal, elektronische Überwachung, Einbruchserkennung, Einsatz von Videoüberwachung (CCTV)","en":"Facility shall be equipped against unauthorized access: controlled access points, perimeter control such as fences, guards, electronic surveillance, intrusion detection, use of CCTV"}'::jsonb, '{"de":"Ist die Anlage mit Sicherheitskontrollen wie Zäunen, Wachpersonal, CCTV und Einbruchserkennung ausgestattet?","en":"Is the facility equipped with security controls such as fences, guards, CCTV, and intrusion detection?"}'::jsonb, false)
