insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/136', 'compliance@1', 136, null, 'security', 'security.1', '1.6', true, '{"de":"„Zugangskontrolle für Personen, die keine Mitarbeiter des Unternehmens sind (Besucher, Auftragnehmer, LKW- und Bahnpersonal)…“","en":"Access control for people who are not employees of the company (visitors, contractors, truck and railroad personnel)…"}'::jsonb, '{"de":"Die Zugangskontrolle für Personen, die keine Mitarbeiter des Unternehmens sind (Besucher, Auftragnehmer, LKW- und Bahnpersonal), muss die Überprüfung von Ausweisdokumenten, die Unterzeichnung von Vertraulichkeitsvereinbarungen (NDA) und, wo erforderlich, Hintergrundüberprüfungen umfassen. Der Zugang ist auf vorab genehmigte Bereiche beschränkt, oder der Besucher muss von einem Mitarbeiter des Unternehmens begleitet werden. HINWEIS: Ausnahmen sind zulässig","en":"Access control for people who are not employees of the company (visitors, contractors, truck and railroad personnel) shall includes the checking of id cards, signing of non-disclosure agreements, and where required, background checks. Access limited to pre-approved areas or requires the visitor to be escorted by an employee of the company. NOTE: Exemptions are applicable"}'::jsonb, '{"de":"Bestehen Zugangskontrollen für Personen, die keine Mitarbeiter des Unternehmens sind, einschliesslich Ausweiskontrollen, Vertraulichkeitsvereinbarungen (NDA) und Hintergrundüberprüfungen?","en":"Are access controls in place for people who are not employees of the company, including ID checks, NDAs, and background verification?"}'::jsonb, false)
