values ('compliance@1/138', 'compliance@1', 138, null, 'security', 'security.1', '1.8', true, '{"de":"„Eine Überprüfung aller elektronischen und physischen Sicherheitskontrollen (einschliesslich Zugangskontrolle)…“","en":"A review of all electronic and physical security controls (including access control)…"}'::jsonb, '{"de":"Eine Überprüfung aller elektronischen und physischen Sicherheitskontrollen (einschliesslich Zugangskontrolle) muss jährlich durchgeführt werden","en":"A review of all electronic and physical security controls (including access control) shall be conducted annually"}'::jsonb, '{"de":"Wird jährlich eine Überprüfung der elektronischen und physischen Sicherheitskontrollen, einschliesslich Zugangskontrolle, durchgeführt?","en":"Is an annual review of electronic and physical security controls, including access control, conducted?"}'::jsonb, false)
