insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/139', 'compliance@1', 139, null, 'security', 'security.2', '2.1', true, '{"de":"„Der Standort muss über einen Business-Continuity-Plan verfügen, der Folgendes umfasst: - kritische Vermögenswerte und Informationen…“","en":"Site shall have a Business continuity plan including: - critical assets and information…"}'::jsonb, '{"de":"Der Standort muss über einen Business-Continuity-Plan verfügen, der Folgendes umfasst:\n- kritische Vermögenswerte und Informationsbedarf\n- Risikoanalyse und Geschäftsauswirkungsanalyse mit Risikomatrix und Risikominderung\n- Kontinuitätsverfahren für jeden analysierten kritischen Prozess\n- angemessenes Eskalationsverfahren je nach Art der Katastrophe\n- alle 2 Jahre überprüft","en":"Site shall have a Business continuity plan including:\n- critical assets and information needs\n- risk analysis and business impact analysis with risk matrix and risk mitigation\n- continuity procedure for each critical process analyzed\n- adequate escalation procedure depending of nature of disaster\n- reviewed every 2 years"}'::jsonb, '{"de":"Verfügt der Standort über einen Business-Continuity-Plan, der kritische Vermögenswerte, Risikoanalysen, Kontinuitätsverfahren und Eskalationspläne abdeckt?","en":"Does the site have a Business Continuity Plan covering critical assets, risk analysis, continuity procedures, and escalation plans?"}'::jsonb, false)
