values ('compliance@1/145', 'compliance@1', 145, null, 'line_breaking', 'line_breaking.1', '1.5', true, '{"de":"Die Arbeitsfreigaben müssen von Ausstellern/Beschäftigten unterzeichnet und in einem kontrollierten Bereich aufbewahrt werden","en":"Permits shalle be signed by issuers/workers and retained in a controlled area."}'::jsonb, '{"de":"Die Arbeitsfreigaben müssen von Ausstellern/Beschäftigten unterzeichnet und in einem kontrollierten Bereich aufbewahrt werden. Die Arbeitsfreigabe muss vollständig und korrekt ausgefüllt sein; gültig für eine Schicht.","en":"Permits shalle be signed by issuers/workers and retained in a controlled area. Permit shall be filled out completely and accurately; valid for one shift."}'::jsonb, '{"de":"Werden die Arbeitsfreigaben von Ausstellern/Beschäftigten unterzeichnet und in einem kontrollierten Bereich aufbewahrt, gültig für eine Schicht?","en":"Are permits signed by issuers/workers and retained in a controlled area, valid for one shift?"}'::jsonb, false)
