values ('compliance@1/146', 'compliance@1', 146, null, 'line_breaking', 'line_breaking.1', '1.6', true, '{"de":"Eine Feldverifizierung durch die Führungskraft/Vorgesetzten muss durchgeführt werden, dass Leitungen ordnungsgemäss entleert/gespült wurden…","en":"Field verification shall be conduceted by manager/supervisor that lines drained/flushed…"}'::jsonb, '{"de":"Eine Feldverifizierung durch die Führungskraft/Vorgesetzten muss durchgeführt werden, dass Leitungen ordnungsgemäss entleert/gespült, Entlüftungs- und Ablassventile geöffnet und die Energie abgebaut wurde.","en":"Field verification shall be conduceted by manager/supervisor that lines drained/flushed properly, vents and drain valves opened, energy dissipated."}'::jsonb, '{"de":"Wird eine Feldverifizierung durch eine Führungskraft/Vorgesetzten durchgeführt, um sicherzustellen, dass Leitungen ordnungsgemäss entleert/gespült und Entlüftungs-/Ablassventile geöffnet sind?","en":"Is field verification conducted by a manager/supervisor to ensure lines are properly drained/flushed, and vents/drain valves are opened?"}'::jsonb, false)
