values ('compliance@1/147', 'compliance@1', 147, null, 'line_breaking', 'line_breaking.1', '1.7', true, '{"de":"Die Feldverifizierung muss beinhalten, dass Absperrventile geschlossen und Pumpen gemäss LOTO-Freigabe gestoppt sind…","en":"Field verification shall include that isolation valves are closed, pumps stopped in…"}'::jsonb, '{"de":"Die Feldverifizierung muss beinhalten, dass Absperrventile geschlossen und Pumpen gemäss LOTO-Freigabe gestoppt sind. Alle Absperrpunkte müssen identifiziert werden. Für Absperrzwecke dürfen nur formschlüssig dichtende Absperrventile (Schieber, Ventil-, Kugel-, Kükenhahn-, Nadel- und Membranventile) verwendet werden.","en":"Field verification shall include that isolation valves are closed, pumps stopped in accordance with LOTO permit. All isolating points shall be identified. Only positive shutoff valves (gate, globe, ball, plug, needle, and diaphram valves) used for isolation purposes."}'::jsonb, '{"de":"Umfasst die Feldverifizierung die Prüfung, dass Absperrventile geschlossen sind, Pumpen gestoppt sind und nur formschlüssig dichtende Absperrventile verwendet werden?","en":"Does field verification include checking that isolation valves are closed, pumps are stopped, and only positive shutoff valves are used?"}'::jsonb, false)
