values ('compliance@1/149', 'compliance@1', 149, null, 'line_breaking', 'line_breaking.1', '1.9', true, '{"de":"Vor dem Öffnen von Leitungen im Einsatz mit brennbaren Stoffen muss eine Brennbarkeitsprüfung durchgeführt werden","en":"Flammability test shall be made before breaking lines in flammable material service."}'::jsonb, '{"de":"Vor dem Öffnen von Leitungen im Einsatz mit brennbaren Stoffen muss eine Brennbarkeitsprüfung durchgeführt werden. (Messwerte < 3% UEG und < 22% O2 vor dem Öffnen).","en":"Flammability test shall be made before breaking lines in flammable material service. (Readings < 3% LEL and < 22% O2 before breaking)."}'::jsonb, '{"de":"Wird vor dem Öffnen von Leitungen im Einsatz mit brennbaren Stoffen eine Brennbarkeitsprüfung durchgeführt, um sicherzustellen, dass die Messwerte <3% UEG und <22% O2 betragen?","en":"Is a flammability test conducted before breaking lines in flammable material service, ensuring readings are <3% LEL and <22% O2?"}'::jsonb, false)
