values ('compliance@1/150', 'compliance@1', 150, null, 'line_breaking', 'line_breaking.1', '1.10', true, '{"de":"Notfallmassnahmen müssen festgelegt werden; spezifische Sicherheitsanweisungen müssen…","en":"Emergency response requirements shall be identified; Specific safety instructions shall…"}'::jsonb, '{"de":"Notfallmassnahmen müssen festgelegt werden; spezifische Sicherheitsanweisungen müssen besprochen werden; die nächstgelegene Sicherheitsdusche/Augenspülstation muss identifiziert und auf Funktionsfähigkeit geprüft werden.","en":"Emergency response requirements shall be identified; Specific safety instructions shall be discussed; nearest safety shower/eyewash shall be identified and checked for operation."}'::jsonb, '{"de":"Sind Notfallmassnahmen festgelegt, einschliesslich spezifischer Sicherheitsanweisungen und der Verfügbarkeit von Sicherheitsduschen/Augenspülstationen?","en":"Are emergency response requirements identified, including specific safety instructions and the availability of safety showers/eyewash stations?"}'::jsonb, false)
