values ('compliance@1/151', 'compliance@1', 151, null, 'line_breaking', 'line_breaking.1', '1.11', true, '{"de":"Der korrekte Einsatz von PSA muss festgelegt und umgesetzt werden.","en":"Correct use of PPE shall be identified and implemented."}'::jsonb, '{"de":"Der korrekte Einsatz von PSA muss festgelegt und umgesetzt werden. Berücksichtigung der Toxizität/Gefährdungen des Materials in der Leitung; ausreichende Abläufe und Entlüftungen; mögliches Zurückbleiben von Material an Tiefpunkten der Leitung, in Ventilen, Kondensatableitern, Filtern oder Pumpen; Tragstruktur der Rohrleitungen oder Anlagen.","en":"Correct use of PPE shall be identified and implemented. Consideration of toxicity/hazards of material in line; adequate drains and vents; potential for material to be trapped in low points in line, valves, traps, strainers or pumps; support structure of piping or equipment."}'::jsonb, '{"de":"Ist die korrekte PSA festgelegt und umgesetzt, unter Berücksichtigung der Toxizität und Gefährdungsrisiken des Leitungsinhalts?","en":"Is the correct PPE identified and implemented, considering toxicity and hazard risks associated with line contents?"}'::jsonb, false)
