values ('compliance@1/158', 'compliance@1', 158, null, 'hot_work', 'hot_work.1', '1.4', true, '{"de":"Für Brennen, Schweissen, Schneiden, Sandstrahlen, tragbare… muss eine Heissarbeitsfreigabe ausgestellt werden","en":"Hot Work permit shall be issued for burning, welding, cutting, sand blasting, portable…"}'::jsonb, '{"de":"Für Brennen, Schweissen, Schneiden, Sandstrahlen, tragbare Heizgeräte, Schleifen oder die Verwendung von funkenschlagenden Geräten muss eine Heissarbeitsfreigabe ausgestellt werden.","en":"Hot Work permit shall be issued for burning, welding, cutting, sand blasting, portable heaters, grinding, or with the use of spark throwing equipment."}'::jsonb, '{"de":"Wird für Tätigkeiten wie Brennen, Schweissen, Schneiden, Schleifen oder die Verwendung von funkenschlagenden Geräten eine Heissarbeitsfreigabe ausgestellt?","en":"Is a hot work permit issued for activities such as burning, welding, cutting, grinding, or using spark-throwing equipment?"}'::jsonb, false)
