values ('compliance@1/159', 'compliance@1', 159, null, 'hot_work', 'hot_work.1', '1.5', true, '{"de":"Für funkenerzeugende Geräte, die in Bereichen verwendet werden, die eigensichere Geräte erfordern, muss eine Heissarbeitsfreigabe ausgestellt werden","en":"Hot Work permit shall be issued for spark producing equipment used in areas that require…"}'::jsonb, '{"de":"Für funkenerzeugende Geräte, die in Bereichen verwendet werden, die eigensichere Geräte erfordern, muss eine Heissarbeitsfreigabe ausgestellt werden.","en":"Hot Work permit shall be issued for spark producing equipment used in areas that require intrinsically safe equipment."}'::jsonb, '{"de":"Wird für funkenerzeugende Geräte, die in Bereichen mit erforderlichen eigensicheren Geräten verwendet werden, eine Heissarbeitsfreigabe ausgestellt?","en":"Is a hot work permit issued for spark-producing equipment used in areas requiring intrinsically safe equipment?"}'::jsonb, false)
