insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/160', 'compliance@1', 160, null, 'hot_work', 'hot_work.1', '1.6', true, '{"de":"Der zuständige Manager/Vorgesetzte vor Ort muss sicherstellen, dass im Bereich, in dem Heissarbeiten durchgeführt werden, Folgendes berücksichtigt wurde…","en":"Manager/supervisor field shall verify that area where Hot Work will occur has addressed…"}'::jsonb, '{"de":"Der zuständige Manager/Vorgesetzte vor Ort muss sicherstellen, dass im Bereich, in dem Heissarbeiten durchgeführt werden, Folgendes berücksichtigt wurde:\n- Arbeitsbereich und angrenzende Bereiche frei von Schutt, brennbaren und entzündbaren Stoffen\n- Tiefer liegende Bereiche und angrenzende Bereiche geschützt, Abschirmungen vorhanden, um Personal vor Schweissblendung zu schützen, Absperrungen vorhanden\n- Brandwache eingeteilt\n- Risikobeurteilung durchgeführt, um sicherzustellen, dass der Bereich für Heissarbeiten sicher ist; alle betroffenen Personen wurden über die bevorstehende Heissarbeitstätigkeit informiert","en":"Manager/supervisor field shall verify that area where Hot Work will occur has addressed:\n- Work area and adjacent areas clear of debris, combustibles, flammables\n- Lower floors and adjcent areas protected, shields in place to protect personnel from welding flash, barricades in place\n- Fire Watch designated\n- Risk assessment performed to ensure area safe for Hot Work, all affected personnel have been warned of impending Hot Work activity"}'::jsonb, '{"de":"Stellen Manager/Vorgesetzte sicher, dass der Bereich für Heissarbeiten frei von Schutt, brennbaren und entzündbaren Stoffen ist und dass geeignete Abschirmungen sowie eine Brandwache eingesetzt werden?","en":"Do managers/supervisors verify that the hot work area is clear of debris, combustibles, and flammables, with proper shielding and fire watch assigned?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/161', 'compliance@1', 161, null, 'hot_work', 'hot_work.1', '1.7', true, '{"de":"Für Arbeiten in einem engen Raum (Confined Space) oder innerhalb von 35 ft/10,5 m von einer Rohrleitung, einem Ventil, einer Armatur, einem Behälter oder einer Anlage, die entzündbare oder brennbare Stoffe enthalten hat, muss eine Atmosphärenprüfung durchgeführt werden","en":"Atmospheric testing shall be performed for work in confined space or within 35 ft/10.5 m…"}'::jsonb, '{"de":"Für Arbeiten in einem engen Raum (Confined Space) oder innerhalb von 35 ft/10,5 m von einer Rohrleitung, einem Ventil, einer Armatur, einem Behälter oder einer Anlage, die entzündbare oder brennbare Stoffe enthalten hat, muss eine Atmosphärenprüfung durchgeführt werden. Auf der Freigabe ist zu dokumentieren, dass die Prüfung eine Atmosphäre von < 3 % UEG und < 22 % O2 bestätigt.","en":"Atmospheric testing shall be performed for work in confined space or within 35 ft/10.5 m of a pipeline, valve, fitting, vessel or equipment  that has contained a flammable or combustible substance. Documentation on permit that testing confirms an atmosphere of < 3% LEL and < 22% O2."}'::jsonb, '{"de":"Wird für Heissarbeiten in engen Räumen oder in der Nähe entzündbarer Stoffe eine Atmosphärenprüfung durchgeführt, um sicherzustellen, dass die Messwerte < 3 % UEG und < 22 % O2 betragen?","en":"Is atmospheric testing conducted for hot work in confined spaces or near flammable materials, ensuring readings are < 3% LEL and < 22% O2?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
