values ('compliance@1/162', 'compliance@1', 162, null, 'hot_work', 'hot_work.1', '1.8', true, '{"de":"Für Arbeiten an einer Leitung, die normalerweise entzündbares Material führt, muss eine Atmosphärenprüfung (Explosimeter) durchgeführt werden","en":"Atmospheric testing (explosimeter) shall be performed for work on a line that normally…"}'::jsonb, '{"de":"Für Arbeiten an einer Leitung, die normalerweise entzündbares Material führt, muss eine Atmosphärenprüfung (Explosimeter) durchgeführt werden. Auf der Freigabe ist zu dokumentieren, dass die Prüfung einen Messwert von < 3 % UEG und < 22 % O2 bestätigt.","en":"Atmospheric testing (explosimeter) shall be performed for work on a line that normally carries flammable material. Documentation on permit that testing confirms a reading of < 3% LEL and  < 22% O2."}'::jsonb, '{"de":"Wird für Arbeiten an einer Leitung, die entzündbare Stoffe führt, eine Explosimeterprüfung durchgeführt, wobei die Freigabedokumentation sichere Messwerte bestätigt?","en":"Is an explosimeter test conducted for work on a line that carries flammable materials, with permit documentation confirming safe readings?"}'::jsonb, false)
