values ('compliance@1/163', 'compliance@1', 163, null, 'hot_work', 'hot_work.1', '1.9', true, '{"de":"Zwangsbelüftung muss in Betracht gezogen und, wo angebracht, bereitgestellt werden","en":"Forced air ventilation shall be considered and provided where appropriate."}'::jsonb, '{"de":"Zwangsbelüftung muss in Betracht gezogen und, wo angebracht, bereitgestellt werden. Alle engen Räume müssen angemessen belüftet werden.","en":"Forced air ventilation shall be considered and provided where appropriate. All confined spaces must be properly ventilated."}'::jsonb, '{"de":"Wird Zwangsbelüftung in Betracht gezogen und dort, wo für enge Räume erforderlich, bereitgestellt?","en":"Is forced air ventilation considered and provided where required for confined spaces?"}'::jsonb, false)
