values ('compliance@1/165', 'compliance@1', 165, null, 'hot_work', 'hot_work.1', '1.11', true, '{"de":"Permits müssen von Ausstellern/Beschäftigten unterzeichnet und in einem kontrollierten Bereich aufbewahrt werden.","en":"Permits shall be signed by issuers/workers and retained in a controlled area."}'::jsonb, '{"de":"Permits müssen von Ausstellern/Beschäftigten unterzeichnet und in einem kontrollierten Bereich aufbewahrt werden. Das Permit muss vollständig und korrekt ausgefüllt werden; es ist für eine Schicht gültig.","en":"Permits shall be signed by issuers/workers and retained in a controlled area. Permit shall be filled out completely and accurately; valid for one shift."}'::jsonb, '{"de":"Werden Heissarbeiten-Permits von Ausstellern/Beschäftigten unterzeichnet, in einem kontrollierten Bereich aufbewahrt und sind sie für eine Schicht gültig?","en":"Are hot work permits signed by issuers/workers, retained in a controlled area, and valid for one shift?"}'::jsonb, false)
