values ('compliance@1/166', 'compliance@1', 166, null, 'hot_work', 'hot_work.1', '1.12', true, '{"de":"Alle an Heissarbeiten beteiligten Personen müssen im standortspezifischen Heissarbeiten-Verfahren geschult sein…","en":"All personnel involved in hot work activities shall be trained in the site hot work…"}'::jsonb, '{"de":"Alle an Heissarbeiten beteiligten Personen müssen im standortspezifischen Heissarbeiten-Verfahren geschult sein. Die Schulung muss dokumentiert werden.","en":"All personnel involved in hot work activities shall be trained in the site hot work procedure. Training shall be documented."}'::jsonb, '{"de":"Sind alle an Heissarbeiten beteiligten Personen in den standortspezifischen Verfahren geschult und ist die Schulung dokumentiert?","en":"Are all personnel involved in hot work activities trained in site procedures, with training documented?"}'::jsonb, false)
