values ('compliance@1/168', 'compliance@1', 168, null, 'hot_work', 'hot_work.1', '1.14', true, '{"de":"Der EHS-Manager muss das Programm jährlich überwachen; dokumentierte Feldaudits durchführen, abgeschlossene Permits überprüfen…","en":"EHS manager shall monitor program annually; perform documented field audits, review…"}'::jsonb, '{"de":"Der EHS-Manager muss das Programm jährlich überwachen; dokumentierte Feldaudits durchführen, abgeschlossene Permits überprüfen und das Programm bei Bedarf überarbeiten.","en":"EHS manager shall monitor program annually; perform documented field audits, review completed permits, and revise program as warranted."}'::jsonb, '{"de":"Überwacht der EHS-Manager das Programm jährlich, führt er Audits durch, überprüft er Permits und überarbeitet er das Programm bei Bedarf?","en":"Does the EHS manager annually monitor the program, conduct audits, review permits, and revise the program as necessary?"}'::jsonb, false)
