insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/169', 'compliance@1', 169, null, 'confined_space', 'confined_space.1', '1.1', true, '{"de":"„Es muss eine betriebliche Richtlinie vorhanden sein, die die Festlegung von…“","en":"A facility guideline shall be in place that includes the identification of…"}'::jsonb, '{"de":"Es muss eine betriebliche Richtlinie vorhanden sein, die die Festlegung von Verantwortlichkeiten für alle Aspekte des Programms umfasst, von der Vorbereitung der Ausrüstung für das Betreten enger Räume (Confined Space Entry, CSE) über die Genehmigung der CSE, die Beschäftigten im CSE, die CSE-Trainer bis hin zur CSE-Rettung usw.","en":"A facility guideline shall be in place that includes the identification of responsibilities for all aspects of program from preparing equipment for confined space entry (CSE), authorizing CSE, workers in CSE, CSE trainers, CSE rescue, etc."}'::jsonb, '{"de":"Ermittelt der Betrieb alle Permit-required Confined Spaces (genehmigungspflichtigen engen Räume)?","en":"Does the facility identify all permit-required confined spaces?"}'::jsonb, false)
