insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/170', 'compliance@1', 170, null, 'confined_space', 'confined_space.1', '1.2', true, '{"de":"„Es muss eine betriebliche Richtlinie vorhanden sein, die die Festlegung aller genehmigungspflichtigen…“","en":"A facility guideline shall be in place that includes the identification of all permit…"}'::jsonb, '{"de":"Es muss eine betriebliche Richtlinie vorhanden sein, die die Festlegung aller genehmigungspflichtigen engen Räume umfasst.","en":"A facility guideline shall be in place that includes the identification of all permit required confined spaces."}'::jsonb, '{"de":"Verfügt der Betrieb über ein Verfahren zur Bestimmung von nicht genehmigungspflichtigen engen Räumen, einschliesslich gleichwertiger Anforderungen an Prüfung und Isolierung?","en":"Does the facility have a process for determining non-permit-required confined spaces, including equivalent testing and isolation requirements?"}'::jsonb, false)
