insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/171', 'compliance@1', 171, null, 'confined_space', 'confined_space.1', '1.3', true, '{"de":"„Es muss eine betriebliche Richtlinie vorhanden sein, die das Verfahren zur Bestimmung…“","en":"A facility guideline shall be in place that includes the process for determining…"}'::jsonb, '{"de":"Es muss eine betriebliche Richtlinie vorhanden sein, die das Verfahren zur Bestimmung von nicht genehmigungspflichtigen engen Räumen umfasst. Bei nicht genehmigungspflichtigen engen Räumen gelten weiterhin dieselben Anforderungen an die Prüfung der Atmosphäre und die Isolierung wie bei einem genehmigungspflichtigen Confined Space.","en":"A facility guideline shall be in place that includes the process for determining non-permit required confined spaces. Non-permit required confined space will still include requirements of testing the atmosphere and isolation equal to that of a permit required CS."}'::jsonb, '{"de":"Verfügt der Betrieb über ein definiertes Rettungsteam, definierte Rettungsmethoden sowie Melde-/Berichtsverfahren?","en":"Does the facility have a defined rescue team, rescue methods, and notification/reporting procedures?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/172', 'compliance@1', 172, null, 'confined_space', 'confined_space.1', '1.4', true, '{"de":"„Es muss eine betriebliche Richtlinie vorhanden sein, die die Festlegung eines Rettungsteams,…“","en":"A facility guideline shall be in place that includes the identification of a rescue team,…"}'::jsonb, '{"de":"Es muss eine betriebliche Richtlinie vorhanden sein, die die Festlegung eines Rettungsteams, von Rettungsmethoden und Melde-/Berichtsverfahren umfasst. Bei Anwendung einer Rettung ohne Betreten des Raumes müssen alle Personen ein Auffanggeschirr mit an einer Hebevorrichtung befestigter Sicherungsleine tragen. Bei einer Rettung mit Betreten des Raumes müssen die den Confined Space betretenden Personen ein Auffanggeschirr tragen und über eine Sicherungsleine mit verfügbarer Hebevorrichtung für die Rettung verfügen. Weitere Rettungsausrüstung, wie geeignete Atemluftgeräte, muss ebenfalls verfügbar sein.","en":"A facility guideline shall be in place that includes the identification of a rescue team, rescue methods, and notification/reporting methods. If non-entry rescue is used, all personnel must wear harness and lifeline attached to hoisting device. For entry rescue, individuals entering CS must wear a harness and have a lifeline with hoist available for rescue. Other rescue equipment such as appropriate breathing air apparatus must also be available."}'::jsonb, '{"de":"Wird das an Rettungen ohne und mit Betreten des Raumes beteiligte Personal mit geeigneter Ausrüstung, einschliesslich Auffanggeschirr, Sicherungsleinen und Atemschutzgeräten, ausgestattet?","en":"Are personnel involved in non-entry and entry rescues provided with appropriate equipment, including harnesses, lifelines, and breathing apparatus?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/173', 'compliance@1', 173, null, 'confined_space', 'confined_space.1', '1.5', true, '{"de":"„Es muss eine betriebliche Richtlinie vorhanden sein, die ein Schulungsprogramm zum betrieblichen…“","en":"A facility guideline shall be in place that includes a training program on the site…"}'::jsonb, '{"de":"Es muss eine betriebliche Richtlinie vorhanden sein, die ein Schulungsprogramm zum betrieblichen Verfahren sowie einen Übungsplan für Rettungstechniken umfasst. Alle Schulungen sollten mindestens jährlich stattfinden.","en":"A facility guideline shall be in place that includes a training program on the site procedure and a practice schedule for rescue techniques. All training should be on at least an annual schedule."}'::jsonb, '{"de":"Bietet der Betrieb ein Schulungsprogramm für CSE an und führt er jährliche Rettungsübungen durch?","en":"Does the facility provide a training program for CSE and conduct annual rescue practice sessions?"}'::jsonb, false)
