insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/174', 'compliance@1', 174, null, 'confined_space', 'confined_space.1', '1.6', true, '{"de":"„Es muss eine betriebliche Richtlinie vorhanden sein, wonach Personen, die den Confined Space betreten, …“","en":"A facility guideline shall be in place that includes the personnel entering the CS must…"}'::jsonb, '{"de":"Es muss eine betriebliche Richtlinie vorhanden sein, wonach Personen, die den Confined Space betreten, über eine angemessene Schulung verfügen und die Grössenanforderungen erfüllen müssen.","en":"A facility guideline shall be in place that includes the personnel entering the CS must have adequate training and meet size requirement."}'::jsonb, '{"de":"Erhalten alle Personen, die enge Räume betreten, eine angemessene Schulung und erfüllen sie die Grössenanforderungen?","en":"Do all personnel entering confined spaces receive adequate training and meet size requirements?"}'::jsonb, false)
