values ('compliance@1/181', 'compliance@1', 181, null, 'confined_space', 'confined_space.1', '1.13', true, '{"de":"Titel von Punkt 1.13\n\"Eine Betriebsrichtlinie muss ein Freigabeverfahren vorsehen, das Ergebnisse der Atmosphärenprüfung vor der Einfahrt beinhaltet…\"","en":"A facility guideline shall use a permit process that includes atmospheric testing results…"}'::jsonb, '{"de":"Eine Betriebsrichtlinie muss ein Freigabeverfahren vorsehen, das Ergebnisse der Atmosphärenprüfung vor der Einfahrt beinhaltet. O2: 19,5%-22%; UEG<3%; Schadstoffe < IDLH, gegen die Personal durch Atemschutz geschützt werden kann. Ergebnisse werden Einfahrenden und Sicherungsposten mitgeteilt.","en":"A facility guideline shall use a permit process that includes atmospheric testing results prior to entry. O2: 19.5%-22%;  LEL<3%;  Contaminants < IDLH which personnel can be protected by respirator. Results communicated with entrants and attendant."}'::jsonb, '{"de":"Verlangt das Freigabeverfahren eine Atmosphärenprüfung vor der Einfahrt, um sicherzustellen, dass O2-, UEG- und Schadstoffwerte innerhalb sicherer Grenzwerte liegen?","en":"Does the permit process require atmospheric testing prior to entry, ensuring O2, LEL, and contaminant levels are within safe limits?"}'::jsonb, false)
