values ('compliance@1/184', 'compliance@1', 184, null, 'confined_space', 'confined_space.1', '1.16', true, '{"de":"Titel von Punkt 1.16\n\"Eine Betriebsrichtlinie muss ein Freigabeverfahren vorsehen, das die Kennzeichnung aller…\"","en":"A facility guideline shall use a permit process that includes the identification of all…"}'::jsonb, '{"de":"Eine Betriebsrichtlinie muss ein Freigabeverfahren vorsehen, das die Kennzeichnung aller Stellen beinhaltet, an denen der Confined Space isoliert wurde, sowie aller zugehörigen Anlagen, die LOTO erfordern, wie Rührwerke, Mischer, Wärmetauscher usw.","en":"A facility guideline shall use a permit process that includes the identification of all points where the CS was isolated and any related equipment that require LOTO such as agitators, mixers, heat transfer equipment, etc."}'::jsonb, '{"de":"Kennzeichnet das Freigabeverfahren alle Isolierstellen und verlangt LOTO für die betreffenden Anlagen?","en":"Does the permit process identify all isolation points and require LOTO for applicable equipment?"}'::jsonb, false)
