values ('compliance@1/189', 'compliance@1', 189, null, 'confined_space', 'confined_space.1', '1.21', true, '{"de":"Ein enger Raum wird entleert und…","en":"A facility guideline shall use a permit process that includes a CS is emptied and…"}'::jsonb, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren (Permit-Verfahren) verwenden, das beinhaltet, dass der enge Raum (Confined Space) entleert und dekontaminiert wird. Die PSA wird auf der Arbeitsfreigabe (Permit) festgelegt.","en":"A facility guideline shall use a permit process that includes a CS is emptied and decontaminated. PPE identified on permit."}'::jsonb, '{"de":"Stellt das Freigabeverfahren sicher, dass enge Räume (Confined Spaces) vor dem Betreten entleert und dekontaminiert werden und die PSA festgelegt ist?","en":"Does the permit process ensure confined spaces are emptied and decontaminated before entry, with PPE identified?"}'::jsonb, false)
