values ('compliance@1/190', 'compliance@1', 190, null, 'confined_space', 'confined_space.1', '1.22', true, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren verwenden, das eine angemessene Belüftung beinhaltet.","en":"A facility guideline shall use a permit process that includes av entilation appropriate."}'::jsonb, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren (Permit-Verfahren) verwenden, das eine angemessene Belüftung beinhaltet. Bei unzureichendem natürlichem Luftzug wird eine Zwangsbelüftung bereitgestellt. Brenn- oder Schweissarbeiten im engen Raum (Confined Space) können Atemluft oder zusätzliche Belüftung erfordern.","en":"A facility guideline shall use a permit process that includes av entilation appropriate. Forced air ventilation provided when there is not an adequate natural draft. Burning or welding inside the CS may require breathing air or additional ventilation."}'::jsonb, '{"de":"Wird die Belüftung beurteilt und bei Bedarf bereitgestellt, einschliesslich Zwangsbelüftung für enge Räume (Confined Spaces) mit unzureichendem natürlichem Luftstrom?","en":"Is ventilation assessed and provided as necessary, including forced air ventilation for confined spaces with inadequate natural airflow?"}'::jsonb, false)
