values ('compliance@1/191', 'compliance@1', 191, null, 'confined_space', 'confined_space.1', '1.23', true, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren verwenden, das elektrische Werkzeuge, Beleuchtung…","en":"A facility guideline shall use a permit process that includes electrical tools, lights…"}'::jsonb, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren (Permit-Verfahren) verwenden, das beinhaltet, dass elektrische Werkzeuge, Beleuchtung und Geräte, die im engen Raum (Confined Space) verwendet werden, Niederspannung (12–24 V) aufweisen oder bei 120–240 V mit einem Fehlerstrom-Schutzschalter (GFCI) geschützt sind.","en":"A facility guideline shall use a permit process that includes electrical tools, lights and equipment used in the CS are low voltage (12-24 V) or 120-240 V if protected with a ground fault cirquit interruptor (GFCI)."}'::jsonb, '{"de":"Sind elektrische Werkzeuge, Beleuchtung und Geräte, die in engen Räumen (Confined Spaces) verwendet werden, mit Niederspannung ausgestattet oder mit einem GFCI geschützt?","en":"Are electrical tools, lights, and equipment used in confined spaces low voltage or GFCI-protected?"}'::jsonb, false)
