values ('compliance@1/193', 'compliance@1', 193, null, 'confined_space', 'confined_space.1', '1.25', true, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren verwenden, das nach Abschluss der CSE vorsieht, dass alle…","en":"A facility guideline shall use a permit process that includes upon completion of CSE, all…"}'::jsonb, '{"de":"Eine betriebliche Richtlinie muss ein Freigabeverfahren (Permit-Verfahren) verwenden, das beinhaltet, dass nach Abschluss der Confined Space Entry (CSE) alle Geräte und Rückstände entfernt werden, die Schlösser von den Isolationspunkten entfernt werden und der Vorgesetzte bestätigt, dass sich das gesamte Personal ausserhalb des Behälters befindet.","en":"A facility guideline shall use a permit process that includes upon completion of CSE, all equipment and debris removed; locks removed from isolation points; supervisor confirm that all personnel out of vessel."}'::jsonb, '{"de":"Stellt das Freigabeverfahren sicher, dass nach Abschluss der Confined Space Entry (CSE) alle Geräte und Rückstände entfernt werden, die Schlösser entfernt werden und die Vorgesetzten bestätigen, dass sich das gesamte Personal ausserhalb befindet?","en":"Does the permit process ensure that upon completion of CSE, all equipment and debris are removed, locks are removed, and supervisors confirm all personnel are out?"}'::jsonb, false)
