values ('compliance@1/196', 'compliance@1', 196, null, 'confined_space', 'confined_space.1', '1.28', true, '{"de":"Der EHS-Manager überwacht das Programm jährlich; führt dokumentierte Feldaudits durch, überprüft…","en":"EHS manager shall monitor program annually; perform documented field audits, review…"}'::jsonb, '{"de":"Der EHS-Manager muss das Programm jährlich überwachen, dokumentierte Feldaudits durchführen, abgeschlossene Freigaben (Permits) überprüfen und das Programm bei Bedarf überarbeiten.","en":"EHS manager shall monitor program annually; perform documented field audits, review completed permits, and revise program as warranted."}'::jsonb, '{"de":"Überwacht der EHS-Manager das Confined-Space-Entry-Programm jährlich, führt Audits durch, überprüft Freigaben (Permits) und überarbeitet das Programm bei Bedarf?","en":"Does the EHS manager monitor the confined space entry program annually, conduct audits, review permits, and revise the program as necessary?"}'::jsonb, false)
