values ('compliance@1/199', 'compliance@1', 199, null, 'high_work', 'high_work.1', '1.3', true, '{"de":"Absturzgefährdungen am Arbeitsplatz wurden ermittelt.","en":"Fall hazards in the workplace have been identified."}'::jsonb, '{"de":"Absturzgefährdungen am Arbeitsplatz wurden ermittelt. Eine Absturzgefährdung besteht, wenn sich eine Person in einer Höhe von mehr als 4 ft/1,2 m befindet und nicht durch ein Standard-Geländersystem geschützt ist.","en":"Fall hazards in the workplace have been identified. A fall hazard exists when individual is at a height greater than 4 ft/1.2 m and not protected by standard guardrail system."}'::jsonb, '{"de":"Wurden Absturzgefährdungen am Arbeitsplatz ermittelt, insbesondere für Personen in Höhen von mehr als 4 ft/1,2 m ohne Standard-Geländerschutz?","en":"Have fall hazards in the workplace been identified, specifically for individuals at heights greater than 4 ft/1.2 m without standard guardrail protection?"}'::jsonb, false)
