values ('compliance@1/200', 'compliance@1', 200, null, 'high_work', 'high_work.1', '1.4', true, '{"de":"Erhöhte Laufwege/Plattformen von mehr als 4 ft/1,2 m sind mit einem Geländersystem ausgestattet.","en":"Elevated walkways/platforms greater than 4 ft/1.2 m are equipped with guardrail system."}'::jsonb, '{"de":"Erhöhte Laufwege/Plattformen von mehr als 4 ft/1,2 m sind mit einem Geländersystem ausgestattet. Das Geländer besteht aus einem Obergurt in 42\" (+/- 3\") bzw. 1 m (+/- 8 cm) Höhe, einem Zwischengurt und einer Fussleiste. Die Geländer müssen einer seitlichen Kraft von 200 lbs/90 kg widerstehen können. Vertikale Stützen dürfen nicht mehr als 8 ft/2,4 m Abstand haben.","en":"Elevated walkways/platforms greater than 4 ft/1.2 m are equipped with guardrail system. Guardrail comprised of top rail at 42\"(+/- 3\") or 1 m (+/- 8cm); mid-rail, and toe board. Rails capable of withstanding 200 lbs/90 kgs lateral force. Vertical supports not more than 8 ft/2.4 m apart."}'::jsonb, '{"de":"Sind erhöhte Laufwege und Plattformen von mehr als 4 ft/1,2 m mit einem Geländersystem ausgestattet, das den Sicherheitsanforderungen entspricht?","en":"Are elevated walkways and platforms greater than 4 ft/1.2 m equipped with a guardrail system meeting safety specifications?"}'::jsonb, false)
