insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/202', 'compliance@1', 202, null, 'high_work', 'high_work.1', '1.6', true, '{"de":"Arbeitsfreigabe (Permit) für Höhenarbeit und Absturzschutz wird für Tätigkeiten verwendet, die Folgendes erfordern: - Verwendung von…","en":"High Work and Fall Protection permit to work used for tasks requiring: - Use of…"}'::jsonb, '{"de":"Arbeitsfreigabe (Permit) für Höhenarbeit und Absturzschutz wird für Tätigkeiten verwendet, die Folgendes erfordern:\n- Verwendung von Gerüsten, tragbaren Leitern, erhöhten Plattformen, mobilen Geräten zum Heben von Personal, wenn der Boden der Plattform höher als 6 ft/2 m liegt\n- Arbeiten, die den Einsatz einer Hubarbeitsbühne wie JLG, Schwenkgerüst, Gabelstapler, Hubarbeitsbühnen-Fahrzeug (Bucket Truck) oder Scherenhebebühne erfordern\n- Erhöhte Arbeitsbereiche von mehr als 4 ft/1,2 m, bei denen Gitterroste oder Geländer entfernt wurden, oder innerhalb von 6 ft/2 m von Öffnungen im Boden wie Schächten, Einstiegsöffnungen oder Oberlichtern\n- Arbeiten innerhalb von 6 ft/2 m von der Vorderkante flach geneigter oder flacher Dächer sowie auf allen geneigten Dächern\n- Arbeitstätigkeiten in der Nähe von Oberlichtern, Einstiegsöffnungen, Schächten, Mannlöchern oder anderen temporären Öffnungen","en":"High Work and Fall Protection permit to work used for tasks requiring:\n- Use of scaffolds, portable ladders, elevated platforms,mobile equipment designed to lift personnel when the floor of the platform is greater than 6 ft/2 m\n- Work requiring use of an aerial work platform such as JLG, swinging scaffold, fork lift truck, bucket truck, scissor manlift\n- Elevated work areas greater than 4 ft/1.2 m where grating or guardrails are removed, or within 6 ft/2 m of opeings in floors such as chutes, manholes, or skylights\n- Work within 6 ft/2 m of the leading edge of low-sloping roofs or flat roofs, and on all sloping roofs\n- Work activities in the vicinity of skylights, hatchways, chutes, manholes or other temporary openings"}'::jsonb, '{"de":"Ist eine Arbeitsfreigabe (Permit) für Höhenarbeit und Absturzschutz erforderlich für Tätigkeiten wie:\n- Verwendung von Gerüsten, Leitern und erhöhten Plattformen\n- Verwendung von Hubarbeitsbühnen (JLG, Gabelstapler-Bucket-Truck, Scherenhebebühne)\n- Arbeiten in erhöhten Bereichen von mehr als 4 ft/1,2 m, bei denen Geländer entfernt wurden\n- Arbeiten innerhalb von 6 ft/2 m von offenen Böden, Schächten, Mannlöchern, Oberlichtern\n- Arbeiten innerhalb von 6 ft/2 m von Vorderkanten von Dächern oder auf geneigten Dächern?","en":"Is a High Work and Fall Protection permit required for tasks such as:\n- Use of scaffolds, ladders, and elevated platforms\n- Use of aerial work platforms (JLG, forklift bucket truck, scissor lift)\n- Working on elevated areas greater than 4 ft/1.2 m where guardrails are removed\n- Working within 6 ft/2 m of open floors, chutes, manholes, skylights\n- Working within 6 ft/2 m of leading edges of roofs or on sloped roofs?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/203', 'compliance@1', 203, null, 'high_work', 'high_work.1', '1.7', true, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländer…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, gilt Folgendes: Ein Warnleinensystem muss nicht näher als 6 ft/2 m von der Dachkante entfernt rund um alle Seiten des Arbeitsbereichs angebracht werden. Die Warnleine muss eine Bruchfestigkeit von 500 lbs/226 kg aufweisen und mit Fahnen markiert sein.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: A warning line system must be placed no closer than 6 ft/2 m from roof edge around all sides of the roof area where work is being performed. The warning line must have 500 lbs/226 kg of breaking strength and be marked with flags."}'::jsonb, '{"de":"Ist bei Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt ohne Geländersysteme ein Warnleinensystem nicht näher als 6 ft/2 m von der Dachkante angebracht, mit einer Bruchfestigkeit von mindestens 500 lbs/226 kg?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, is a warning line system placed no closer than 6 ft/2 m from the roof edge, with at least 500 lbs/226 kg of breaking strength?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/204', 'compliance@1', 204, null, 'high_work', 'high_work.1', '1.8', true, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländer…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, gilt Folgendes: Eine Kontrollierte Zugangszone (Controlled Access Zone, CAZ) muss nicht weniger als 6 ft/2 m von der Kante des Arbeitsbereichs eingerichtet werden. Dieser Bereich muss mit einem Seil oder einer Barriere mit mindestens 200 lbs/90 kg Bruchfestigkeit markiert werden.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: A Controlled Access Zone (CAZ) must be established no less than 6 ft/2 m from the edge of the work area. This area must be marked with a rope or barrier that has at least 200 lbs/90 kg of breaking strength."}'::jsonb, '{"de":"Ist bei Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt ohne Geländersysteme eine Kontrollierte Zugangszone (CAZ) nicht weniger als 6 ft/2 m vom Arbeitsbereich entfernt eingerichtet, markiert mit einem Seil oder einer Barriere von mindestens 200 lbs/90 kg Bruchfestigkeit?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, is a Controlled Access Zone (CAZ) established no less than 6 ft/2 m from the work area, marked with a rope or barrier of at least 200 lbs/90 kg of breaking strength?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/205', 'compliance@1', 205, null, 'high_work', 'high_work.1', '1.9', true, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländer…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, gilt Folgendes: Eine fachkundige Person muss benannt werden, um die Sicherheit der Beschäftigten, die innerhalb der CAZ arbeiten, zu überwachen.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: A competent person must be designated to monitor the safety of employees working within the CAZ."}'::jsonb, '{"de":"Ist bei Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt ohne Geländersysteme eine fachkundige Person benannt, um die Sicherheit der Beschäftigten innerhalb der CAZ zu überwachen?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, is a competent person designated to monitor employee safety within the CAZ?"}'::jsonb, false)
