insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/206', 'compliance@1', 206, null, 'high_work', 'high_work.1', '1.10', true, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländer…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Für Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, gilt Folgendes: Das Permit muss an der Arbeitsstelle ausgehängt werden und ist nur für eine Arbeitsschicht gültig.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: Permit posted at job sites; good for one work shift only."}'::jsonb, '{"de":"Ist bei Dacharbeiten mindestens 6 ft/2 m von der Kante entfernt ohne Geländersysteme ein Permit an der Arbeitsstelle ausgehängt und nur für eine Arbeitsschicht gültig?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, is a permit posted at job sites and valid for one work shift only?"}'::jsonb, false)
