insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/207', 'compliance@1', 207, null, 'high_work', 'high_work.1', '1.11', true, '{"de":"„Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, ist Folgendes erforderlich: Arbeitsfreigaben (Permits) werden von den Ausstellern/Beschäftigten unterzeichnet und an einem kontrollierten Ort aufbewahrt. Die Arbeitsfreigabe ist vollständig und korrekt ausgefüllt; sie ist für eine Schicht gültig.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: Permits are signed by issuers/workers and retained in a controlled area. Permit filled out completely and accurately; valid for one shift."}'::jsonb, '{"de":"Werden bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante ohne Geländersysteme die Arbeitsfreigaben (Permits) von den Ausstellern und Beschäftigten unterzeichnet, an einem kontrollierten Ort aufbewahrt und vollständig und korrekt ausgefüllt?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, are permits signed by issuers and workers, retained in a controlled area, and filled out completely and accurately?"}'::jsonb, false)
