insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/208', 'compliance@1', 208, null, 'high_work', 'high_work.1', '1.12', true, '{"de":"„Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, ist Folgendes erforderlich: Warnschilder sind am Rand des Arbeitsbereichs angebracht. Der Bereich ist abgesperrt, um den Zutritt zu verhindern.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: Warning signs posted on the perimeter of the work area. Area roped off to prevent access."}'::jsonb, '{"de":"Sind bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante ohne Geländersysteme Warnschilder am Rand des Arbeitsbereichs angebracht und ist der Bereich abgesperrt, um unbefugten Zutritt zu verhindern?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, are warning signs posted on the perimeter of the work area, and is the area roped off to prevent unauthorized access?"}'::jsonb, false)
