insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/209', 'compliance@1', 209, null, 'high_work', 'high_work.1', '1.13', true, '{"de":"„Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, ist Folgendes erforderlich: Für Höhenarbeiten, die eine Arbeitsfreigabe erfordern, werden Ganzkörper-Auffanggurte mit stossdämpfendem oder einziehbarem Verbindungsmittel verwendet. Anschlagpunkte müssen ein Totgewicht von 5''000 lbs/2''449 kg pro angehängtem Beschäftigten tragen können.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: Full body harnesses with a shock absorbing or retractable lifeline are used for  high work requiring a permit. Anchorage points must be capable of supporting a dead weight of 5,000 lbs/2449 kg for every employee attached."}'::jsonb, '{"de":"Werden bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante ohne Geländersysteme Ganzkörper-Auffanggurte mit stossdämpfendem oder einziehbarem Verbindungsmittel verwendet? Können die Anschlagpunkte mindestens 5''000 lbs/2''449 kg pro Beschäftigtem tragen?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, are full-body harnesses with a shock-absorbing or retractable lifeline used? Are anchorage points capable of supporting a minimum of 5,000 lbs/2449 kg per employee?"}'::jsonb, false)
