insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/210', 'compliance@1', 210, null, 'high_work', 'high_work.1', '1.14', true, '{"de":"„Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, ist Folgendes erforderlich: Alle Ganzkörper-Auffanggurte, stossdämpfenden Verbindungsmittel und Absturzsicherungsausrüstungen werden vor Gebrauch einer Sichtprüfung unterzogen. Die gesamte Absturzsicherungsausrüstung befindet sich in einwandfreiem Zustand. Jede Komponente des Systems, die einer Stossbelastung ausgesetzt war, muss ausser Betrieb genommen werden, bis sie als unbeschädigt geprüft wurde, oder zur Rezertifizierung an den Hersteller zurückgesendet werden.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: All full body harnesses, shock absorbing lifelines and fall protection equipment are visibly inspected before use. All fall protection equipment is in good condition. Any component of the system that has been subjected to impact loading must be removed from service until inspected to be undamaged or sent back to the manufacturer for recertification."}'::jsonb, '{"de":"Werden bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante ohne Geländersysteme alle Ganzkörper-Auffanggurte, stossdämpfenden Verbindungsmittel und Absturzsicherungsausrüstungen vor Gebrauch einer Sichtprüfung unterzogen? Werden Komponenten, die einer Stossbelastung ausgesetzt waren, bis zur Prüfung oder Rezertifizierung ausser Betrieb genommen?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, are all full-body harnesses, shock-absorbing lifelines, and fall protection equipment visibly inspected before use? Are components subject to impact loading removed from service until inspected or sent for recertification?"}'::jsonb, false)
