values ('compliance@1/211', 'compliance@1', 211, null, 'high_work', 'high_work.1', '1.15', true, '{"de":"„Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme…","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail…"}'::jsonb, '{"de":"Bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante, wenn persönliche Absturzsicherungssysteme oder Geländersysteme nicht verwendet werden, ist Folgendes erforderlich: Ein Rettungsplan muss vor der Durchführung jeder Tätigkeit im Zusammenhang mit der Verwendung eines persönlichen Absturzsicherungssystems besprochen und kommuniziert werden.","en":"For roof work at least 6 ft/2 m from edge when personal fall arrest systems or guardrail systems are not used the following is required: A rescue plan must be discussed and communicated pritor to performing any task associated with the use of a personal fall arrest system."}'::jsonb, '{"de":"Wird bei Dacharbeiten mit einem Abstand von mindestens 6 ft/2 m von der Kante ohne Geländersysteme ein Rettungsplan besprochen und kommuniziert, bevor eine Tätigkeit ausgeführt wird, die ein persönliches Absturzsicherungssystem erfordert?","en":"For roof work at least 6 ft/2 m from the edge without guardrail systems, is a rescue plan discussed and communicated before performing any task requiring a personal fall arrest system?"}'::jsonb, false)
