insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/220', 'compliance@1', 220, null, 'excavation', 'excavation.1', '1.6', true, '{"de":"Die Arbeitsstelle muss von der kompetenten Person täglich sowie nach jedem Regen oder anderen Ereignis... inspiziert werden","en":"Job site shall be inspected by competent person daily and after any rain or other event…"}'::jsonb, '{"de":"Die Arbeitsstelle muss von der kompetenten Person täglich sowie nach jedem Regen oder anderen Ereignis, das den Aushub beeinträchtigt haben könnte, inspiziert werden. Die Inspektionen sind auf der Freigabe zu dokumentieren.","en":"Job site shall be inspected by competent person daily and after any rain or other event that may have impacted the excavation. Documentation of inspections on permit."}'::jsonb, '{"de":"Wird die Arbeitsstelle von einer kompetenten Person täglich sowie nach jedem Regen oder Ereignis, das den Aushub beeinträchtigen könnte, inspiziert? Wird die Dokumentation der Inspektionen auf der Freigabe geführt?","en":"Is the job site inspected by a competent person daily and after any rain or event that may impact the excavation? Is documentation of inspections maintained on the permit?"}'::jsonb, false)
