insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/223', 'compliance@1', 223, null, 'excavation', 'excavation.1', '1.9', true, '{"de":"Die Lage unterirdischer Leitungen wie Strom, Brennstoff, Wasserleitungen, Abwasser, Telefon usw. muss...","en":"Location of underground utilities such as electric, fuel, water lines, sewer, telephone…"}'::jsonb, '{"de":"Die Lage unterirdischer Leitungen wie Strom, Brennstoff, Wasserleitungen, Abwasser, Telefon oder andere muss ermittelt und vor Ort deutlich markiert worden sein. Alle Installationen sind auf der Freigabe und in den am Standort geführten Plänen ausgewiesen. Es darf kein Aushub oder Schneiden beginnen, bevor alle unterirdischen Leitungen geortet wurden.","en":"Location of underground utilities such as electric, fuel, water lines, sewer, telephone or any others have been identified and clearly marked at the site. All installations identified on permit and on drawings maintained at site. No excavation or cutting may commence until all underground utilities are located."}'::jsonb, '{"de":"Wurden unterirdische Leitungen wie Strom, Brennstoff, Wasserleitungen, Abwasser, Telefon und andere ermittelt und vor Ort deutlich markiert? Sind alle Installationen auf den Freigaben und den Standortplänen ausgewiesen? Ist Aushub oder Schneiden untersagt, bevor alle unterirdischen Leitungen geortet wurden?","en":"Have underground utilities such as electric, fuel, water lines, sewer, telephone, and others been identified and clearly marked at the site? Are all installations identified on permits and on site drawings? Is excavation or cutting prohibited until all underground utilities are located?"}'::jsonb, false)
