values ('compliance@1/225', 'compliance@1', 225, null, 'excavation', 'excavation.1', '1.11', true, '{"de":"Titel von Punkt 1.11\n\"Grabenaushebungen, die tiefer als 4 ft/1,22 m sind, müssen einen sicheren Fluchtweg aufweisen, der…\"","en":"Trench excavations deeper than 4 ft/1.22 m must have a safe means of egress that would…"}'::jsonb, '{"de":"Grabenaushebungen, die tiefer als 4 ft/1,22 m sind, müssen einen sicheren Fluchtweg aufweisen, der für das Personal nicht mehr als 25 ft/7,62 m Seitwärtsbewegung erfordert.","en":"Trench excavations deeper than 4 ft/1.22 m must have a safe means of egress that would require no more than 25 ft/7.62 m of lateral travel for personnel."}'::jsonb, '{"de":"Verfügen Grabenaushebungen, die tiefer als 4 ft/1,22 m sind, über einen sicheren Fluchtweg, der für das Personal nicht mehr als 25 ft/7,62 m Seitwärtsbewegung erfordert?","en":"Do trench excavations deeper than 4 ft/1.22 m have a safe means of egress requiring no more than 25 ft/7.62 m of lateral travel for personnel?"}'::jsonb, false)
