values ('compliance@1/226', 'compliance@1', 226, null, 'excavation', 'excavation.1', '1.12', true, '{"de":"Alle Aushebungen, die tiefer als 4 ft/1,22 m sind, müssen ein Abschrägungs- oder Abstufungssystem, ein…","en":"All excavations deeper than 4 ft/1.22 must have a sloping or benching system, a support…"}'::jsonb, '{"de":"Alle Aushebungen, die tiefer als 4 ft/1,22 m sind, müssen ein Abschrägungs- oder Abstufungssystem, ein Stützschildsystem oder vor Ort konstruierte und errichtete Systeme aufweisen, um das Personal vor möglichen Einstürzen zu schützen.","en":"All excavations deeper than 4 ft/1.22 must have a sloping or benching system, a support shield system, or systems designed and built in place to protect personnel from possible cave-ins."}'::jsonb, '{"de":"Verfügen alle Aushebungen, die tiefer als 4 ft/1,22 m sind, über ein Abschrägungs- oder Abstufungssystem, ein Stützschildsystem oder andere Systeme, die konstruiert und errichtet wurden, um das Personal vor möglichen Einstürzen zu schützen?","en":"Do all excavations deeper than 4 ft/1.22 m have a sloping or benching system, a support shield system, or other systems designed and built to protect personnel from possible cave-ins?"}'::jsonb, false)
