values ('compliance@1/228', 'compliance@1', 228, null, 'excavation', 'excavation.1', '1.14', true, '{"de":"Warnsysteme wie Absperrungen, Hand- oder mechanische Signale oder Anschlagbalken müssen verwendet werden…","en":"Warning systems such as barricades, hand or mechanical signals, or stop logs must be used…"}'::jsonb, '{"de":"Warnsysteme wie Absperrungen, Hand- oder mechanische Signale oder Anschlagbalken müssen verwendet werden, wenn mobile Ausrüstung neben der Aushebung betrieben wird.","en":"Warning systems such as barricades, hand or mechanical signals, or stop logs  must be used when mobile equipment is operated adjacent to the excavation."}'::jsonb, '{"de":"Werden Warnsysteme wie Absperrungen, Hand- oder mechanische Signale oder Anschlagbalken verwendet, wenn mobile Ausrüstung neben der Aushebung betrieben wird?","en":"Are warning systems such as barricades, hand or mechanical signals, or stop logs used when mobile equipment operates adjacent to the excavation?"}'::jsonb, false)
