values ('compliance@1/229', 'compliance@1', 229, null, 'excavation', 'excavation.1', '1.15', true, '{"de":"Es ist dem Personal nicht erlaubt, in Aushebungen mit angesammeltem Wasser zu arbeiten - sei es aus Oberflächen-…","en":"Personnel may not work in excavations with accumulated water - whether from surface…"}'::jsonb, '{"de":"Es ist dem Personal nicht erlaubt, in Aushebungen mit angesammeltem Wasser zu arbeiten - sei es aus Oberflächenwasser, Regenwasser oder Grundwasser. Risikobeurteilungen müssen durchgeführt werden, um Gefährdungen im Zusammenhang mit Wasserentfernungsgeräten zu ermitteln.","en":"Personnel may not work in excavations with accumulated water - whether from surface water, rain water or groundwater.  Risk assessments must be performed to identify hazards associated with water removal equipment."}'::jsonb, '{"de":"Ist es dem Personal verboten, in Aushebungen mit angesammeltem Wasser aus Oberflächenwasser, Regenwasser oder Grundwasser zu arbeiten? Werden Risikobeurteilungen durchgeführt, um Gefährdungen im Zusammenhang mit Wasserentfernungsgeräten zu ermitteln?","en":"Are personnel prohibited from working in excavations with accumulated water from surface water, rainwater, or groundwater? Are risk assessments performed to identify hazards associated with water removal equipment?"}'::jsonb, false)
