insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/230', 'compliance@1', 230, null, 'excavation', 'excavation.1', '1.16', true, '{"de":"Aushebungen unterhalb der Ebene der Basis oder des Fundaments eines Fundaments oder einer Stützmauer…","en":"Excavations below the level of the base or footing of any foundation or retaining wall…"}'::jsonb, '{"de":"Aushebungen unterhalb der Ebene der Basis oder des Fundaments eines Fundaments oder einer Stützmauer sind nicht zulässig, ausser wenn:\n- Ein Stützsystem, wie beispielsweise eine Unterfangung, vorhanden ist, um die Struktur zu stabilisieren;\n- Die Aushebung in stabilem Fels erfolgt;\n- Ein qualifizierter Fachingenieur die Feststellung genehmigt hat, dass die Struktur ausreichend weit von der Aushebung entfernt ist, sodass sie von der Aushebungsaktivität nicht beeinträchtigt wird; oder\n- Ein qualifizierter Fachingenieur die Feststellung genehmigt hat, dass diese Aushebungsarbeiten keine Gefährdung für das Personal darstellen.","en":"Excavations below the level of the base or footing of any foundation or retaining wall may not be permitted except when:\n- A support system, such as underpinning, is in place to stabilize the structure;\n- The excavation is in stable rock;\n- A qualified professional engineer has approved the determination that the structure is sufficiently removed from the excavation so as to be unaffected by the excavation activity; or\n- A qualified professional engineer has approved the determination that such excavation work will not pose a hazard to personnel."}'::jsonb, '{"de":"Sind Aushebungen unterhalb der Ebene der Basis oder des Fundaments eines Fundaments oder einer Stützmauer verboten, sofern nicht:\n- Ein Stützsystem, wie beispielsweise eine Unterfangung, vorhanden ist, um die Struktur zu stabilisieren?\n- Die Aushebung in stabilem Fels erfolgt?\n- Ein qualifizierter Fachingenieur genehmigt hat, dass die Struktur ausreichend weit von der Aushebung entfernt ist?\n- Ein qualifizierter Fachingenieur festgestellt hat, dass die Aushebung keine Gefährdung für das Personal darstellt?","en":"Are excavations below the level of the base or footing of any foundation or retaining wall prohibited unless:\n- A support system, such as underpinning, is in place to stabilize the structure?\n- The excavation is in stable rock?\n- A qualified professional engineer has approved that the structure is sufficiently removed from the excavation?\n- A qualified professional engineer has determined the excavation will not pose a hazard to personnel?"}'::jsonb, false)
