values ('compliance@1/231', 'compliance@1', 231, null, 'excavation', 'excavation.1', '1.17', true, '{"de":"Es ist ein angemessener Schutz vorhanden, um das Personal vor losem Gestein oder Erdreich zu schützen.","en":"Adequate protection is in place to protect personnel from loose rock or soil."}'::jsonb, '{"de":"Es ist ein angemessener Schutz vorhanden, um das Personal vor losem Gestein oder Erdreich zu schützen. Ausgehobenes oder anderes Material muss mindestens 2 ft/0,61 m vom Rand der Aushebung entfernt oder hinter einer Rückhaltevorrichtung platziert werden.","en":"Adequate protection is in place to protect personnel from loose rock or soil. Excavated or other material shall be placed at least 2 ft/ 0.61 m from the edge of the excavation, or beyond a retaining device."}'::jsonb, '{"de":"Ist ein angemessener Schutz vorhanden, um das Personal vor losem Gestein oder Erdreich zu schützen? Wird ausgehobenes oder anderes Material mindestens 2 ft/0,61 m vom Rand der Aushebung entfernt oder hinter einer Rückhaltevorrichtung platziert?","en":"Is adequate protection in place to protect personnel from loose rock or soil? Are excavated or other materials placed at least 2 ft/0.61 m from the edge of the excavation or beyond a retaining device?"}'::jsonb, false)
