values ('compliance@1/232', 'compliance@1', 232, null, 'excavation', 'excavation.1', '1.18', true, '{"de":"Gehwege werden bereitgestellt, wo Personal oder Ausrüstung die Aushebung überqueren müssen oder dürfen…","en":"Walkways are provided where personnel or equipment are required or permitted to cross the…"}'::jsonb, '{"de":"Gehwege werden bereitgestellt, wo Personal oder Ausrüstung die Aushebung überqueren müssen oder dürfen. Geländer müssen bereitgestellt werden, wenn Gehwege 4 ft/1,2 m über tiefer liegenden Ebenen liegen.","en":"Walkways are provided where personnel or equipment are required or permitted to cross the excavation. Guardrails must be provided when walkways are 4 feet /1.2 m above lower levels."}'::jsonb, '{"de":"Werden Gehwege bereitgestellt, wo Personal oder Ausrüstung die Aushebung überqueren müssen oder dürfen? Werden Geländer bereitgestellt, wenn Gehwege 4 ft/1,2 m über tiefer liegenden Ebenen liegen?","en":"Are walkways provided where personnel or equipment are required or permitted to cross the excavation? Are guardrails provided when walkways are 4 ft/1.2 m above lower levels?"}'::jsonb, false)
