insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/239', 'compliance@1', 239, null, 'loto', 'loto.1', '1.5', true, '{"de":"LOTO-Verfahren wird während Instandhaltungs- und/oder Wartungsarbeiten im normalen Produktionsbetrieb angewendet…","en":"LOTO procedure implemented during servicing and/or maintenance during normal production…"}'::jsonb, '{"de":"LOTO-Verfahren wird während Instandhaltungs- und/oder Wartungsarbeiten im normalen Produktionsbetrieb angewendet, wenn:\n- eine Person eine Schutzvorrichtung oder andere Sicherheitseinrichtung entfernen/umgehen muss\n- eine Person einen Körperteil in einen Bereich einer Maschine oder eines Ausrüstungsteils am Betriebspunkt bringen muss oder wo während eines Maschinenzyklus eine damit verbundene Gefahrenzone besteht.","en":"LOTO procedure implemented during servicing and/or maintenance during normal production  operations when:\n- An individual  is required to remove/bypass a guard or other safety device\n- An individual is required to place any part of his body into an area on a machine or piece of equipment at the point of operation or where an associated danger zone exists during a machine operating cycle."}'::jsonb, '{"de":"Wird das LOTO-Verfahren angewendet, wenn eine Person eine Schutzvorrichtung oder andere Sicherheitseinrichtung entfernen/umgehen muss oder ihren Körper während des Maschinenbetriebs in eine Gefahrenzone bringen muss?","en":"Is the LOTO procedure implemented when an individual is required to remove/bypass a guard or other safety device or place their body in a danger zone during machine operation?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/240', 'compliance@1', 240, null, 'loto', 'loto.1', '1.6', true, '{"de":"Wenn kein Verfahren oder Permit verwendet wird, sind die folgenden Elemente erfüllt: Maschine oder…","en":"If a procedure or permit is not used, the following elements are met: machine or…"}'::jsonb, '{"de":"Wenn kein Verfahren oder Permit verwendet wird, sind die folgenden Elemente erfüllt: Die Maschine oder Ausrüstung weist kein Potenzial für gespeicherte oder Restenergie auf; die Maschine oder Ausrüstung verfügt über eine einzige Energiequelle, die leicht identifiziert und isoliert werden kann; die Isolierung und Verriegelung dieser Energiequelle führt zu einer vollständigen Entenergetisierung und Deaktivierung der Maschine oder Ausrüstung; die Maschine oder Ausrüstung ist während der Instandhaltung oder Wartung von dieser Energiequelle isoliert und verriegelt; eine einzige Verriegelungsvorrichtung erreicht einen verriegelten Zustand; die Verriegelungsvorrichtung steht unter der ausschliesslichen Kontrolle der befugten Person, die die Instandhaltung oder Wartung durchführt; und die Instandhaltung oder Wartung schafft keine Gefährdungen für andere Personen.","en":"If a procedure or permit is not used, the following elements are met: machine or equipment has no potential for stored or residual energy; the machine or equipment has a single energy source which can be readily identified and isolated; the isolation and locking out of that energy source will completely deenergize and deactivate the machine or equipment; the machine or equipment is isolated from that energy source and locked out during servicing or maintenance; a single lockout device will achieve a locked out condition; the lockout device is under the exclusive control of the authorized personnel performing the servicing or maintenance; and the servicing or maintenance does not create hazards for other personnel."}'::jsonb, '{"de":"Erfüllt die Maschine, wenn kein Verfahren oder Permit verwendet wird, alle Bedingungen für einen sicheren Betrieb ohne LOTO? Besteht kein Potenzial für gespeicherte Energie? Ist die Energiequelle identifizierbar, isoliert und verriegelt? Steht die Verriegelungsvorrichtung unter der ausschliesslichen Kontrolle befugter Personen?","en":"If a procedure or permit is not used, does the machine meet all conditions for safe operation without LOTO? Is there no potential for stored energy? Is the energy source identifiable, isolated, and locked out? Is the lockout device under the exclusive control of authorized personnel?"}'::jsonb, false)
