insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/241', 'compliance@1', 241, null, 'loto', 'loto.1', '1.7', true, '{"de":"Wenn eine Energieisolierung nicht durch eine Verriegelungsvorrichtung erreicht werden kann, ist die Trennung der Energie…","en":"If energy isolation cannot be achieved by a lock out device, disconnection of the energy…"}'::jsonb, '{"de":"Wenn eine Energieisolierung nicht durch eine Verriegelungsvorrichtung erreicht werden kann, ist die Trennung der Energiequelle zu bevorzugen. Wenn die Trennung der Energiequelle andere erhebliche Gefährdungen schafft, kann Tagout mit zusätzlichen Sicherheitsmassnahmen verwendet werden, wie z. B. die Entfernung eines isolierenden Schaltungselements, das Blockieren eines Steuerschalters, das Öffnen einer zusätzlichen Trennvorrichtung oder die Entfernung eines Ventilgriffs. Zusätzliche Sicherheitsmassnahmen sind bewertet/vorhanden und auf dem Permit dokumentiert.","en":"If energy isolation cannot be achieved by a lock out device, disconnection of the energy source is preferred.  If disconnection of energy source creates other significant hazards, tag out may be used with additional safety measures such as removal of an isolating circuit element, blocking of a control switch, opening an extra disconnecting revice, or the removal of a valve handle. Additional safety measures assessed/in place and documented on permit."}'::jsonb, '{"de":"Wird, wenn eine Energieisolierung nicht durch eine Verriegelungsvorrichtung erreicht werden kann, die Trennung bevorzugt? Werden, wenn die Trennung Gefährdungen schafft, zusätzliche Sicherheitsmassnahmen bewertet, umgesetzt und dokumentiert?","en":"If energy isolation cannot be achieved by a lock out device, is disconnection preferred? If disconnection creates hazards, are additional safety measures assessed, in place, and documented?"}'::jsonb, false)
