insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/242', 'compliance@1', 242, null, 'loto', 'loto.1', '1.8', true, '{"de":"Verfahren oder Permit enthalten spezifische Verfahrensschritte für das Herunterfahren, Isolieren,…","en":"Procedures or permit include specific procedural steps for shutting down, isolating,…"}'::jsonb, '{"de":"Verfahren oder Permit enthalten spezifische Verfahrensschritte für das Herunterfahren, Isolieren, Blockieren und Sichern von Maschinen oder Ausrüstungen zur Kontrolle gefährlicher Energie; spezifische Schritte für das Anbringen, Entfernen und Übertragen von Lockout- oder Tagout-Vorrichtungen; die Identifizierung aller Stellen, an denen Energie abgeleitet oder gespeicherte Energie freigesetzt wurde; spezifische Anforderungen zum Testen einer Maschine oder Ausrüstung, um die Wirksamkeit von Lockout/Tagout-Vorrichtungen und anderen Kontrollmassnahmen zu bestimmen und zu verifizieren.","en":"Procedures or permit include specific procedural steps for shutting down, isolating, blocking and securing machines or equipment to control hazardous energy; specific steps for the placement, removal and transfer of lockout devices or tag out devices; identification of all points where energy has been disipated or stored energy released; specific requirements  for testing a machine or equipment to determine and verify the effectiveness of lockout/tagout devices and other control measures."}'::jsonb, '{"de":"Enthalten Verfahren oder Permits spezifische Schritte für das Herunterfahren, Isolieren, Blockieren und Sichern von Maschinen? Werden alle Stellen der Energieableitung identifiziert und auf ihre Wirksamkeit getestet?","en":"Do procedures or permits include specific steps for shutting down, isolating, blocking, and securing machines? Are all points of energy dissipation identified and tested for effectiveness?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/243', 'compliance@1', 243, null, 'loto', 'loto.1', '1.9', true, '{"de":"Lockout/Tagout-Vorrichtungen sind eindeutig identifiziert; die einzigen Vorrichtungen, die zur Kontrolle von…","en":"Lockout/tagout devices are singularly identified; the only devices used for controlling…"}'::jsonb, '{"de":"Lockout/Tagout-Vorrichtungen sind eindeutig identifiziert; sie sind die einzigen Vorrichtungen, die zur Energiekontrolle verwendet werden; sie dürfen nicht für andere Zwecke eingesetzt werden. Die Vorrichtungen sind so konstruiert und bedruckt, dass eine Verschlechterung durch die Umgebung, der sie ausgesetzt sind, verhindert wird. Die Vorrichtungen sind innerhalb des Betriebs standardisiert (Farbe, Form oder Grösse). Schlösser sind ausreichend robust, um ein Entfernen ohne übermässige Kraftanwendung zu verhindern. Anhänger enthalten Warnungen vor Gefahrenzuständen und Aufschriften wie: NICHT STARTEN. NICHT ÖFFNEN. NICHT BETÄTIGEN.","en":"Lockout/tagout devices are singularly identified; the only devices used for controlling energy; shall not be used for any other purposes. Devices are constructed and printed to prevent deterioration by environment to which they are subjected. Devices are standardized within the facility (color, shape, or size). Locks are substantial enough to prevent removal without excessive force. Tags include warnings against hazardous conditions and legends such as: DO NOT START. DO NOT OPEN. DO NOT OPERATE."}'::jsonb, '{"de":"Sind Lockout/Tagout-Vorrichtungen innerhalb des Betriebs standardisiert? Werden sie ausschliesslich zur Energiekontrolle verwendet? Enthalten sie Warnungen wie: NICHT STARTEN. NICHT ÖFFNEN. NICHT BETÄTIGEN?","en":"Are lockout/tagout devices standardized within the facility? Are they used exclusively for energy control? Do they include warnings such as: DO NOT START. DO NOT OPEN. DO NOT OPERATE?"}'::jsonb, false)
