values ('compliance@1/244', 'compliance@1', 244, null, 'loto', 'loto.1', '1.10', true, '{"de":"Lockout/Tagout-Vorrichtungen zeigen die Identität der Person an, die die Vorrichtung angebracht hat,…","en":"Lockout/tagout devices indicate the identity of the personnel applying the device,…"}'::jsonb, '{"de":"Lockout/Tagout-Vorrichtungen zeigen die Identität der Person an, die die Vorrichtung angebracht hat, eine Beschreibung der Arbeit und das Datum der Anbringung. Schlösser sind mit einem Anhänger mit diesen Informationen versehen.","en":"Lockout/tagout devices indicate the identity of the personnel applying the device, description of work, and date the device was applied. Locks are accompanied by tag with this information."}'::jsonb, '{"de":"Zeigen Lockout/Tagout-Vorrichtungen die Identität der Person an, die die Vorrichtung angebracht hat, eine Beschreibung der Arbeit und das Anbringungsdatum? Sind Schlösser mit Anhängern mit diesen Informationen versehen?","en":"Do lockout/tagout devices indicate the identity of the personnel applying the device, description of work, and date applied? Are locks accompanied by tags with this information?"}'::jsonb, false)
