values ('compliance@1/246', 'compliance@1', 246, null, 'loto', 'loto.1', '1.12', true, '{"de":"Betroffene Mitarbeitende werden vom Anlagenverantwortlichen oder einem autorisierten Mitarbeitenden über die…","en":"Affected personnel are notified by equipment owner or authorized employee of the…"}'::jsonb, '{"de":"Betroffene Mitarbeitende werden vom Anlagenverantwortlichen oder einem autorisierten Mitarbeitenden über das Anbringen und Entfernen von Lockout-Tagout (LOTO)-Vorrichtungen informiert.","en":"Affected personnel are notified by equipment owner or authorized employee of the application and removal of LOTO devices."}'::jsonb, '{"de":"Werden betroffene Mitarbeitende vom Anlagenverantwortlichen oder einem autorisierten Mitarbeitenden über das Anbringen und Entfernen von Lockout-Tagout (LOTO)-Vorrichtungen informiert?","en":"Are affected personnel notified by the equipment owner or an authorized employee of the application and removal of LOTO devices?"}'::jsonb, false)
