insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/247', 'compliance@1', 247, null, 'loto', 'loto.1', '1.13', true, '{"de":"Die Anwendung der Steuerungsmassnahme (LOTO) berücksichtigt die folgenden Elemente in der folgenden Reihenfolge: -…","en":"Application of control (LOTO) address the following elements in the following sequence: -…"}'::jsonb, '{"de":"Die Anwendung der Steuerungsmassnahme (LOTO) berücksichtigt die folgenden Elemente in der folgenden Reihenfolge:\n- Die autorisierte Person kennt die Art und das Ausmass der Energie, die Gefährdungen der zu kontrollierenden Energie sowie die Methode oder Mittel zu deren Kontrolle.\n- Die Maschine oder Anlage wird gemäss den bereits festgelegten Verfahren ausgeschaltet oder stillgelegt.\n- Alle zur Kontrolle der Energiezufuhr zur Maschine oder Anlage erforderlichen Energieisoliervorrichtungen sind physisch lokalisiert und so angewendet, dass die Maschine oder Anlage von der Energiequelle isoliert wird.\n- Lockout-Tagout (LOTO)-Vorrichtungen werden von jedem an der Aufgabe beteiligten autorisierten Mitarbeitenden an der Isoliervorrichtung angebracht. (Bei einer grossen Anzahl von Isolierpunkten können Schlosskästen verwendet werden.)\n- Jegliche potenziell gefährliche gespeicherte oder Restenergie wird entlastet, getrennt, zurückgehalten oder anderweitig gefahrlos gemacht.\n- Vor Beginn der Arbeiten hat der Anlagenverantwortliche überprüft, dass die Isolierung und Energiefreischaltung erfolgt ist, indem er versucht hat, die Anlage oder Maschine durch Betätigen der \"Ein\"-Taste zu starten und/oder überprüft hat, dass Entlüftungen, Ablässe, Blockierungen oder andere Vorrichtungen vorhanden sind, um die Isolierung zu bestätigen. Allen autorisierten Mitarbeitenden wird die Möglichkeit gegeben, die Isolierung zu überprüfen.","en":"Application of control (LOTO) address the following elements in the following sequence:\n- Authorized person has knowledge of the type and magnitude of energy, the hazards of the energy to be controlled, and the method or means to control the energy.\n- The machine or equipment shall be turned off or shut down using the procedures already established.\n- All energy isolating devices necessary to control the energy to the machine or equipment are physically located and applied in a way that isolates the machine or equipment from the energy source.\n- LOTO devices are affixed to the isolating device by each authorized employee involved in the task. (Lock boxes can be used for large numbers of isolating points)\n- All potentially hazardous stored or residual energy is relieved, disconnected, restrained, and otherwise rendered safe.\n- Prior to starting work, the equipment owner has verified that isolation and deenergization has been accomplished by \"trying\" to start the equipment or machine by activating \"on\" buttons and/or checking that vents, drains, blocks or other equipment is in place to verify isolation. All authorized employees have the opportunity to verify isolation."}'::jsonb, '{"de":"Folgt die Anwendung von Lockout Tagout (LOTO) der erforderlichen Reihenfolge, einschliesslich Gefährdungsbewusstsein, Abschaltverfahren, Energieisolierung und Verifizierung? Erhalten alle autorisierten Mitarbeitenden die Möglichkeit, die Isolierung zu überprüfen?","en":"Does the LOTO application follow the required sequence, including hazard awareness, shut down procedures, energy isolation, and verification? Are all authorized employees given the opportunity to verify isolation?"}'::jsonb, false)
