values ('compliance@1/248', 'compliance@1', 248, null, 'loto', 'loto.1', '1.14', true, '{"de":"Der Arbeitsbereich wird überprüft, um sicherzustellen, dass die Maschine/Anlage betriebsbereit ist,…","en":"Work area is inspected to ensure that machine/equipment is operationally intact,…"}'::jsonb, '{"de":"Der Arbeitsbereich wird überprüft, um sicherzustellen, dass die Maschine/Anlage betriebsbereit ist, das Personal sicher entfernt wurde und die Lockout-Tagout (LOTO)-Vorrichtungen vor der Freigabe von LOTO entfernt wurden.","en":"Work area is inspected to ensure that machine/equipment is operationally intact, personnel have been safely removed, and LOTO devices have been removed prior to release from LOTO."}'::jsonb, '{"de":"Wird der Arbeitsbereich überprüft, um sicherzustellen, dass die Maschine/Anlage betriebsbereit ist, das Personal sicher entfernt wurde und die Lockout-Tagout (LOTO)-Vorrichtungen vor der Freigabe entfernt wurden?","en":"Is the work area inspected to ensure the machine/equipment is operationally intact, personnel are safely removed, and LOTO devices have been removed before release?"}'::jsonb, false)
