values ('compliance@1/249', 'compliance@1', 249, null, 'loto', 'loto.1', '1.15', true, '{"de":"Lockout-Tagout (LOTO)-Vorrichtungen werden von der Person entfernt, die sie angebracht hat.","en":"LOTO devices are removed by the person who applied the device."}'::jsonb, '{"de":"Lockout-Tagout (LOTO)-Vorrichtungen werden von der Person entfernt, die sie angebracht hat.","en":"LOTO devices are removed by the person who applied the device."}'::jsonb, '{"de":"Werden Lockout-Tagout (LOTO)-Vorrichtungen nur von der Person entfernt, die sie angebracht hat?","en":"Are LOTO devices removed only by the person who applied them?"}'::jsonb, false)
