values ('compliance@1/250', 'compliance@1', 250, null, 'loto', 'loto.1', '1.16', true, '{"de":"Periodische Überprüfungen des Energiekontrollverfahrens werden mindestens jährlich durchgeführt,…","en":"Periodic inspections of the energy control procedure are conducted at least annually,…"}'::jsonb, '{"de":"Periodische Überprüfungen des Energiekontrollverfahrens werden mindestens jährlich durchgeführt, dokumentiert und 2 Jahre lang aufbewahrt. Die Überprüfungen werden von einem autorisierten Mitarbeitenden durchgeführt, der nicht an den überprüften Lockout-Tagout (LOTO)-Arbeiten beteiligt ist, und schliessen jede an der Aufgabe beteiligte autorisierte Person mit ein.","en":"Periodic inspections of the energy control procedure are conducted at least annually, documented, and retained for 2 years. Inspections are conducted by an authorized employee other than personnel involved in the LOTO work being inspected and include each authorized person involved in the job."}'::jsonb, '{"de":"Werden periodische Überprüfungen mindestens jährlich durchgeführt, dokumentiert und 2 Jahre lang aufbewahrt? Werden die Überprüfungen von einem autorisierten Mitarbeitenden durchgeführt, der nicht an den Arbeiten beteiligt ist?","en":"Are periodic inspections conducted at least annually, documented, and retained for 2 years? Are inspections performed by an authorized employee not involved in the work?"}'::jsonb, false)
