values ('compliance@1/253', 'compliance@1', 253, null, 'explosion_protection', 'explosion_protection.1', '1.1', true, '{"de":"\"Der Standort muss einen Plan zur Ex-Zonen-Einteilung erstellen, der Folgendes umfasst: - Daten für…\"","en":"The site shall establish an Hazardous Area Classification Plan including: - data for…"}'::jsonb, '{"de":"Der Standort muss einen Plan zur Ex-Zonen-Einteilung erstellen, der Folgendes umfasst:\n- Daten für brennbare Flüssigkeiten, Gase und brennbare Stäube\n- Zoneneinteilung\n- Teilnehmer müssen über Kenntnisse zur Ex-Klassifizierung verfügen und mit Maschinen und Substanzen vertraut sein","en":"The site shall establish an Hazardous Area Classification Plan including:\n- data for flammable liquids, gases and combustible powders\n- zone classification\n- participant must have knowledge about Ex classification and be familiar with machineries and substances"}'::jsonb, '{"de":"Wurde ein Plan zur Ex-Zonen-Einteilung erstellt? Enthält er Daten zu brennbaren Substanzen, die Zoneneinteilung und Kenntnisse des Personals zur Ex-Klassifizierung?","en":"Has a Hazardous Area Classification Plan been established? Does it include data for flammable substances, zone classification, and personnel knowledge of Ex classification?"}'::jsonb, false)
