insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/254', 'compliance@1', 254, null, 'explosion_protection', 'explosion_protection.1', '1.2', true, '{"de":"\"Der Standort muss ein Explosionsschutzdokument erstellen, das Folgendes umfasst: - Daten zu Gebäude,…\"","en":"The site shall establish an Explosion Protection Document including: - data on building,…"}'::jsonb, '{"de":"Der Standort muss ein Explosionsschutzdokument erstellen, das Folgendes umfasst:\n- Daten zu Gebäude, Anlage und Prozessen\n- Ex-Zonenplan und Erdungsplan\n- mögliche Zündquellen\n- Wartung von Ex-Ausrüstung\n- Schutzmassnahmen (explosionsdruckfest, Lüftungssystem, Ex-Kennzeichnungen, Schulung, PSA)\n- Notfallschutzmassnahmen\n- Feststellungen und Massnahmenplan\n- Genehmigung durch den Standortleiter","en":"The site shall establish an Explosion Protection Document including:\n- data on building, installation and processes\n- Ex zone map and grounding map\n- possible ignition sources\n- maintenance of Ex equipment\n- control measures (explosion pressure resistant, ventilation system, Ex signs, training, PPE)\n- emergency protection measures\n- findings and action plan\n- approval by site manager"}'::jsonb, '{"de":"Wurde ein Explosionsschutzdokument erstellt? Enthält es Daten zu Gebäude und Anlage, Ex-Zonen- und Erdungspläne, Zündquellen, Wartung von Ex-Ausrüstung, Schutzmassnahmen, Notfallmassnahmen, Feststellungen, Massnahmenpläne und die Genehmigung des Standortleiters?","en":"Has an Explosion Protection Document been established? Does it include building and installation data, Ex zone and grounding maps, ignition sources, maintenance of Ex equipment, control measures, emergency measures, findings, action plans, and site manager approval?"}'::jsonb, false)
