insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/255', 'compliance@1', 255, null, 'explosion_protection', 'explosion_protection.1', '1.3', true, '{"de":"\"Der Standort muss gute Praktiken hinsichtlich Elektrostatik anwenden, einschliesslich: - Erdung und…\"","en":"The site shall have good practices in regards to electrostatic including: - grounding and…"}'::jsonb, '{"de":"Der Standort muss gute Praktiken hinsichtlich Elektrostatik anwenden, einschliesslich:\n- Erdung und Potentialausgleich aller leitfähigen Teile von Ausrüstung, Anlage und Verpackungen\n- periodische Überprüfung durch das Wartungsteam\n- ein Erdungsplan muss verfügbar sein\n- in Ex-Zonen muss der Boden leitfähig sein (Erdungswiderstand kleiner als 10 Ohm)\n- in Ex-Zonen müssen Mitarbeitende leitfähige Sicherheitsschuhe und leitfähige Kleidung tragen\n- Mitarbeitende müssen im Verständnis elektrostatischer Gefährdungen geschult sein\n- Verwendung funkenfreier Werkzeuge in Ex-Zonen (Bürste, Schraubenzieher, Staubsauger, ...)","en":"The site shall have good practices in regards to electrostatic including:\n- grounding and bonding of all conductive parts of equipment, installation and packages\n- periodical check shall be performed by maintenance team\n- a grounding map shall be available\n- in Ex Zones the floor shall be conductive (resistance to ground less than 10 Ohm)\n- in Ex Zone, employees shall wear conductive safety shoes and wear conductive clothing\n- employees shall be trained in understanding electrostatic hazards\n- use of spark free tools in Ex Zones (brush, screwdriver, vacuum cleaner, ...)"}'::jsonb, '{"de":"Sind gute Praktiken für Elektrostatik vorhanden? Werden Erdungs- und Potentialausgleichsprüfungen durchgeführt? Ist ein Erdungsplan verfügbar? Sind die Böden in Ex-Zonen leitfähig? Tragen Mitarbeitende leitfähige Schutzausrüstung und werden sie zu elektrostatischen Gefährdungen geschult? Werden funkenfreie Werkzeuge verwendet?","en":"Are good practices for electrostatics in place? Are grounding and bonding checks performed? Is a grounding map available? Are Ex zone floors conductive? Do employees wear conductive safety gear and receive training on electrostatic hazards? Are spark-free tools used?"}'::jsonb, false)
on conflict (id) do update set version_key = excluded.version_key, position = excluded.position, parent_id = excluded.parent_id, section_key = excluded.section_key, group_key = excluded.group_key, label = excluded.label, rateable = excluded.rateable, title = excluded.title, requirement = excluded.requirement, question = excluded.question, de_reviewed = excluded.de_reviewed;
insert into public.questionnaire_items (id, version_key, position, parent_id, section_key, group_key, label, rateable, title, requirement, question, de_reviewed)
values ('compliance@1/256', 'compliance@1', 256, null, 'explosion_protection', 'explosion_protection.1', '1.4', true, '{"de":"\"Der Standort muss gute Praktiken in Ex-Zonen anwenden, einschliesslich: - Alle Ex-Zonen müssen…\"","en":"The site shall have good practices in Ex Zones including: - All Ex zones shall be…"}'::jsonb, '{"de":"Der Standort muss gute Praktiken in Ex-Zonen anwenden, einschliesslich:\n- Alle Ex-Zonen müssen mit geeigneter Beschilderung und Kennzeichnung versehen sein, ein Stickstoff-Schild muss angebracht sein, um Erstickung zu vermeiden\n- Nur Ex-zugelassene elektrische Ausrüstung mit Ex-Kennzeichnung und Zertifikat darf in Ex-Zonen verwendet werden\n- Das Lüftungssystem in Ex-Zonen muss durch die Wartung instand gehalten werden, und bei Ausfall der Lüftung muss ein Alarmsystem verfügbar sein\n- Alle Ausrüstung in Ex-Zonen muss für die Wartung als sicherheitskritisch eingestuft werden\n- keine Arbeiten mit offener Flamme\n- Rauchverbote müssen strikt eingehalten werden","en":"The site shall have good practices in Ex Zones including:\n- All Ex zones shall be labelled with proper signage and marking, Nitrogen sign shall be displayed to avoid suffocation\n- Only Ex approved electrical equipment, with Ex sign and certificate shall be used in Ex Zones\n- Ventilation system in Ex Zones shall be serviced by maintenance and an alarm system shall be available in case the ventilation fail\n- All equipment in Ex Zones shall be classified as safety critical for maintenance\n- no open flames activities\n- non smoking rules followed strictly"}'::jsonb, '{"de":"Sind gute Praktiken in Ex-Zonen umgesetzt? Sind Ex-Zonen ordnungsgemäss mit Beschilderung und Stickstoff-Warnhinweisen gekennzeichnet? Wird nur Ex-zugelassene elektrische Ausrüstung verwendet? Wird die Lüftung gewartet und ist ein Alarmsystem vorhanden? Ist die Ausrüstung in Ex-Zonen als sicherheitskritisch eingestuft? Sind offene Flammen und Rauchen strikt verboten?","en":"Are good practices in Ex Zones implemented? Are Ex zones properly labeled with signage and Nitrogen warnings? Is only Ex-approved electrical equipment used? Is ventilation maintained with an alarm system? Are Ex Zone equipment classified as safety critical? Are open flames and smoking strictly prohibited?"}'::jsonb, false)
