values ('compliance@1/262', 'compliance@1', 262, null, 'mechanical_integrity', 'mechanical_integrity.1', '1.1', true, '{"de":"Ist ein schriftliches Programm zur Aufrechterhaltung der mechanischen Integrität vorhanden, das Folgendes umfasst: -…","en":"Is a written Mechanical Integrity Program in place that includes the following: -…"}'::jsonb, '{"de":"Ist ein schriftliches Programm zur Aufrechterhaltung der mechanischen Integrität vorhanden, das Folgendes umfasst:\n- Druckbehälter und Lagertanks?\n- Rohrleitungssysteme und -komponenten?\n- Entlastungs- und Entlüftungssysteme und -vorrichtungen?\n- Notabschaltsysteme?\n- Steuerungen (einschliesslich Überwachungsgeräte, Sensoren, Alarme und Verriegelungen)?\n- Pumpen?","en":"Is a written Mechanical Integrity Program in place that includes the following:\n- Pressure Vessels and Storage Tanks?\n- Piping Systems and Components?\n- Relief and Vent Systems and Devices?\n- Emergency Shutdown Systems?\n- Controls (including monitoring devices, sensors, alarms and  interlocks)?\n- Pumps?"}'::jsonb, '{"de":"Gibt es ein schriftliches Programm zur Aufrechterhaltung der mechanischen Integrität, das Druckbehälter, Lagertanks, Rohrleitungen, Entlastungs- und Entlüftungssysteme, Notabschaltungen, Steuerungen und Pumpen abdeckt?","en":"Is there a written Mechanical Integrity Program covering pressure vessels, storage tanks, piping, relief and vent systems, emergency shutdowns, controls, and pumps?"}'::jsonb, false)
