values ('compliance@1/273', 'compliance@1', 273, null, 'mechanical_integrity', 'mechanical_integrity.2', '2.7', true, '{"de":"Umfasst die Dokumentation jeder Inspektion und Prüfung für jedes Gerät…","en":"Does the documentation of each inspection and test for each piece of equipment include…"}'::jsonb, '{"de":"Umfasst die Dokumentation jeder Inspektion und Prüfung für jedes Gerät Folgendes:\n- Datum der Inspektion/Prüfung?\n- Name des Inspektors/Prüfers?\n- Geräteidentifikation/Seriennummer?\n- Beschreibung der Inspektion/Prüfung?\n- Ergebnisse der Inspektion/Prüfung?","en":"Does the documentation of each inspection and test for each piece of equipment include the following:\n- Date of Inspection/Test?\n- Name of the Inspector/Tester?\n- Equipment Identification/Serial Number?\n- Description of Inspection/Test?\n- Results of Inspection/Test?"}'::jsonb, '{"de":"Umfasst die Inspektions-/Prüfdokumentation das Datum, den Namen des Inspektors, die Geräte-ID, die Prüfbeschreibung und die Ergebnisse?","en":"Does inspection/test documentation include the date, inspector name, equipment ID, test description, and results?"}'::jsonb, false)
