values ('compliance@1/280', 'compliance@1', 280, null, 'moc_pssr', 'moc_pssr.1', '1.2', true, '{"de":"Stellen das Verfahren für das Änderungsmanagement und das Formular zur Änderungsfreigabe sicher, dass vor…","en":"Does the Management of Change Procedure and Change Authorization Form assure that, prior…"}'::jsonb, '{"de":"Stellen das Verfahren für das Änderungsmanagement und das Formular zur Änderungsfreigabe sicher, dass vor der Änderung Folgendes berücksichtigt wird:\n- Technische Grundlage für die Änderung?\n- Auswirkung der Änderung auf Sicherheit und Gesundheit?\n- Anpassung der Betriebsverfahren?\n- Erforderlicher Zeitraum für die Änderung?\n- Ordnungsgemässe Genehmigungen?","en":"Does the Management of Change Procedure and Change Authorization Form assure that, prior to the change, the following are addressed:\n- Technical Basis for Change?\n- Impact of Change on Safety and Health?\n- Modification to Operating Procedures?\n- Necessary Time Period for Change?\n- Proper Authorizations?"}'::jsonb, '{"de":"Enthält das Verfahren für das Änderungsmanagement Anforderungen zur Beurteilung der technischen Grundlage, der Auswirkungen auf Sicherheit und Gesundheit, der Anpassungen der Verfahren, des Zeitraums und der ordnungsgemässen Genehmigungen, bevor Änderungen vorgenommen werden?","en":"Does the Management of Change Procedure include requirements to assess technical basis, safety and health impact, modifications to procedures, time period, and proper authorizations before changes are made?"}'::jsonb, false)
