values ('compliance@1/298', 'compliance@1', 298, null, 'incident_investigation', 'incident_investigation.1', '1.8', true, '{"de":"Enthalten die Vorfalluntersuchungsberichte Folgendes: - Datum des Vorfalls?","en":"Do the Incident Investigation Reports include the following: - Date of the Incident?"}'::jsonb, '{"de":"Enthalten die Vorfalluntersuchungsberichte Folgendes:\n- Datum des Vorfalls?\n- Datum des Beginns der Untersuchung (Inspection)?\n- Eine Beschreibung des Vorfalls?\n- Ermittlung der beitragenden Faktoren?\n- Daraus resultierende Empfehlungen?\n- Ordnungsgemässe Genehmigungen und Unterschriften?","en":"Do the Incident Investigation Reports include the following:\n- Date of the Incident?\n- Date the inspection (Investigation) began?\n- A description of the incident?\n- Identification of contributing factors?\n- Resulting recommendations?\n- Proper approvals and signatures?"}'::jsonb, '{"de":"Enthalten die Vorfalluntersuchungsberichte Folgendes:\n- Datum des Vorfalls?\n- Datum des Beginns der Untersuchung?\n- Detaillierte Beschreibung des Vorfalls?\n- Ermittlung der beitragenden Faktoren?\n- Empfehlungen für Korrekturmassnahmen?\n- Ordnungsgemässe Genehmigungen und Unterschriften?","en":"Do the Incident Investigation Reports contain the following:\n- Date of the incident?\n- Date the investigation began?\n- Detailed description of the incident?\n- Identification of contributing factors?\n- Recommendations for corrective actions?\n- Proper approvals and signatures?"}'::jsonb, false)
